window.PORTFOLIO_TEMPLATE = "<!doctype html>\n<html lang=\"en\"><head>\n<meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"description\" content=\"Here is where you can see a compiled showcase of some of the projects I've worked on and how I made them.\"><title>Owen Sheetz — Engineering Portfolio</title>\n<style>\n:root{--ink:#153033;--muted:#596c6e;--paper:#f5f4ee;--line:#d3d9d3;--accent:#b9ed76}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:24px}body{margin:0;background:var(--paper);color:var(--ink);font-family:Arial,Helvetica,sans-serif;line-height:1.6}a{color:inherit}a:focus-visible,summary:focus-visible{outline:3px solid #507b19;outline-offset:5px}.wrap{width:min(1160px,90%);margin:auto}header{padding:26px 0;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}header a{text-decoration:none;font-size:14px}nav{display:flex;gap:26px}.brand{font-weight:700;letter-spacing:-.5px;font-size:20px}small,.eyebrow{font-family:monospace;letter-spacing:1.5px;text-transform:uppercase;font-size:12px}.hero{padding:100px 0 80px;display:grid;grid-template-columns:1.2fr 1fr;gap:55px;align-items:center}h1{font-size:clamp(44px,6.2vw,78px);line-height:1.05;letter-spacing:-4px;margin:22px 0}h1 span{color:#6b8580}h2{font-size:clamp(30px,4vw,46px);letter-spacing:-1.8px;line-height:1.15}h3{font-size:23px;line-height:1.25;letter-spacing:-.6px}.intro{font-size:19px;max-width:530px;color:var(--muted)}.button{display:inline-flex;text-decoration:none;background:var(--ink);color:white;padding:13px 22px;border-radius:3px;margin-top:20px;gap:25px}.visual{background:#163b3d;border-radius:4px;padding:28px;position:relative;color:#cce2ce;overflow:hidden}.visual svg{display:block;width:100%;height:auto}.visual small{font-size:10px}.visual .caption{display:flex;justify-content:space-between;gap:10px}.section{padding:65px 0;border-top:1px solid var(--line)}.sectionhead{display:flex;justify-content:space-between;align-items:baseline;gap:20px;margin-bottom:30px}.sectionhead h2{margin:0}.feature{background:white;border:1px solid var(--line);padding:40px;display:grid;grid-template-columns:1fr 1fr;gap:45px}.feature h3{font-size:35px;margin:15px 0 20px}.tags{display:flex;gap:8px;flex-wrap:wrap;margin:24px 0}.tag{font:12px monospace;border:1px solid var(--line);padding:6px 9px;border-radius:3px}.fact{border-top:1px solid var(--line);padding:17px 0}.fact strong{display:block;font-size:15px}.fact p{margin:5px 0;color:var(--muted);font-size:15px}details{margin-top:26px;border-top:1px solid var(--line);padding-top:20px}summary{cursor:pointer;font-weight:700}details p{color:var(--muted)}.projects{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:22px}.project{padding:27px;border:1px solid var(--line);min-height:215px}.project h3{margin:32px 0 16px}.project p{color:var(--muted);font-size:14px}.number{font:12px monospace;color:var(--muted)}.about{display:grid;grid-template-columns:1fr 1fr;gap:60px}.about p{color:var(--muted);font-size:18px}.disciplines{display:flex;gap:20px;flex-wrap:wrap;font:13px monospace;margin-top:25px}footer{border-top:1px solid var(--line);padding:24px 0 35px;display:flex;justify-content:space-between;color:var(--muted);font-size:12px}.note{font:12px monospace;color:var(--muted)}@media(max-width:760px){.hero{grid-template-columns:1fr;padding:55px 0;gap:30px}h1{letter-spacing:-2px}.feature,.about{grid-template-columns:1fr;padding:25px;gap:20px}.about{padding:0}.projects{grid-template-columns:1fr}.sectionhead{align-items:start;flex-direction:column;gap:10px}.section{padding:45px 0}nav{gap:16px}.visual{max-width:500px}footer{gap:20px;flex-wrap:wrap}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}\n</style>\n<style id=\"project-layout-style\">\n    .hero{padding:85px 0 65px;grid-template-columns:1.35fr .8fr;gap:75px}\n    h1{font-size:clamp(44px,5.4vw,72px)}h1 span{font-size:.65em;letter-spacing:-2px;display:inline-block;margin-top:20px;line-height:1.2}\n    .profile-visual{padding:30px 34px;background:var(--ink);color:var(--paper)}\n    .profile-monogram{font-size:100px;line-height:1.2;letter-spacing:-7px;margin:32px 0 38px;color:var(--accent)}\n    .profile-interests>div{display:flex;gap:22px;align-items:center;padding:14px 0;border-top:1px solid #ffffff25}\n    .profile-interests span{font:11px monospace;color:var(--accent)}.profile-interests strong{font-size:16px;font-weight:400}\n    #about{padding-top:48px;padding-bottom:55px}#about h2{font-size:32px;margin-top:18px}#about p{margin-top:0}\n    .project-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;align-items:start}\n    .project-grid>.projects{display:contents}\n    details.project-disclosure{margin:0;padding:0;border:1px solid var(--line);background:#ffffff6b;min-height:0;border-radius:4px;overflow:hidden}\n    .project-disclosure>summary{position:relative;list-style:none;display:block;padding:30px 60px 30px 30px;cursor:pointer;font-weight:400}\n    .project-disclosure>summary::-webkit-details-marker{display:none}\n    .project-disclosure>summary::after{content:'+';position:absolute;right:27px;top:30px;font-size:26px;line-height:1;color:var(--muted)}\n    .project-disclosure[open]>summary::after{content:'−'}\n    .project-disclosure>summary:hover{background:#ffffff}\n    .project-disclosure .card-title{font-size:26px;line-height:1.25;margin:25px 0 18px;letter-spacing:-.8px}\n    .card-prompt{font:12px monospace;color:var(--muted)}\n    .project-disclosure[open]{grid-column:1/-1}\n    .project-disclosure[open]>summary{border-bottom:1px solid var(--line)}\n    .project-disclosure .feature{border:0;background:transparent;padding:30px;gap:30px}\n    .project-body{padding:5px 30px 30px}.project-body p{font-size:17px;white-space:pre-line;max-width:800px}\n    .project-body img{max-width:800px;height:auto!important;max-height:450px;object-fit:contain!important}\n    .project-link{display:inline-block;margin-top:10px;font-size:14px}\n    @media(max-width:760px){.hero{grid-template-columns:1fr;gap:30px;padding:50px 0}.profile-visual{padding:22px 28px}.profile-monogram{font-size:72px;margin:18px 0 24px}.project-grid{grid-template-columns:1fr}.project-disclosure>summary{padding:24px 55px 24px 24px}.project-disclosure .feature{padding:24px}.project-body{padding:5px 24px 24px}h1 span{letter-spacing:-1px}#about h2{font-size:28px}}\n  </style><style id=\"portfolio-editor-colors\">:root{--ink:#153033;--paper:#f5f4ee;--muted:#596c6e;--line:#d3d9d3;--accent:#b9ed76}h1 span{color:var(--muted)}.visual svg [stroke=\"#b9ed76\"]{stroke:var(--accent)}.visual svg [fill=\"#b9ed76\"]{fill:var(--accent)}.projects:empty{display:none}</style></head>\n<body><div class=\"wrap\">\n<header><a class=\"brand\" href=\"#top\">Owen Sheetz<span style=\"color: rgb(185, 237, 118);\">.</span></a><nav aria-label=\"Main navigation\"><a href=\"#projects\">Projects</a><a href=\"#about\">About</a></nav></header>\n<main id=\"top\">\n<section class=\"hero\"><div><div class=\"eyebrow\">Electrical / Optics / Controls</div><h1>Owen Sheetz.<br><span>I make cool stuff</span></h1><p class=\"intro\">Here is where you can see a compiled showcase of some of the projects I've worked on and how I made them.</p><a class=\"button\" href=\"#projects\">Explore my projects <span aria-hidden=\"true\">â†—</span></a></div>\n<div class=\"visual profile-visual\"><small>Engineering interests</small><div class=\"profile-monogram has-cover\"><img src=\"data:image/jpeg;base64,\" alt=\"Owen Sheetz\" class=\"about-cover\"></div><div class=\"profile-interests\"><div><span>01</span><strong>Electrical</strong></div><div><span>02</span><strong>Optics</strong></div><div><span>03</span><strong>Controls</strong></div></div></div></section>\n<section id=\"about\" class=\"section about\"><div><div class=\"eyebrow\">About Owen</div><h2>I'm currently pursuing an MS in Optics from the University of Rochester and doing research at the Laboratory for Laser Energetics. <br><br>My career interests are in Fusion Energy and Aerospace. On the side I like to build whatever spikes my curiousity.</h2></div><div><p>I grew up in San Francisco, and was always interested in science. My early life was influenced by Mythbusters, Cosmos, the Academy of Science, XKCD and Randall Munroe's What If?. \n\nI went to Cal Poly Pomona for Physics and participated in and led the Formula SAE Electric team. Later, I did research at CERN. After graduating, I did an internship for Lockheed Martin Space before beginning my MS at UR.\n\nI like riding my electric skateboard, mechanical watches, sailing, and camping.</p><div class=\"disciplines\"><span>01 Electrical</span><span>02 Optics</span><span>03 Controls</span></div></div></section><section id=\"projects\" class=\"section\"><div class=\"sectionhead\"><h2>Selected projects</h2><small>From control loops to light</small></div>\n\n<div class=\"project-grid\"><details class=\"project-disclosure featured-card\" id=\"reaction-wheel-project\"><summary><span class=\"number\">01 / CONTROLS + ELECTRONICS</span><h3 class=\"card-title\">Self-Balancing Reaction Wheel Cube</h3><span class=\"card-prompt\">Explore project</span></summary><article class=\"feature\"><div><div class=\"eyebrow\">01 / Featured project</div><h3>Self-Balancing<br>Reaction Wheel Cube</h3><p>6 inch weighted reaction wheel, 3d printed housing, gimbal motor and FOC control. The balance controller uses 3 nested PID loop.</p><div class=\"tags\"><span class=\"tag\">ESP32</span><span class=\"tag\">C++</span><span class=\"tag\">PID Control</span><span class=\"tag\">BNO085 IMU</span><span class=\"tag\">SimpleFOC</span><span class=\"tag\">Brushless DC Motors</span><span class=\"tag\">3D Printing</span></div><a href=\"#cube-details\">Read the engineering details â†“</a></div><div><div class=\"fact\"><strong>Sense the orientation</strong><p>A BNO085 inertial measurement unit measures the cube's orientation. Sensor filtering supports the feedback loop.</p></div><div class=\"fact\"><strong>Control the reaction wheel</strong><p>I simulated the reaction wheel in simulink and used realistic parameters to test control loop design and PID tuning. At t=5s, the simulation gives a kick to the cube to test its resiliency to disturbance.</p></div><div class=\"fact\"><strong>Recover and explore</strong><p>Motor speed regulation and automatic recovery behavior improve stability. Further exploration uses rapid acceleration and braking to investigate jumping and balance recovery.</p></div></div>\n<figure style=\"grid-column:1/-1;margin:0;border-top:1px solid var(--line);padding-top:28px\">\n<div class=\"eyebrow\" style=\"margin-bottom:16px\">Control system simulation / MATLAB + Simulink</div>\n<video controls=\"\" playsinline=\"\" preload=\"metadata\" poster=\"assets/reaction-wheel-poster.png\" aria-label=\"Self-Balancing Reaction Wheel Cube simulation\" aria-describedby=\"simulation-caption\" style=\"display:block;width:100%;max-width:960px;height:auto;background:#fff;border:1px solid var(--line);border-radius:4px\">\n<source src=\"assets/reaction-wheel-simulation.mp4\" type=\"video/mp4\">\nYour browser does not support embedded video. <a href=\"assets/reaction-wheel-simulation.mp4\">Download the simulation video</a>.\n</video>\n<figcaption id=\"simulation-caption\" style=\"margin-top:14px;color:var(--muted);font-size:14px\">I simulated the reaction wheel in simulink and used realistic parameters to test control loop design and PID tuning. At t=5s, the simulation gives a kick to the cube to test its resiliency to disturbance.</figcaption>\n<p style=\"margin-bottom:0;font-size:13px\"><a href=\"assets/reaction-wheel-simulation.mp4\" download=\"\">Download simulation video (MP4)</a></p>\n</figure>\n<figure id=\"cube-photo\" style=\"grid-column: 1 / -1; margin: 0px;\"><img src=\"data:image/jpeg;base64,\" alt=\"Reaction wheel cube prototype\" style=\"width: 100%; max-height: 600px; object-fit: contain; display: block; border-radius: 4px;\"></figure><div id=\"cube-details\" style=\"grid-column:1/-1\"><details><summary>Inside the design and control system</summary><p>I designed and built the cube around an ESP32 microcontroller, BNO085 IMU, and GM4108H-120T Gimbal Motor with a built in encoder. The motor is controlled with the MKS ESP32 FOC board and powered by a 3s 300mah toothpick LiHV battery which gives plenty of runtime. Code is written mostly with GPT-5.5, control loop design and PID parameters chosen by me through repeated trial and error.</p><p>The controller uses 3 nested PID loops. The first loop uses the IMU to measure the position and rotational velocity relative to the set balance point.</p><p>The second loop allows the set balance point to be changed by up to 3 deg as the wheel speed increases. This loop attempts to prevent the wheelspeed from reaching saturation by throwing the balance point in the opposite direction and then bleeding off the extra wheel speed. This loop has to tradeoff between a low wheelspeed target and strong disturbance rejection.</p><p>The final control loop allows the maximum allowable balance point offset to be controllable. High max balance point offset allows large disturbance rejection but causes vibration during normal operation. Low max balance point offset allows smoother operation but low disturbance rejection. The third control loop allows the max balance point to go up if there is a large disturbance, and reduce as the disturbance is mitigated.</p></details></div></article></details><div class=\"projects\"><details class=\"project project-disclosure\"><summary><span class=\"number\">02 / OPTICS + ELECTRONICS</span><h3 class=\"card-title\">Laser Communications System</h3><span class=\"card-prompt\">Explore project</span></summary><div class=\"project-body\"><img src=\"data:image/jpeg;base64,\" alt=\"Laser Communications System\" loading=\"lazy\" style=\"width: 100%; height: 170px; object-fit: cover; display: block; margin-top: 20px; border-radius: 3px;\"><p>Project documentation coming soon.</p></div></details><details class=\"project project-disclosure\"><summary><span class=\"number\">03 / OPTICS + SIGNALS</span><h3 class=\"card-title\">Laser Microphone</h3><span class=\"card-prompt\">Explore project</span></summary><div class=\"project-body\"><p>Project documentation coming soon.</p></div></details><details class=\"project project-disclosure\"><summary><span class=\"number\">04 / OPTICAL DESIGN</span><h3 class=\"card-title\">Adjustable Polarizing Sunglasses</h3><span class=\"card-prompt\">Explore project</span></summary><div class=\"project-body\"><p>Project documentation coming soon.</p></div></details><details class=\"project project-disclosure\"><summary><span class=\"number\">05 / Electrical Engineering</span><h3 class=\"card-title\">Adders</h3><span class=\"card-prompt\">Explore project</span></summary><div class=\"project-body\"><p>Full and Half Adder circuits made from 2N2222 Transistors</p></div></details></div></div></section>\n\n<section class=\"section\" id=\"portfolio-contact\"><small>Get in touch</small><h2>Let’s connect.</h2><div style=\"display: flex; flex-wrap: wrap; gap: 18px; margin-top: 20px;\"><a data-contact=\"email\" href=\"mailto:osheetz@ur.rochester.edu\">Email</a><a data-contact=\"linkedin\" href=\"www.linkedin.com/in/owen-sheetz-157523268\" target=\"_blank\" rel=\"noopener noreferrer\">LinkedIn</a><a data-contact=\"resume\" href=\"data:application/pdf;base64,\" download=\"Owen-Sheetz-Resume.pdf\">Resume</a></div></section></main><footer><span>© 2026 Owen Sheetz</span><span>Personal engineering portfolio</span></footer></div>\n</body></html>";
window.PORTFOLIO_SAVED_STATE = {"name":"Owen Sheetz","disciplines":"Electrical / Optics / Controls","headline":"Owen Sheetz.","headlineAccent":"I make cool stuff","intro":"Here is where you can see a compiled showcase of some of the projects I've worked on and how I made them.","aboutHeading":"I'm currently pursuing an MS in Optics from the University of Rochester and doing research at the Laboratory for Laser Energetics. \n\nMy career interests are in Fusion Energy and Aerospace. On the side I like to build whatever spikes my curiousity.","aboutText":"I grew up in San Francisco, and was always interested in science. My early life was influenced by Mythbusters, Cosmos, the Academy of Science, XKCD and Randall Munroe's What If?. \n\nI went to Cal Poly Pomona for Physics and participated in and led the Formula SAE Electric team. Later, I did research at CERN. After graduating, I did an internship for Lockheed Martin Space before beginning my MS at UR.\n\nI like riding my electric skateboard, mechanical watches, sailing, and camping.","email":"osheetz@ur.rochester.edu","github":"","linkedin":"www.linkedin.com/in/owen-sheetz-157523268","resume":"data:application/pdf;base64,","cubeTitle":"Self-Balancing\nReaction Wheel Cube","cubeSummary":"6 inch weighted reaction wheel, 3d printed housing, gimbal motor and FOC control. The balance controller uses 3 nested PID loop.","cubeTags":"ESP32, C++, PID Control, BNO085 IMU, SimpleFOC, Brushless DC Motors, 3D Printing","facts":[{"title":"Sense the orientation","body":"A BNO085 inertial measurement unit measures the cube's orientation. Sensor filtering supports the feedback loop."},{"title":"Control the reaction wheel","body":"I simulated the reaction wheel in simulink and used realistic parameters to test control loop design and PID tuning. At t=5s, the simulation gives a kick to the cube to test its resiliency to disturbance."},{"title":"Recover and explore","body":"Motor speed regulation and automatic recovery behavior improve stability. Further exploration uses rapid acceleration and braking to investigate jumping and balance recovery."}],"detailsHeading":"Inside the design and control system","cubeDetails":"I designed and built the cube around an ESP32 microcontroller, BNO085 IMU, and GM4108H-120T Gimbal Motor with a built in encoder. The motor is controlled with the MKS ESP32 FOC board and powered by a 3s 300mah toothpick LiHV battery which gives plenty of runtime. Code is written mostly with GPT-5.5, control loop design and PID parameters chosen by me through repeated trial and error.\n\nThe controller uses 3 nested PID loops. The first loop uses the IMU to measure the position and rotational velocity relative to the set balance point. \n\nThe second loop allows the set balance point to be changed by up to 3 deg as the wheel speed increases. This loop attempts to prevent the wheelspeed from reaching saturation by throwing the balance point in the opposite direction and then bleeding off the extra wheel speed. This loop has to tradeoff between a low wheelspeed target and strong disturbance rejection. \n\nThe final control loop allows the maximum allowable balance point offset to be controllable. High max balance point offset allows large disturbance rejection but causes vibration during normal operation. Low max balance point offset allows smoother operation but low disturbance rejection. The third control loop allows the max balance point to go up if there is a large disturbance, and reduce as the disturbance is mitigated. ","cubeImage":"data:image/jpeg;base64,","cubeImageAlt":"Reaction wheel cube prototype","videoSrc":"assets/reaction-wheel-simulation.mp4","videoPoster":"assets/reaction-wheel-poster.png","videoCaption":"I simulated the reaction wheel in simulink and used realistic parameters to test control loop design and PID tuning. At t=5s, the simulation gives a kick to the cube to test its resiliency to disturbance.","showVideo":true,"projects":[{"title":"Laser Communications System","category":"OPTICS + ELECTRONICS","description":"Project documentation coming soon.","image":"data:image/jpeg;base64,","imageAlt":"","link":"","id":"laser-communications-system","blocks":[{"type":"code","heading":"Code","files":[{"filename":"servo_find_receive.ino","language":"Arduino / C++","code":"#include <HardwareSerial.h>\r\n#include <Wire.h>\r\n#include <Adafruit_GFX.h>\r\n#include <Adafruit_SSD1306.h>\r\n#include <WiFi.h>\r\n#include <esp_now.h>\r\n#include <esp_wifi.h>\r\n#include <esp_arduino_version.h>\r\n#include \"camera_target.h\"\r\n\r\n\r\n#define SCREEN_WIDTH 128\r\n#define SCREEN_HEIGHT 64\r\n#define SCREEN_ADDRESS 0x3C\r\n\r\n#define IMAGE_SIZE 1024\r\n\r\n// Enough for a very large script\r\n#define SCRIPT_BUFFER_SIZE 100000\r\n\r\n#define MAX_NORMAL_TEXT 512\r\n\r\n\r\nAdafruit_SSD1306 display(\r\n  SCREEN_WIDTH,\r\n  SCREEN_HEIGHT,\r\n  &Wire,\r\n  -1\r\n);\r\n\r\nHardwareSerial LaserSerial(2);\r\n\r\nconst int laserRX = 16;\r\n// Match the transmitter LINK_BAUD and Python BAUD_RATE.\r\nconst uint32_t LINK_BAUD = 38400;\r\n// Recover from a partial packet after the optical signal drops out.\r\nconst unsigned long PACKET_IDLE_TIMEOUT_MS = 500;\r\nunsigned long lastPacketByteTime = 0;\r\n\r\n\r\n// ============================================================\r\n// PACKET TYPES\r\n// ============================================================\r\n\r\n#define TYPE_TEXT          0x01\r\n#define TYPE_IMAGE         0x02\r\n#define TYPE_SCRIPT_START  0x03\r\n#define TYPE_SCRIPT_CHUNK  0x04\r\n#define TYPE_SCRIPT_END    0x05\r\n#define TYPE_ALIGN_PROBE   0x06\r\n\r\nconst uint8_t MAGIC1 = 0xAA;\r\nconst uint8_t MAGIC2 = 0x55;\r\n\r\nconst uint8_t ESPNOW_CHANNEL = 1;\r\nconst uint16_t ALIGN_ACK_MAGIC = 0xA17E;\r\nconst uint8_t broadcastAddress[] = {\r\n  0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF\r\n};\r\n\r\nstruct __attribute__((packed)) AlignAck {\r\n  uint16_t magic;\r\n  uint16_t sequence;\r\n};\r\n\r\n\r\n// Runtime speed control uses ESP-NOW so a bad optical rate can be recovered.\r\nconst uint16_t SPEED_MAGIC = 0xB431;\r\nconst uint16_t TARGET_MAGIC = 0xB434;\r\nconst uint16_t TARGET_ACK_MAGIC = 0xB436;\r\nconst uint16_t SOLID_HIT_MAGIC = 0xB435;\r\nunsigned long solidLowSince = 0, lastSolidHitReport = 0;\r\nbool solidLowActive = false;\r\nvolatile uint32_t pendingTarget = 0;\r\nbool cameraBlank = false;\r\nconst uint16_t SPEED_ACK_MAGIC = 0xB432;\r\nconst uint16_t TEST_ACK_MAGIC = 0xB433;\r\nstruct __attribute__((packed)) SpeedMessage {\r\n  uint16_t magic;\r\n  uint32_t value;  // baud rate or test sequence\r\n  uint16_t detail; // test errors\r\n};\r\nuint8_t testNextByte(uint32_t &state) {\r\n  state = state * 1664525UL + 1013904223UL;\r\n  return (uint8_t)(state >> 24);\r\n}\r\nbool supportedBaud(uint32_t baud) {\r\n  const uint32_t rates[] = {9600, 19200, 38400, 57600, 115200, 230400,\r\n                            460800, 921600, 1000000, 1500000, 2000000,\r\n                            2500000, 3000000, 4000000, 5000000};\r\n  for (uint32_t rate : rates) if (baud == rate) return true;\r\n  return false;\r\n}\r\n\r\nvolatile uint32_t pendingBaud = 0;\r\n#if ESP_ARDUINO_VERSION_MAJOR >= 3\r\nvoid onSpeedRequest(const esp_now_recv_info_t *info, const uint8_t *data, int length)\r\n#else\r\nvoid onSpeedRequest(const uint8_t *mac, const uint8_t *data, int length)\r\n#endif\r\n{\r\n  if (length != sizeof(SpeedMessage)) return;\r\n  SpeedMessage request;\r\n  memcpy(&request, data, sizeof(request));\r\n  if (request.magic == TARGET_MAGIC) {\r\n    if (request.value >= 1 && request.value <= 5) pendingTarget = request.value;\r\n    return;\r\n  }\r\n  if (request.magic == SPEED_MAGIC && supportedBaud(request.value)) {\r\n    pendingBaud = request.value;\r\n  }\r\n}\r\n\r\nbool espNowReady = false;\r\n\r\nvoid showCameraTarget() {\r\n  cameraBlank = false;\r\n  display.clearDisplay();\r\n  display.fillRect(32, 0, 64, 64, SSD1306_WHITE);\r\n  for (int y = 0; y < 8; y++) {\r\n    for (int x = 0; x < 8; x++) {\r\n      display.fillRect(40 + x * 6, 8 + y * 6, 6, 6,\r\n                      (CAMERA_TAG_ROWS[y] & (1 << (7 - x))) ? SSD1306_WHITE : SSD1306_BLACK);\r\n    }\r\n  }\r\n  if (!cameraBlank) display.display();\r\n}\r\n\r\n\r\n// ============================================================\r\n// BUFFERS\r\n// ============================================================\r\n\r\nuint8_t imageBuffer[IMAGE_SIZE];\r\n\r\nchar normalText[MAX_NORMAL_TEXT + 1];\r\n\r\nchar *scriptBuffer = NULL;\r\n\r\nuint32_t scriptLength = 0;\r\n\r\n\r\n// Temporary packet buffer\r\nuint8_t packetBuffer[1024];\r\n\r\n\r\n// ============================================================\r\n// PACKET RECEIVER STATE\r\n// ============================================================\r\n\r\nenum ReceiveState {\r\n\r\n  WAIT_MAGIC1,\r\n  WAIT_MAGIC2,\r\n  WAIT_TYPE,\r\n  WAIT_LENGTH_HIGH,\r\n  WAIT_LENGTH_LOW,\r\n  RECEIVE_PAYLOAD\r\n};\r\n\r\nReceiveState state = WAIT_MAGIC1;\r\n\r\nuint8_t packetType = 0;\r\n\r\nuint16_t packetLength = 0;\r\nuint16_t packetIndex = 0;\r\n\r\n\r\n// ============================================================\r\n// SCROLL VARIABLES\r\n// ============================================================\r\n\r\nbool scrolling = false;\r\n\r\nuint32_t scrollPixel = 0;\r\n\r\nunsigned long lastScrollTime = 0;\r\n\r\n// Smaller = faster\r\nconst unsigned long SCROLL_DELAY = 20;\r\n\r\n// Text size 2 = approximately 12 pixels per character\r\nconst int CHARACTER_WIDTH = 12;\r\n#include \"dino_game.h\"\r\n\r\n\r\n// ============================================================\r\n// RESET PACKET RECEIVER\r\n// ============================================================\r\n\r\nvoid resetReceiver() {\r\n\r\n  state = WAIT_MAGIC1;\r\n\r\n  packetType = 0;\r\n\r\n  packetLength = 0;\r\n\r\n  packetIndex = 0;\r\n}\r\n\r\n\r\n// ============================================================\r\n// IMAGE CONVERSION\r\n// ============================================================\r\n\r\nvoid convertToSSD1306() {\r\n\r\n  uint8_t *oledBuffer =\r\n    display.getBuffer();\r\n\r\n  memset(\r\n    oledBuffer,\r\n    0,\r\n    IMAGE_SIZE\r\n  );\r\n\r\n\r\n  for (int y = 0; y < 64; y++) {\r\n\r\n    for (int x = 0; x < 128; x++) {\r\n\r\n      int sourceByte =\r\n        y * 16 + (x / 8);\r\n\r\n      int sourceBit =\r\n        7 - (x % 8);\r\n\r\n      bool pixel =\r\n        (imageBuffer[sourceByte] >> sourceBit)\r\n        & 0x01;\r\n\r\n\r\n      if (pixel) {\r\n\r\n        int targetByte =\r\n          x + (y / 8) * 128;\r\n\r\n        int targetBit =\r\n          y % 8;\r\n\r\n        oledBuffer[targetByte] |=\r\n          (1 << targetBit);\r\n      }\r\n    }\r\n  }\r\n}\r\n\r\n\r\n// ============================================================\r\n// SHOW IMAGE\r\n// ============================================================\r\n\r\nvoid showImage() {\r\n\r\n  scrolling = false;\r\n\r\n  convertToSSD1306();\r\n\r\n  if (!cameraBlank) display.display();\r\n\r\n  Serial.println(\"IMAGE DISPLAYED\");\r\n}\r\n\r\n\r\n// ============================================================\r\n// SHOW NORMAL TEXT\r\n// ============================================================\r\n\r\nvoid showNormalText() {\r\n\r\n  scrolling = false;\r\n\r\n  normalText[packetLength] = '\\0';\r\n\r\n  display.clearDisplay();\r\n\r\n  display.setTextColor(\r\n    SSD1306_WHITE\r\n  );\r\n\r\n  display.setTextSize(2);\r\n\r\n  display.setCursor(0, 20);\r\n\r\n  display.print(normalText);\r\n\r\n  if (!cameraBlank) display.display();\r\n\r\n  Serial.print(\"TEXT: \");\r\n  Serial.println(normalText);\r\n}\r\n\r\n\r\n// ============================================================\r\n// START RECEIVING SCRIPT\r\n// ============================================================\r\n\r\nvoid startReceivingScript() {\r\n\r\n  scrolling = false;\r\n\r\n  scriptLength = 0;\r\n\r\n\r\n  display.clearDisplay();\r\n\r\n  display.setTextColor(\r\n    SSD1306_WHITE\r\n  );\r\n\r\n  display.setTextSize(1);\r\n\r\n  display.setCursor(0, 20);\r\n\r\n  display.println(\"RECEIVING SCRIPT\");\r\n\r\n  if (!cameraBlank) display.display();\r\n\r\n\r\n  Serial.println();\r\n  Serial.println(\"SCRIPT START\");\r\n}\r\n\r\n\r\n// ============================================================\r\n// ADD SCRIPT CHUNK\r\n// ============================================================\r\n\r\nvoid addScriptChunk() {\r\n\r\n  for (uint16_t i = 0; i < packetLength; i++) {\r\n\r\n    if (\r\n      scriptLength <\r\n      SCRIPT_BUFFER_SIZE - 1\r\n    ) {\r\n\r\n      char c =\r\n        (char)packetBuffer[i];\r\n\r\n\r\n      // Convert line endings into spaces\r\n      // so it scrolls as one continuous ticker\r\n      if (\r\n        c == '\\n' ||\r\n        c == '\\r'\r\n      ) {\r\n\r\n        c = ' ';\r\n      }\r\n\r\n\r\n      scriptBuffer[scriptLength++] = c;\r\n    }\r\n  }\r\n\r\n\r\n  scriptBuffer[scriptLength] = '\\0';\r\n}\r\n\r\n\r\n// ============================================================\r\n// FINISH SCRIPT\r\n// ============================================================\r\n\r\nvoid finishScript() {\r\n\r\n  scriptBuffer[scriptLength] = '\\0';\r\n\r\n  Serial.println();\r\n  Serial.println(\"SCRIPT RECEIVED\");\r\n\r\n  Serial.print(\"Characters: \");\r\n  Serial.println(scriptLength);\r\n\r\n\r\n  if (scriptLength > 0) {\r\n\r\n    scrollPixel = 0;\r\n\r\n    lastScrollTime = millis();\r\n\r\n    scrolling = true;\r\n  }\r\n}\r\n\r\n\r\n// ============================================================\r\n// SCROLL HUGE TEXT\r\n// ============================================================\r\n\r\nvoid updateScrolling() {\r\n\r\n  if (!scrolling) {\r\n    return;\r\n  }\r\n\r\n\r\n  if (\r\n    millis() - lastScrollTime\r\n    < SCROLL_DELAY\r\n  ) {\r\n\r\n    return;\r\n  }\r\n\r\n\r\n  lastScrollTime = millis();\r\n\r\n\r\n  // Which character are we currently at?\r\n  uint32_t firstChar =\r\n    scrollPixel / CHARACTER_WIDTH;\r\n\r\n\r\n  // Pixel offset within that character\r\n  int pixelOffset =\r\n    scrollPixel % CHARACTER_WIDTH;\r\n\r\n\r\n  // Finished entire script\r\n  if (firstChar >= scriptLength) {\r\n\r\n    scrolling = false;\r\n\r\n    display.clearDisplay();\r\n\r\n    display.setTextSize(1);\r\n\r\n    display.setCursor(0, 20);\r\n\r\n    display.println(\"END\");\r\n\r\n    if (!cameraBlank) display.display();\r\n\r\n    return;\r\n  }\r\n\r\n\r\n  display.clearDisplay();\r\n\r\n  display.setTextColor(\r\n    SSD1306_WHITE\r\n  );\r\n\r\n  display.setTextSize(2);\r\n\r\n\r\n  // Start slightly off-screen\r\n  display.setCursor(\r\n    -pixelOffset,\r\n    20\r\n  );\r\n\r\n\r\n  // Only draw characters that could actually be visible.\r\n  // This makes huge scripts efficient.\r\n  const int visibleChars = 13;\r\n\r\n\r\n  for (\r\n    int i = 0;\r\n    i < visibleChars;\r\n    i++\r\n  ) {\r\n\r\n    uint32_t index =\r\n      firstChar + i;\r\n\r\n\r\n    if (index >= scriptLength) {\r\n      break;\r\n    }\r\n\r\n\r\n    char c =\r\n      scriptBuffer[index];\r\n\r\n\r\n    display.print(c);\r\n  }\r\n\r\n\r\n  if (!cameraBlank) display.display();\r\n\r\n\r\n  scrollPixel++;\r\n}\r\n\r\n\r\n// ============================================================\r\n// ALIGNMENT FEEDBACK OVER ESP-NOW\r\n// ============================================================\r\n\r\nvoid setupAlignmentFeedback() {\r\n  WiFi.mode(WIFI_STA);\r\n  WiFi.disconnect();\r\n  esp_wifi_set_channel(ESPNOW_CHANNEL, WIFI_SECOND_CHAN_NONE);\r\n\r\n  if (esp_now_init() != ESP_OK) {\r\n    Serial.println(\"ESP-NOW INIT FAILED\");\r\n    return;\r\n  }\r\n\r\n  esp_now_peer_info_t peerInfo = {};\r\n  memcpy(peerInfo.peer_addr, broadcastAddress, 6);\r\n  peerInfo.channel = ESPNOW_CHANNEL;\r\n  peerInfo.encrypt = false;\r\n\r\n  esp_err_t addResult = esp_now_add_peer(&peerInfo);\r\n\r\n  if (\r\n    addResult != ESP_OK &&\r\n    addResult != ESP_ERR_ESPNOW_EXIST\r\n  ) {\r\n    Serial.println(\"ESP-NOW PEER FAILED\");\r\n    return;\r\n  }\r\n\r\n  if (esp_now_register_recv_cb(onSpeedRequest) != ESP_OK) {\r\n    Serial.println(\"ESP-NOW SPEED CALLBACK FAILED\");\r\n    return;\r\n  }\r\n  espNowReady = true;\r\n  Serial.println(\"Runtime speed receiver ready, channel 1\");\r\n  Serial.println(\"Alignment feedback ready\");\r\n}\r\n\r\nvoid acknowledgeAlignmentProbe() {\r\n  if (!espNowReady || packetLength != 2) {\r\n    return;\r\n  }\r\n\r\n  uint16_t sequence =\r\n    ((uint16_t)packetBuffer[0] << 8) |\r\n    packetBuffer[1];\r\n\r\n  AlignAck ack;\r\n  ack.magic = ALIGN_ACK_MAGIC;\r\n  ack.sequence = sequence;\r\n\r\n  esp_now_send(\r\n    broadcastAddress,\r\n    (uint8_t *)&ack,\r\n    sizeof(ack)\r\n  );\r\n\r\n  Serial.print(\"LASER HIT, PROBE \");\r\n  Serial.println(sequence);\r\n}\r\n\r\n\r\n// ============================================================\r\n// PROCESS COMPLETE PACKET\r\n// ============================================================\r\n\r\nvoid processPacket() {\r\n  // Bad game packets leave the last good scene intact. Other display packets\r\n  // end game rendering so it cannot overwrite a later text or image message.\r\n  if (packetType == 0x08) {\r\n    receiveDino(packetBuffer, packetLength);\r\n    return;\r\n  }\r\n  if (packetType >= TYPE_TEXT && packetType <= TYPE_SCRIPT_END) dinoActive = false;\r\n\r\n\r\n  // ----------------------------------------------------------\r\n  // ALIGNMENT PROBE\r\n  // ----------------------------------------------------------\r\n\r\n  if (packetType == 0x07 && packetLength == IMAGE_SIZE) {\r\n    uint32_t sequence = ((uint32_t)packetBuffer[0] << 24) |\r\n                        ((uint32_t)packetBuffer[1] << 16) |\r\n                        ((uint32_t)packetBuffer[2] << 8) | packetBuffer[3];\r\n    uint32_t randomState = sequence;\r\n    uint16_t errors = 0;\r\n    for (int i = 4; i < IMAGE_SIZE; i++) {\r\n      if (packetBuffer[i] != testNextByte(randomState)) errors++;\r\n    }\r\n    SpeedMessage result = {TEST_ACK_MAGIC, sequence, errors};\r\n    if (espNowReady) esp_now_send(broadcastAddress, (uint8_t *)&result, sizeof(result));\r\n  }\r\n  else if (packetType == TYPE_ALIGN_PROBE) {\r\n\r\n    acknowledgeAlignmentProbe();\r\n  }\r\n\r\n\r\n  // ----------------------------------------------------------\r\n  // IMAGE\r\n  // ----------------------------------------------------------\r\n\r\n  else if (packetType == TYPE_IMAGE) {\r\n\r\n    if (packetLength == IMAGE_SIZE) {\r\n\r\n      // User content ends camera blanking even if DISPLAY radio was missed.\r\n      cameraBlank = false;\r\n      memcpy(\r\n        imageBuffer,\r\n        packetBuffer,\r\n        IMAGE_SIZE\r\n      );\r\n\r\n      Serial.println(\"IMAGE RECEIVED\");\r\n\r\n      showImage();\r\n    }\r\n  }\r\n\r\n\r\n  // ----------------------------------------------------------\r\n  // NORMAL TEXT\r\n  // ----------------------------------------------------------\r\n\r\n  else if (packetType == TYPE_TEXT) {\r\n\r\n    if (\r\n      packetLength <=\r\n      MAX_NORMAL_TEXT\r\n    ) {\r\n\r\n      cameraBlank = false;\r\n      memcpy(\r\n        normalText,\r\n        packetBuffer,\r\n        packetLength\r\n      );\r\n\r\n      showNormalText();\r\n    }\r\n  }\r\n\r\n\r\n  // ----------------------------------------------------------\r\n  // SCRIPT START\r\n  // ----------------------------------------------------------\r\n\r\n  else if (\r\n    packetType ==\r\n    TYPE_SCRIPT_START\r\n  ) {\r\n\r\n    cameraBlank = false;\r\n    startReceivingScript();\r\n  }\r\n\r\n\r\n  // ----------------------------------------------------------\r\n  // SCRIPT CHUNK\r\n  // ----------------------------------------------------------\r\n\r\n  else if (\r\n    packetType ==\r\n    TYPE_SCRIPT_CHUNK\r\n  ) {\r\n\r\n    addScriptChunk();\r\n  }\r\n\r\n\r\n  // ----------------------------------------------------------\r\n  // SCRIPT END\r\n  // ----------------------------------------------------------\r\n\r\n  else if (\r\n    packetType ==\r\n    TYPE_SCRIPT_END\r\n  ) {\r\n\r\n    finishScript();\r\n  }\r\n}\r\n\r\n\r\n// ============================================================\r\n// SETUP\r\n// ============================================================\r\n\r\nvoid setup() {\r\n\r\n  Serial.begin(115200);\r\n\r\n  Wire.begin(21, 22);\r\n\r\n\r\n  if (!display.begin(\r\n        SSD1306_SWITCHCAPVCC,\r\n        SCREEN_ADDRESS)) {\r\n\r\n    Serial.println(\"OLED FAILED\");\r\n\r\n    while (1);\r\n  }\r\n\r\n\r\n  // Allocate large script buffer\r\n  scriptBuffer =\r\n    (char *)malloc(\r\n      SCRIPT_BUFFER_SIZE\r\n    );\r\n\r\n\r\n  if (scriptBuffer == NULL) {\r\n\r\n    Serial.println(\r\n      \"SCRIPT MEMORY FAILED\"\r\n    );\r\n\r\n    while (1);\r\n  }\r\n\r\n\r\n  display.clearDisplay();\r\n\r\n  display.setTextColor(\r\n    SSD1306_WHITE\r\n  );\r\n\r\n  display.setTextSize(1);\r\n\r\n  display.setCursor(0, 20);\r\n\r\n  display.println(\"WAITING\");\r\n\r\n  if (!cameraBlank) display.display();\r\n\r\n\r\n  // Buffer a whole image during OLED updates.\r\n  LaserSerial.setRxBufferSize(2048);\r\n  LaserSerial.begin(\r\n    LINK_BAUD,\r\n    SERIAL_8N1,\r\n    laserRX,\r\n    -1\r\n  );\r\n\r\n  setupAlignmentFeedback();\r\n  showCameraTarget();\r\n\r\n\r\n  Serial.println(\r\n    \"Receiver ready\"\r\n  );\r\n}\r\n\r\n\r\n// ============================================================\r\n// LOOP\r\n// ============================================================\r\n\r\nvoid loop() {\r\n\r\n  uint32_t targetRequest = pendingTarget;\r\n  if (targetRequest) {\r\n    pendingTarget = 0;\r\n    // Game transitions are acknowledged over radio, so lost optical bytes\r\n    // cannot leave an old image packet or game renderer active.\r\n    dinoActive = false;\r\n    if (targetRequest == 4 || targetRequest == 5) {\r\n      while (LaserSerial.available()) LaserSerial.read();\r\n      resetReceiver();\r\n      scrolling = false;\r\n      cameraBlank = false;\r\n      if (targetRequest == 4) {\r\n        display.clearDisplay();\r\n        display.setTextSize(1);\r\n        display.setCursor(30, 26);\r\n        display.print(\"DINO READY\");\r\n        display.display();\r\n      } else showCameraTarget();\r\n      SpeedMessage ack = {TARGET_ACK_MAGIC, targetRequest, 0};\r\n      if (espNowReady) esp_now_send(broadcastAddress, (uint8_t *)&ack, sizeof(ack));\r\n    } else\r\n    if (targetRequest == 2) {\r\n      cameraBlank = true;\r\n      display.clearDisplay();\r\n      display.display();\r\n    } else if (targetRequest == 3) {\r\n      cameraBlank = false;\r\n      bool hasPixels = false;\r\n      for (int i = 0; i < 1024; i++) {\r\n        if (display.getBuffer()[i]) { hasPixels = true; break; }\r\n      }\r\n      if (hasPixels) display.display();\r\n      else showCameraTarget();\r\n    } else showCameraTarget();\r\n  }\r\n\r\n\r\n  // Active-low sensor shares GPIO16 with UART RX. Require sustained light,\r\n  // much longer than a normal UART low pulse; probes never establish lock here.\r\n  unsigned long lightNow = millis();\r\n  if (cameraBlank && digitalRead(laserRX) == LOW) {\r\n    if (!solidLowActive) {\r\n      solidLowActive = true;\r\n      solidLowSince = lightNow;\r\n    }\r\n    if (espNowReady && lightNow-solidLowSince >= 20 && lightNow-lastSolidHitReport >= 100) {\r\n      SpeedMessage hit = {SOLID_HIT_MAGIC, 1, 0};\r\n      esp_now_send(broadcastAddress, (uint8_t *)&hit, sizeof(hit));\r\n      lastSolidHitReport = lightNow;\r\n    }\r\n  } else {\r\n    solidLowActive = false;\r\n  }\r\n\r\n  // Apply UART changes from the main loop, not the Wi-Fi callback.\r\n  uint32_t baud = pendingBaud;\r\n  if (baud != 0) {\r\n    pendingBaud = 0;\r\n    LaserSerial.updateBaudRate(baud);\r\n    while (LaserSerial.available()) LaserSerial.read();\r\n    resetReceiver();\r\n    SpeedMessage ack = {SPEED_ACK_MAGIC, baud, 0};\r\n    esp_err_t result = esp_now_send(broadcastAddress, (uint8_t *)&ack, sizeof(ack));\r\n    Serial.print(\"SPEED REQUEST \");\r\n    Serial.print(baud);\r\n    Serial.print(\" ACK SEND CODE \");\r\n    Serial.println((int)result); // 0 means queued successfully, not confirmed delivery.\r\n  }\r\n\r\n  if (state != WAIT_MAGIC1 &&\r\n      millis() - lastPacketByteTime > PACKET_IDLE_TIMEOUT_MS) {\r\n    resetReceiver();\r\n  }\r\n\r\n  // Keep scrolling without blocking the receiver\r\n  if (dinoActive) updateDino();\r\n  else updateScrolling();\r\n\r\n\r\n  while (LaserSerial.available()) {\r\n\r\n    uint8_t b =\r\n      LaserSerial.read();\r\n    lastPacketByteTime = millis();\r\n\r\n\r\n    switch (state) {\r\n\r\n\r\n      case WAIT_MAGIC1:\r\n\r\n        if (b == MAGIC1) {\r\n\r\n          state =\r\n            WAIT_MAGIC2;\r\n        }\r\n\r\n        break;\r\n\r\n\r\n      case WAIT_MAGIC2:\r\n\r\n        if (b == MAGIC2) {\r\n\r\n          state =\r\n            WAIT_TYPE;\r\n        }\r\n\r\n        else if (b == MAGIC1) {\r\n\r\n          state =\r\n            WAIT_MAGIC2;\r\n        }\r\n\r\n        else {\r\n\r\n          state =\r\n            WAIT_MAGIC1;\r\n        }\r\n\r\n        break;\r\n\r\n\r\n      case WAIT_TYPE:\r\n\r\n        packetType = b;\r\n        if (packetType < TYPE_TEXT || packetType > 0x08) {\r\n          resetReceiver();\r\n          if (b == MAGIC1) state = WAIT_MAGIC2;\r\n          break;\r\n        }\r\n\r\n        state =\r\n          WAIT_LENGTH_HIGH;\r\n\r\n        break;\r\n\r\n\r\n      case WAIT_LENGTH_HIGH:\r\n\r\n        packetLength =\r\n          ((uint16_t)b << 8);\r\n\r\n        state =\r\n          WAIT_LENGTH_LOW;\r\n\r\n        break;\r\n\r\n\r\n      case WAIT_LENGTH_LOW:\r\n\r\n        packetLength |= b;\r\n\r\n        packetIndex = 0;\r\n        if ((packetType == TYPE_IMAGE || packetType == 0x07) && packetLength != IMAGE_SIZE ||\r\n            packetType == TYPE_ALIGN_PROBE && packetLength != 2 ||\r\n            packetType == 0x08 && packetLength != 19 ||\r\n            (packetType == TYPE_SCRIPT_START || packetType == TYPE_SCRIPT_END) && packetLength != 0) {\r\n          resetReceiver();\r\n          break;\r\n        }\r\n\r\n\r\n        // Zero-length packet:\r\n        // START SCRIPT or END SCRIPT\r\n        if (packetLength == 0) {\r\n\r\n          processPacket();\r\n\r\n          resetReceiver();\r\n        }\r\n\r\n        else if (\r\n          packetLength <=\r\n          sizeof(packetBuffer)\r\n        ) {\r\n\r\n          state =\r\n            RECEIVE_PAYLOAD;\r\n        }\r\n\r\n        else {\r\n\r\n          Serial.println(\r\n            \"PACKET TOO LARGE\"\r\n          );\r\n\r\n          resetReceiver();\r\n        }\r\n\r\n        break;\r\n\r\n\r\n      case RECEIVE_PAYLOAD:\r\n\r\n        packetBuffer[packetIndex++] = b;\r\n\r\n\r\n        if (\r\n          packetIndex >=\r\n          packetLength\r\n        ) {\r\n\r\n          processPacket();\r\n\r\n          resetReceiver();\r\n        }\r\n\r\n        break;\r\n    }\r\n  }\r\n}\r\n"},{"type":"code","heading":"Code","filename":"servo_find_Send.ino","language":"Arduino / C++","code":"#include <Arduino.h>\r\n#include <WiFi.h>\r\n#include <esp_now.h>\r\n#include <esp_wifi.h>\r\n#include <esp_arduino_version.h>\r\n#include <ESP32Servo.h>\r\n\r\n#define IMAGE_SIZE 1024\r\n\r\n// USB RX and laser TX share Serial: use the same rate in Python and receiver.\r\nconst uint32_t LINK_BAUD = 38400;\r\n\r\n// ============================================================\r\n// PASTE YOUR EXISTING 128x64 BITMAP HERE\r\n// ============================================================\r\n\r\nconst unsigned char epd_bitmap_d1urfbt_28f79a48_5efa_41be_91d3_85e6dfe128e5[] PROGMEM = {\r\n\r\n  // YOUR 1024 BYTES HERE\r\n\r\n};\r\n\r\n#define bitmap epd_bitmap_d1urfbt_28f79a48_5efa_41be_91d3_85e6dfe128e5\r\n\r\n\r\n// ============================================================\r\n// PACKET TYPES\r\n// ============================================================\r\n\r\n#define TYPE_TEXT 0x01\r\n#define TYPE_IMAGE 0x02\r\n#define TYPE_SCRIPT_START 0x03\r\n#define TYPE_SCRIPT_CHUNK 0x04\r\n#define TYPE_SCRIPT_END 0x05\r\n#define TYPE_ALIGN_PROBE 0x06\r\n\r\nconst uint8_t MAGIC1 = 0xAA;\r\nconst uint8_t MAGIC2 = 0x55;\r\n\r\nbool scriptMode = false;\r\n\r\nuint8_t usbImageBuffer[IMAGE_SIZE];\r\n\r\n// ============================================================\r\n// PAN/TILT ALIGNMENT\r\n// ============================================================\r\n\r\n// Third NPN transistor: HIGH grounds the laser return for solid CV light.\r\nconst int LASER_OVERRIDE_PIN = 25;\r\nvolatile bool laserSolidEnabled = false;\r\nvolatile bool pendingSolidHit = false;\r\nvoid setLaserSolid(bool solid) {\r\n  laserSolidEnabled = solid;\r\n  if (!solid) pendingSolidHit = false;\r\n  digitalWrite(LASER_OVERRIDE_PIN, solid ? HIGH : LOW);\r\n}\r\n\r\nconst int PAN_PIN = 13;\r\nconst int TILT_PIN = 14;\r\n\r\nconst int PAN_HOME = 41;\r\nconst int TILT_HOME = 104;\r\n\r\nconst int PAN_MIN = 0;\r\nconst int PAN_MAX = 180;\r\nconst int TILT_MIN = 0;\r\nconst int TILT_MAX = 180;\r\n\r\n// Keep automatic search independent of the expanded manual movement limits.\r\nconst int SEARCH_PAN_RADIUS = 11;\r\nconst int SEARCH_TILT_RADIUS = 6;\r\nconst int SEARCH_PAN_MIN = PAN_HOME - SEARCH_PAN_RADIUS;\r\nconst int SEARCH_PAN_MAX = PAN_HOME + SEARCH_PAN_RADIUS;\r\nconst int SEARCH_TILT_MIN = TILT_HOME - SEARCH_TILT_RADIUS;\r\nconst int SEARCH_TILT_MAX = TILT_HOME + SEARCH_TILT_RADIUS;\r\nconst int SEARCH_PASSES = 2;\r\nint searchPanX100 = PAN_HOME * 100;\r\nint searchTiltX100 = TILT_HOME * 100;\r\nint searchStepX100 = 50; // 0.5 degree; app can select another measured useful step\r\nint currentPanX100 = PAN_HOME * 100;\r\nint currentTiltX100 = TILT_HOME * 100;\r\nint lockedPanX100 = PAN_HOME * 100;\r\nint lockedTiltX100 = TILT_HOME * 100;\r\nbool searchCancelled = false;\r\nunsigned long nearSearchStarted = 0;\r\nbool nearSearchTimed = false;\r\n\r\n// One unit here is one quarter-degree.\r\nconst int SCAN_STEP_QUARTER_DEGREES = 1;\r\nconst int SERVO_SETTLE_MS = 25;\r\nconst int SEARCH_SETTLE_MS = 300;\r\nconst int SEARCH_PROBES_PER_POINT = 3;\r\nconst int SEARCH_PROBE_GAP_MS = 40;\r\nconst int ACK_WAIT_MS = 30;\r\nconst int LOCAL_TRACK_RADIUS_QUARTER_DEGREES = 4;  // +/- 1 degree\r\n// Retained for the optional diagnostic refinement mapper.\r\nconst int REFINE_RADIUS_HALF_DEGREES = 4;\r\nconst int REFINEMENT_PROBES_PER_POINT = 3;\r\nconst int LOCK_CONFIRM_PROBES = 6;\r\nconst int LOCK_CONFIRM_REQUIRED = 4;\r\nconst int PAN_BACKLASH_TAKEUP_QUARTER_DEGREES = 1;   // 1 degree\r\nconst int TILT_BACKLASH_TAKEUP_QUARTER_DEGREES = 1;  // 1 degree\r\nconst int BACKLASH_PRELOAD_MS = 80;\r\nconst int FINAL_LOCK_SETTLE_MS = 150;\r\nconst int MISSED_PROBES_BEFORE_MOVE = 5;\r\nconst unsigned long ACTIVE_CHECK_INTERVAL_MS = 1000;\r\nconst uint8_t ESPNOW_CHANNEL = 1;\r\n\r\nconst uint16_t ALIGN_ACK_MAGIC = 0xA17E;\r\n\r\nstruct __attribute__((packed)) AlignAck {\r\n  uint16_t magic;\r\n  uint16_t sequence;\r\n};\r\n\r\n\r\n// Runtime speed control uses ESP-NOW so a bad optical rate can be recovered.\r\nconst uint16_t SPEED_MAGIC = 0xB431;\r\nconst uint16_t TARGET_MAGIC = 0xB434;\r\nconst uint16_t TARGET_ACK_MAGIC = 0xB436;\r\nconst uint16_t SOLID_HIT_MAGIC = 0xB435;\r\nconst uint16_t SPEED_ACK_MAGIC = 0xB432;\r\nconst uint16_t TEST_ACK_MAGIC = 0xB433;\r\nstruct __attribute__((packed)) SpeedMessage {\r\n  uint16_t magic;\r\n  uint32_t value;  // baud rate or test sequence\r\n  uint16_t detail; // test errors\r\n};\r\nuint8_t testNextByte(uint32_t &state) {\r\n  state = state * 1664525UL + 1013904223UL;\r\n  return (uint8_t)(state >> 24);\r\n}\r\nbool supportedBaud(uint32_t baud) {\r\n  const uint32_t rates[] = {9600, 19200, 38400, 57600, 115200, 230400,\r\n                            460800, 921600, 1000000, 1500000, 2000000,\r\n                            2500000, 3000000, 4000000, 5000000};\r\n  for (uint32_t rate : rates) if (baud == rate) return true;\r\n  return false;\r\n}\r\n\r\nconst uint8_t speedBroadcast[] = {255,255,255,255,255,255};\r\nvolatile uint32_t speedAckBaud = 0;\r\nvolatile uint32_t targetAckValue = 0;\r\nvolatile uint32_t testAckSequence = 0;\r\nvolatile uint16_t testAckErrors = 0;\r\nbool benchmarkMode = false;\r\nbool speedControlReady = false;\r\n\r\nServo panServo;\r\nServo tiltServo;\r\n\r\nvolatile bool alignAckReceived = false;\r\nvolatile uint16_t alignAckSequence = 0;\r\nuint16_t nextProbeSequence = 1;\r\nint lockedPanX2 = PAN_HOME * 2;\r\nint lockedTiltX2 = TILT_HOME * 2;\r\nint currentPanX4 = PAN_HOME * 4;\r\nint currentTiltX4 = TILT_HOME * 4;\r\nint lockedPanX4 = PAN_HOME * 4;\r\nint lockedTiltX4 = TILT_HOME * 4;\r\nbool alignmentLocked = false;\r\nbool activeAlignmentEnabled = false;\r\nbool hasEverLocked = false;\r\nbool searchHasHit = false;\r\nint firstHitPanX100 = 0, firstHitTiltX100 = 0;\r\nint searchMinPan, searchMaxPan, searchMinTilt, searchMaxTilt;\r\nunsigned long lastAlignmentCheck = 0;\r\nint consecutiveMissedProbes = 0;\r\n\r\n#if ESP_ARDUINO_VERSION_MAJOR >= 3\r\nvoid onEspNowReceive(\r\n  const esp_now_recv_info_t *info,\r\n  const uint8_t *data,\r\n  int length)\r\n#else\r\nvoid onEspNowReceive(\r\n  const uint8_t *mac,\r\n  const uint8_t *data,\r\n  int length)\r\n#endif\r\n{\r\n  if (length == sizeof(SpeedMessage)) {\r\n    SpeedMessage message;\r\n    memcpy(&message, data, sizeof(message));\r\n    if (message.magic == SOLID_HIT_MAGIC && laserSolidEnabled) pendingSolidHit = true;\r\n    if (message.magic == SPEED_ACK_MAGIC) speedAckBaud = message.value;\r\n    if (message.magic == TARGET_ACK_MAGIC) targetAckValue = message.value;\r\n    if (message.magic == TEST_ACK_MAGIC) {\r\n      testAckErrors = message.detail;\r\n      testAckSequence = message.value;\r\n    }\r\n    return;\r\n  }\r\n  if (length != sizeof(AlignAck)) {\r\n    return;\r\n  }\r\n\r\n  AlignAck ack;\r\n  memcpy(&ack, data, sizeof(ack));\r\n\r\n  if (ack.magic == ALIGN_ACK_MAGIC) {\r\n    alignAckSequence = ack.sequence;\r\n    alignAckReceived = true;\r\n  }\r\n}\r\n\r\nint halfDegreesToPulse(int angleX2) {\r\n  angleX2 = constrain(angleX2, 0, 360);\r\n  return 500 + ((long)angleX2 * 2000L) / 360L;\r\n}\r\n\r\nint quarterDegreesToPulse(int angleX4) {\r\n  angleX4 = constrain(angleX4, 0, 720);\r\n  return 500 + ((long)angleX4 * 2000L) / 720L;\r\n}\r\n\r\nvoid moveMountQuarterDegrees(int panX4, int tiltX4) {\r\n  panX4 = constrain(panX4, PAN_MIN * 4, PAN_MAX * 4);\r\n  tiltX4 = constrain(tiltX4, TILT_MIN * 4, TILT_MAX * 4);\r\n\r\n  currentPanX4 = panX4;\r\n  currentTiltX4 = tiltX4;\r\n  currentPanX100 = panX4 * 25;\r\n  currentTiltX100 = tiltX4 * 25;\r\n\r\n  panServo.writeMicroseconds(quarterDegreesToPulse(panX4));\r\n  tiltServo.writeMicroseconds(quarterDegreesToPulse(tiltX4));\r\n}\r\n\r\n// Manual fine movement uses centidegrees and the servo timer's microsecond pulses.\r\nvoid moveMountFineDegrees(int panX100, int tiltX100) {\r\n  panX100 = constrain(panX100, PAN_MIN * 100, PAN_MAX * 100);\r\n  tiltX100 = constrain(tiltX100, TILT_MIN * 100, TILT_MAX * 100);\r\n  currentPanX100 = panX100;\r\n  currentTiltX100 = tiltX100;\r\n  currentPanX4 = (panX100 + 12) / 25;\r\n  currentTiltX4 = (tiltX100 + 12) / 25;\r\n  panServo.writeMicroseconds(500 + ((long)panX100 * 2000L) / 18000L);\r\n  tiltServo.writeMicroseconds(500 + ((long)tiltX100 * 2000L) / 18000L);\r\n}\r\n\r\nvoid moveMountHalfDegrees(int panX2, int tiltX2) {\r\n  moveMountQuarterDegrees(panX2 * 2, tiltX2 * 2);\r\n}\r\n\r\nvoid moveMount(int pan, int tilt) {\r\n  moveMountHalfDegrees(pan * 2, tilt * 2);\r\n}\r\n\r\nvoid approachWithBacklashTakeup(int targetPanX4, int targetTiltX4) {\r\n  int preloadPanX4 = constrain(\r\n    targetPanX4 - PAN_BACKLASH_TAKEUP_QUARTER_DEGREES,\r\n    PAN_MIN * 4,\r\n    PAN_MAX * 4);\r\n  int preloadTiltX4 = constrain(\r\n    targetTiltX4 - TILT_BACKLASH_TAKEUP_QUARTER_DEGREES,\r\n    TILT_MIN * 4,\r\n    TILT_MAX * 4);\r\n\r\n  // Unload both gear trains, then always approach the final command\r\n  // from the increasing-angle direction.\r\n  moveMountQuarterDegrees(preloadPanX4, preloadTiltX4);\r\n  delay(BACKLASH_PRELOAD_MS);\r\n  moveMountQuarterDegrees(targetPanX4, targetTiltX4);\r\n  delay(FINAL_LOCK_SETTLE_MS);\r\n}\r\n\r\nvoid goHome() {\r\n  moveMount(PAN_HOME, TILT_HOME);\r\n  lockedPanX2 = PAN_HOME * 2;\r\n  lockedTiltX2 = TILT_HOME * 2;\r\n  lockedPanX4 = PAN_HOME * 4;\r\n  lockedTiltX4 = TILT_HOME * 4;\r\n  alignmentLocked = false;\r\n}\r\n\r\n\r\n// ============================================================\r\n// SEND PACKET HEADER\r\n// ============================================================\r\n\r\nvoid sendHeader(uint8_t type, uint16_t length) {\r\n  // Every optical packet needs UART modulation, including messages sent\r\n  // while automatic alignment checks are disabled.\r\n  setLaserSolid(false);\r\n\r\n  Serial.write(MAGIC1);\r\n  Serial.write(MAGIC2);\r\n\r\n  Serial.write(type);\r\n\r\n  Serial.write((uint8_t)(length >> 8));\r\n  Serial.write((uint8_t)(length & 0xFF));\r\n}\r\n\r\n\r\n// ============================================================\r\n// ALIGNMENT PROBE AND SEARCH\r\n// ============================================================\r\n\r\nbool sendAlignmentProbe() {\r\n  setLaserSolid(false);  // Receiver needs optical UART modulation.\r\n  uint16_t sequence = nextProbeSequence++;\r\n\r\n  alignAckReceived = false;\r\n\r\n  sendHeader(TYPE_ALIGN_PROBE, 2);\r\n  Serial.write((uint8_t)(sequence >> 8));\r\n  Serial.write((uint8_t)(sequence & 0xFF));\r\n  Serial.flush();\r\n\r\n  unsigned long started = millis();\r\n\r\n  while (millis() - started < ACK_WAIT_MS) {\r\n    if (alignAckReceived && alignAckSequence == sequence) {\r\n      return true;\r\n    }\r\n\r\n    delay(1);\r\n  }\r\n\r\n  return false;\r\n}\r\n\r\nbool testPositionHalfDegrees(int panX2, int tiltX2) {\r\n  if (\r\n    panX2 < PAN_MIN * 2 || panX2 > PAN_MAX * 2 || tiltX2 < TILT_MIN * 2 || tiltX2 > TILT_MAX * 2) {\r\n    return false;\r\n  }\r\n\r\n  moveMountHalfDegrees(panX2, tiltX2);\r\n  delay(SERVO_SETTLE_MS);\r\n  return sendAlignmentProbe();\r\n}\r\n\r\nbool testPositionQuarterDegrees(int panX4, int tiltX4) {\r\n  if (\r\n    panX4 < PAN_MIN * 4 || panX4 > PAN_MAX * 4 || tiltX4 < TILT_MIN * 4 || tiltX4 > TILT_MAX * 4) {\r\n    return false;\r\n  }\r\n\r\n  moveMountQuarterDegrees(panX4, tiltX4);\r\n  delay(SERVO_SETTLE_MS);\r\n  return sendAlignmentProbe();\r\n}\r\n\r\nint scorePositionHalfDegrees(\r\n  int panX2,\r\n  int tiltX2,\r\n  int probeCount) {\r\n  if (\r\n    panX2 < PAN_MIN * 2 || panX2 > PAN_MAX * 2 || tiltX2 < TILT_MIN * 2 || tiltX2 > TILT_MAX * 2) {\r\n    return 0;\r\n  }\r\n\r\n  moveMountHalfDegrees(panX2, tiltX2);\r\n  delay(SERVO_SETTLE_MS);\r\n\r\n  int score = 0;\r\n\r\n  for (int probe = 0; probe < probeCount; probe++) {\r\n    if (sendAlignmentProbe()) {\r\n      score++;\r\n    }\r\n\r\n    delay(3);\r\n  }\r\n\r\n  return score;\r\n}\r\n\r\nvoid printHalfDegreeValue(int valueX2) {\r\n  Serial.print(valueX2 / 2);\r\n\r\n  if (valueX2 & 1) {\r\n    Serial.print(\".5\");\r\n  }\r\n}\r\n\r\nvoid printQuarterDegreeValue(int valueX4) {\r\n  Serial.print(valueX4 / 4);\r\n\r\n  int fraction = valueX4 & 3;\r\n  if (fraction == 1) Serial.print(\".25\");\r\n  if (fraction == 2) Serial.print(\".5\");\r\n  if (fraction == 3) Serial.print(\".75\");\r\n}\r\n\r\nbool refineAlignment() {\r\n  const int originalPanX2 = lockedPanX2;\r\n  const int originalTiltX2 = lockedTiltX2;\r\n\r\n  long weightedPanSum = 0;\r\n  long weightedTiltSum = 0;\r\n  int totalSuccessfulProbes = 0;\r\n  int successfulPositions = 0;\r\n  int bestScore = 0;\r\n  int bestPanX2 = originalPanX2;\r\n  int bestTiltX2 = originalTiltX2;\r\n\r\n  // Map a small half-degree grid around the first detected point.\r\n  // Multiple probes distinguish a reliable point from a lucky packet.\r\n  for (\r\n    int tiltOffset = -REFINE_RADIUS_HALF_DEGREES;\r\n    tiltOffset <= REFINE_RADIUS_HALF_DEGREES;\r\n    tiltOffset++) {\r\n    bool reverseRow = (tiltOffset & 1);\r\n\r\n    for (\r\n      int column = -REFINE_RADIUS_HALF_DEGREES;\r\n      column <= REFINE_RADIUS_HALF_DEGREES;\r\n      column++) {\r\n      int panOffset = reverseRow ? -column : column;\r\n      int panX2 = originalPanX2 + panOffset;\r\n      int tiltX2 = originalTiltX2 + tiltOffset;\r\n\r\n      int score = scorePositionHalfDegrees(\r\n        panX2,\r\n        tiltX2,\r\n        REFINEMENT_PROBES_PER_POINT);\r\n\r\n      if (score > 0) {\r\n        weightedPanSum += (long)panX2 * score;\r\n        weightedTiltSum += (long)tiltX2 * score;\r\n        totalSuccessfulProbes += score;\r\n        successfulPositions++;\r\n\r\n        int currentDistance =\r\n          abs(panX2 - originalPanX2) + abs(tiltX2 - originalTiltX2);\r\n        int bestDistance =\r\n          abs(bestPanX2 - originalPanX2) + abs(bestTiltX2 - originalTiltX2);\r\n\r\n        if (\r\n          score > bestScore || (score == bestScore && currentDistance < bestDistance)) {\r\n          bestScore = score;\r\n          bestPanX2 = panX2;\r\n          bestTiltX2 = tiltX2;\r\n        }\r\n      }\r\n    }\r\n  }\r\n\r\n  if (totalSuccessfulProbes == 0) {\r\n    moveMountHalfDegrees(originalPanX2, originalTiltX2);\r\n    delay(SERVO_SETTLE_MS);\r\n    alignmentLocked = false;\r\n    return false;\r\n  }\r\n\r\n  int centeredPanX2 =\r\n    (int)((weightedPanSum + totalSuccessfulProbes / 2) / totalSuccessfulProbes);\r\n  int centeredTiltX2 =\r\n    (int)((weightedTiltSum + totalSuccessfulProbes / 2) / totalSuccessfulProbes);\r\n\r\n  int centeredScore = scorePositionHalfDegrees(\r\n    centeredPanX2,\r\n    centeredTiltX2,\r\n    REFINEMENT_PROBES_PER_POINT);\r\n\r\n  // If the weighted center is unreliable, use the strongest measured point.\r\n  if (centeredScore == 0) {\r\n    centeredPanX2 = bestPanX2;\r\n    centeredTiltX2 = bestTiltX2;\r\n    centeredScore = scorePositionHalfDegrees(\r\n      centeredPanX2,\r\n      centeredTiltX2,\r\n      REFINEMENT_PROBES_PER_POINT);\r\n  }\r\n\r\n  lockedPanX2 = centeredPanX2;\r\n  lockedTiltX2 = centeredTiltX2;\r\n  alignmentLocked = true;\r\n  lastAlignmentCheck = millis();\r\n\r\n  Serial.print(\"REFINED P\");\r\n  printHalfDegreeValue(lockedPanX2);\r\n  Serial.print(\" T\");\r\n  printHalfDegreeValue(lockedTiltX2);\r\n  Serial.print(\" POINTS \");\r\n  Serial.print(successfulPositions);\r\n  Serial.print(\" SCORE \");\r\n  Serial.println(centeredScore);\r\n\r\n  return true;\r\n}\r\n\r\nvoid approachFinePosition(int panX100, int tiltX100) {\r\n  int preload = max(25, searchStepX100);\r\n  moveMountFineDegrees(panX100 - preload, tiltX100 - preload);\r\n  delay(BACKLASH_PRELOAD_MS);\r\n  moveMountFineDegrees(panX100, tiltX100);\r\n  delay(FINAL_LOCK_SETTLE_MS);\r\n}\r\n\r\nvoid printFinePosition(const char *prefix, int panX100, int tiltX100) {\r\n  Serial.println();\r\n  Serial.print(prefix);\r\n  Serial.print(\" P\"); Serial.print(panX100 / 100.0f, 2);\r\n  Serial.print(\" T\"); Serial.println(tiltX100 / 100.0f, 2);\r\n}\r\n\r\nbool cancelSearchRequested() {\r\n  // HOME is the only command accepted during a blocking alignment search.\r\n  if (!Serial.available() || (Serial.peek() != 'H' && Serial.peek() != 'h')) return false;\r\n  String request = Serial.readStringUntil('\\n');\r\n  request.trim();\r\n  if (!request.equalsIgnoreCase(\"home\")) return false;\r\n  activeAlignmentEnabled = false;\r\n  searchCancelled = true;\r\n  goHome();\r\n  printFinePosition(\"HOME\", PAN_HOME * 100, TILT_HOME * 100);\r\n  return true;\r\n}\r\n\r\nbool confirmCurrentLock() {\r\n  // A successful probe establishes the physical spot. Keep both servos still:\r\n  // an approach move can lose it through backlash on a direction reversal.\r\n  delay(FINAL_LOCK_SETTLE_MS);\r\n  int score = 0;\r\n  for (int probe = 0; probe < LOCK_CONFIRM_PROBES; probe++) {\r\n    if (cancelSearchRequested()) return false;\r\n    if (sendAlignmentProbe()) score++;\r\n    delay(SEARCH_PROBE_GAP_MS);\r\n  }\r\n  if (score < LOCK_CONFIRM_REQUIRED) {\r\n    alignmentLocked = false;\r\n    return false;\r\n  }\r\n  lockedPanX100 = currentPanX100;\r\n  lockedTiltX100 = currentTiltX100;\r\n  lockedPanX4 = currentPanX4;\r\n  lockedTiltX4 = currentTiltX4;\r\n  lockedPanX2 = (lockedPanX4 + 1) / 2;\r\n  lockedTiltX2 = (lockedTiltX4 + 1) / 2;\r\n  alignmentLocked = true;\r\n  hasEverLocked = true;\r\n  consecutiveMissedProbes = 0;\r\n  lastAlignmentCheck = millis();\r\n  printFinePosition(\"LOCK CONFIRMED\", lockedPanX100, lockedTiltX100);\r\n  Serial.print(\"LOCK SCORE \"); Serial.print(score); Serial.print(\"/\"); Serial.println(LOCK_CONFIRM_PROBES);\r\n  return true;\r\n}\r\n\r\nbool probePosition(int pan, int tilt) {\r\n  if (\r\n    pan < PAN_MIN || pan > PAN_MAX || tilt < TILT_MIN || tilt > TILT_MAX) {\r\n    return false;\r\n  }\r\n\r\n  moveMount(pan, tilt);\r\n  delay(SERVO_SETTLE_MS);\r\n\r\n  if (!sendAlignmentProbe()) {\r\n    return false;\r\n  }\r\n\r\n  // Hold exactly where the valid optical packet was detected.\r\n  lockedPanX2 = pan * 2;\r\n  lockedTiltX2 = tilt * 2;\r\n  alignmentLocked = true;\r\n  return true;\r\n}\r\n\r\nbool checkSearchPoint(int pan, int tilt) {\r\n  if (nearSearchTimed && !searchHasHit && millis()-nearSearchStarted >= 6000) return false;\r\n  if (cancelSearchRequested()) return false;\r\n  moveMountFineDegrees(pan, tilt);\r\n  delay(SEARCH_SETTLE_MS);\r\n  for (int probe = 0; probe < SEARCH_PROBES_PER_POINT; probe++) {\r\n    if (cancelSearchRequested()) return false;\r\n    if (sendAlignmentProbe()) {\r\n      if (!searchHasHit) {\r\n        searchHasHit = true;\r\n        firstHitPanX100 = currentPanX100;\r\n        firstHitTiltX100 = currentTiltX100;\r\n        printFinePosition(\"HIT NEAR\", firstHitPanX100, firstHitTiltX100);\r\n      }\r\n      if (confirmCurrentLock()) return true;\r\n    }\r\n    if (searchCancelled) return false;\r\n    delay(SEARCH_PROBE_GAP_MS);\r\n  }\r\n  return false;\r\n}\r\n\r\nbool refineHitNeighborhood() {\r\n  const int pan = firstHitPanX100, tilt = firstHitTiltX100;\r\n  unsigned long refinementStarted = millis();\r\n  // Sweep tilt monotonically before pan, rather than repeating horizontal rows.\r\n  for (int pass = 0; pass < 2 && millis()-refinementStarted < 6000; pass++) {\r\n    for (int axis = 0; axis < 2 && millis()-refinementStarted < 6000; axis++) {\r\n      for (int offset = -50; offset <= 50 && millis()-refinementStarted < 6000; offset += 50) {\r\n        int p = pan + (axis == 1 ? offset : 0);\r\n        int t = tilt + (axis == 0 ? offset : 0);\r\n        if (p < max(PAN_MIN*100, searchMinPan) || p > min(PAN_MAX*100, searchMaxPan) ||\r\n            t < max(TILT_MIN*100, searchMinTilt) || t > min(TILT_MAX*100, searchMaxTilt)) continue;\r\n        if (checkSearchPoint(p, t)) return true;\r\n        if (searchCancelled) return false;\r\n      }\r\n    }\r\n    const int diagonals[][2] = {{-50,-50},{50,-50},{50,50},{-50,50}};\r\n    for (int i = 0; i < 4 && millis()-refinementStarted < 6000; i++) {\r\n      int p = pan+diagonals[i][0], t = tilt+diagonals[i][1];\r\n      if (p < max(PAN_MIN*100, searchMinPan) || p > min(PAN_MAX*100, searchMaxPan) ||\r\n          t < max(TILT_MIN*100, searchMinTilt) || t > min(TILT_MAX*100, searchMaxTilt)) continue;\r\n      if (checkSearchPoint(p,t)) return true;\r\n      if (searchCancelled) return false;\r\n    }\r\n  }\r\n  moveMountFineDegrees(pan, tilt);\r\n  printFinePosition(\"HIT NEAR\", pan, tilt);\r\n  return false;\r\n}\r\n\r\nbool fineSpiralSearch(int centerPan, int centerTilt, int panRadius, int tiltRadius, int stepSize) {\r\n  searchHasHit = false;\r\n  searchMinPan = centerPan-panRadius; searchMaxPan = centerPan+panRadius;\r\n  searchMinTilt = centerTilt-tiltRadius; searchMaxTilt = centerTilt+tiltRadius;\r\n  if (checkSearchPoint(centerPan, centerTilt)) return true;\r\n  if (searchCancelled) return false;\r\n  if (searchHasHit) return refineHitNeighborhood();\r\n  // Vertical center line first, then horizontal. Each line runs in one\r\n  // direction through the center to reduce repeated backlash reversals.\r\n  for (int axis = 0; axis < 2; axis++) {\r\n    int radius = axis == 0 ? tiltRadius : panRadius;\r\n    for (int offset = -radius; offset <= radius; offset += stepSize) {\r\n      int p = centerPan+(axis == 1 ? offset : 0);\r\n      int t = centerTilt+(axis == 0 ? offset : 0);\r\n      if (p < PAN_MIN*100 || p > PAN_MAX*100 || t < TILT_MIN*100 || t > TILT_MAX*100) continue;\r\n      if (checkSearchPoint(p,t)) return true;\r\n      if (searchCancelled) return false;\r\n      if (searchHasHit) return refineHitNeighborhood();\r\n    }\r\n  }\r\n  // Remaining off-axis points, still bounded to the requested neighborhood.\r\n  for (int y = -tiltRadius; y <= tiltRadius; y += stepSize) {\r\n    if (y == 0) continue;\r\n    for (int x = -panRadius; x <= panRadius; x += stepSize) {\r\n      if (x == 0) continue;\r\n      int p = centerPan+x, t = centerTilt+y;\r\n      if (p < PAN_MIN*100 || p > PAN_MAX*100 || t < TILT_MIN*100 || t > TILT_MAX*100) continue;\r\n      if (checkSearchPoint(p,t)) return true;\r\n      if (searchCancelled) return false;\r\n      if (searchHasHit) return refineHitNeighborhood();\r\n    }\r\n  }\r\n  return false;\r\n}\r\n\r\nbool localReacquire() {\r\n  searchCancelled = false;\r\n  int pan = lockedPanX100, tilt = lockedTiltX100;\r\n  if (fineSpiralSearch(pan, tilt, 50, 50, 50)) return true;\r\n  if (searchCancelled || searchHasHit) return false;\r\n  approachFinePosition(pan, tilt);\r\n  alignmentLocked = true;\r\n  return false;\r\n}\r\n\r\nbool searchForReceiver() {\r\n  searchCancelled = false;\r\n  alignmentLocked = false;\r\n  Serial.println(\"LOCAL SEARCH - NEAR POSITION 2 FIRST\");\r\n  if (fineSpiralSearch(searchPanX100, searchTiltX100, 100, 100,\r\n                       min(searchStepX100, 25))) return true;\r\n  if (searchCancelled || searchHasHit) return false;\r\n  for (int pass = 1; pass <= SEARCH_PASSES; pass++) {\r\n    Serial.println();\r\n    Serial.print(\"ALIGN SEARCH PASS \"); Serial.print(pass); Serial.print(\"/\"); Serial.println(SEARCH_PASSES);\r\n    printFinePosition(\"SEARCH START\", searchPanX100, searchTiltX100);\r\n    if (fineSpiralSearch(searchPanX100, searchTiltX100, SEARCH_PAN_RADIUS * 100,\r\n                         SEARCH_TILT_RADIUS * 100, searchStepX100)) return true;\r\n    if (searchCancelled || searchHasHit) return false;\r\n  }\r\n  moveMountFineDegrees(searchPanX100, searchTiltX100);\r\n  alignmentLocked = false;\r\n  return false;\r\n}\r\n\r\nvoid maintainAlignment() {\r\n  if (!activeAlignmentEnabled || !alignmentLocked || Serial.available()) {\r\n    return;\r\n  }\r\n\r\n  if (millis() - lastAlignmentCheck < ACTIVE_CHECK_INTERVAL_MS) {\r\n    return;\r\n  }\r\n\r\n  lastAlignmentCheck = millis();\r\n\r\n  // A normal tracking check never commands either servo.\r\n  if (sendAlignmentProbe()) {\r\n    consecutiveMissedProbes = 0;\r\n    return;\r\n  }\r\n\r\n  consecutiveMissedProbes++;\r\n\r\n  Serial.print(\"MISSED PROBE \");\r\n  Serial.print(consecutiveMissedProbes);\r\n  Serial.print(\"/\");\r\n  Serial.println(MISSED_PROBES_BEFORE_MOVE);\r\n\r\n  if (consecutiveMissedProbes < MISSED_PROBES_BEFORE_MOVE) {\r\n    return;\r\n  }\r\n\r\n  consecutiveMissedProbes = 0;\r\n  alignmentLocked = false;\r\n  Serial.println(\"LOCK LOST - HOLDING POSITION; USE CV AIM TO REALIGN\");\r\n}\r\n\r\nbool ensureAlignmentForMessage() {\r\n  // User content always goes out at the current position. Background loss\r\n  // must not turn a send or baud change into an unrequested servo search.\r\n  setLaserSolid(false);\r\n  return true;\r\n}\r\n\r\nvoid setupAlignment() {\r\n  panServo.setPeriodHertz(50);\r\n  tiltServo.setPeriodHertz(50);\r\n\r\n  panServo.attach(PAN_PIN, 500, 2500);\r\n  tiltServo.attach(TILT_PIN, 500, 2500);\r\n\r\n  // ESP32Servo 3.1.3 resets resolution to 10 bits inside attach(),\r\n  // despite its comment recommending setTimerWidth() before attach.\r\n  // Set it afterwards: 16 bits at 50 Hz gives 0.305 us PWM ticks\r\n  // instead of 19.53 us (about 1.76 degrees with these endpoints).\r\n  panServo.setTimerWidth(16);\r\n  tiltServo.setTimerWidth(16);\r\n\r\n  goHome();\r\n  delay(500);\r\n\r\n  WiFi.mode(WIFI_STA);\r\n  WiFi.disconnect();\r\n  esp_wifi_set_channel(ESPNOW_CHANNEL, WIFI_SECOND_CHAN_NONE);\r\n\r\n  if (esp_now_init() != ESP_OK) {\r\n    Serial.println(\"ESP-NOW INIT FAILED\");\r\n    return;\r\n  }\r\n\r\n  if (esp_now_register_recv_cb(onEspNowReceive) != ESP_OK) {\r\n    Serial.println(\"ESP-NOW RECEIVE CALLBACK FAILED\");\r\n    return;\r\n  }\r\n  esp_now_peer_info_t speedPeer = {};\r\n  memcpy(speedPeer.peer_addr, speedBroadcast, 6);\r\n  speedPeer.channel = ESPNOW_CHANNEL;\r\n  esp_err_t peerResult = esp_now_add_peer(&speedPeer);\r\n  if (peerResult != ESP_OK && peerResult != ESP_ERR_ESPNOW_EXIST) {\r\n    Serial.print(\"ESP-NOW SPEED PEER FAILED, CODE \");\r\n    Serial.println((int)peerResult);\r\n    return;\r\n  }\r\n  speedControlReady = true;\r\n  Serial.println(\"Runtime speed control ready, channel 1\");\r\n}\r\n\r\n\r\n// ============================================================\r\n// SEND NORMAL TEXT\r\n// ============================================================\r\n\r\nvoid sendText(String message) {\r\n\r\n  uint16_t length = message.length();\r\n\r\n  sendHeader(TYPE_TEXT, length);\r\n\r\n  for (uint16_t i = 0; i < length; i++) {\r\n    Serial.write(message[i]);\r\n  }\r\n\r\n  Serial.flush();\r\n}\r\n\r\n\r\n// ============================================================\r\n// START LONG SCRIPT\r\n// ============================================================\r\n\r\nvoid startScript() {\r\n\r\n  sendHeader(TYPE_SCRIPT_START, 0);\r\n\r\n  Serial.flush();\r\n\r\n  scriptMode = true;\r\n}\r\n\r\n\r\n// ============================================================\r\n// SEND ONE SCRIPT LINE\r\n// ============================================================\r\n\r\nvoid sendScriptLine(String line) {\r\n\r\n  // Add newline back because readStringUntil removes it\r\n  uint16_t length = line.length() + 1;\r\n\r\n  sendHeader(TYPE_SCRIPT_CHUNK, length);\r\n\r\n  for (uint16_t i = 0; i < line.length(); i++) {\r\n    Serial.write(line[i]);\r\n  }\r\n\r\n  Serial.write('\\n');\r\n\r\n  Serial.flush();\r\n}\r\n\r\n\r\n// ============================================================\r\n// END SCRIPT\r\n// ============================================================\r\n\r\nvoid endScript() {\r\n\r\n  sendHeader(TYPE_SCRIPT_END, 0);\r\n\r\n  Serial.flush();\r\n\r\n  scriptMode = false;\r\n}\r\n\r\nbool receiveUsbImage() {\r\n  size_t received = 0;\r\n  unsigned long lastByteTime = millis();\r\n\r\n  while (received < IMAGE_SIZE) {\r\n    // Drain every available byte before yielding. A delay per byte would\r\n    // cap ingestion near 1000 bytes/s even when baud is much higher.\r\n    while (Serial.available() && received < IMAGE_SIZE) {\r\n      int value = Serial.read();\r\n      if (value >= 0) {\r\n        usbImageBuffer[received++] = (uint8_t)value;\r\n        lastByteTime = millis();\r\n      }\r\n    }\r\n\r\n    if (received < IMAGE_SIZE) {\r\n      if (millis() - lastByteTime > 5000) {\r\n        Serial.println(\"IMAGE RECEIVE TIMEOUT\");\r\n        return false;\r\n      }\r\n      delay(1);\r\n    }\r\n  }\r\n  return true;\r\n}\r\n// ============================================================\r\n// SEND IMAGE\r\n// ============================================================\r\nvoid sendImageData(const uint8_t *imageData) {\r\n  sendHeader(TYPE_IMAGE, IMAGE_SIZE);\r\n\r\n  Serial.write(imageData, IMAGE_SIZE);\r\n\r\n  Serial.flush();\r\n}\r\n\r\nvoid sendImage() {\r\n\r\n  sendHeader(TYPE_IMAGE, IMAGE_SIZE);\r\n\r\n  for (int i = 0; i < IMAGE_SIZE; i++) {\r\n\r\n    uint8_t b =\r\n      pgm_read_byte(&bitmap[i]);\r\n\r\n    Serial.write(b);\r\n  }\r\n\r\n  Serial.flush();\r\n}\r\n\r\n\r\n// Change the receiver over radio before switching the shared USB/laser UART.\r\nvoid changeLinkSpeed(uint32_t baud) {\r\n  if (!speedControlReady) {\r\n    Serial.println(\"BAUD ERROR transmitter ESP-NOW setup failed\");\r\n    return;\r\n  }\r\n  if (!supportedBaud(baud)) {\r\n    Serial.println(\"BAUD ERROR unsupported rate\");\r\n    return;\r\n  }\r\n  speedAckBaud = 0;\r\n  SpeedMessage request = {SPEED_MAGIC, baud, 0};\r\n  for (int retry = 0; retry < 6 && speedAckBaud != baud; retry++) {\r\n    esp_err_t sendResult = esp_now_send(speedBroadcast, (uint8_t *)&request, sizeof(request));\r\n    if (sendResult != ESP_OK) {\r\n      Serial.print(\"BAUD ERROR ESP-NOW request send failed, code \");\r\n      Serial.println((int)sendResult);\r\n      return;\r\n    }\r\n    unsigned long started = millis();\r\n    while (millis() - started < 150 && speedAckBaud != baud) delay(1);\r\n  }\r\n  if (speedAckBaud != baud) {\r\n    Serial.println(\"BAUD ERROR receiver did not acknowledge; retry or reset both boards\");\r\n    return;\r\n  }\r\n  Serial.println();\r\n  Serial.print(\"BAUD OK \");\r\n  Serial.println(baud);\r\n  Serial.flush();\r\n  delay(100); // Let the laptop read the response at the old rate.\r\n  Serial.updateBaudRate(baud);\r\n  lastAlignmentCheck = millis();\r\n}\r\n\r\nbool prepareDinoReceiver(uint32_t action) {\r\n  if (!speedControlReady) return false;\r\n  targetAckValue = 0;\r\n  SpeedMessage request = {TARGET_MAGIC, action, 0};\r\n  for (int attempt = 0; attempt < 6 && targetAckValue != action; attempt++) {\r\n    esp_now_send(speedBroadcast, (uint8_t *)&request, sizeof(request));\r\n    unsigned long started = millis();\r\n    while (millis()-started < 150 && targetAckValue != action) delay(1);\r\n  }\r\n  return targetAckValue == action;\r\n}\r\n\r\nvoid runSpeedTest() {\r\n  // Test the complete laptop -> USB -> laser path with laptop-generated data.\r\n  if (!receiveUsbImage()) {\r\n    Serial.println(\"TEST TIMEOUT\");\r\n    return;\r\n  }\r\n  uint32_t sequence = ((uint32_t)usbImageBuffer[0] << 24) |\r\n                      ((uint32_t)usbImageBuffer[1] << 16) |\r\n                      ((uint32_t)usbImageBuffer[2] << 8) | usbImageBuffer[3];\r\n  testAckSequence = 0;\r\n  sendHeader(0x07, IMAGE_SIZE);\r\n  Serial.write(usbImageBuffer, IMAGE_SIZE);\r\n  Serial.flush();\r\n  unsigned long started = millis();\r\n  while (millis() - started < 1200 && testAckSequence != sequence) delay(1);\r\n  Serial.println();\r\n  if (testAckSequence == sequence) {\r\n    Serial.print(\"TEST RESULT \");\r\n    Serial.print(sequence);\r\n    Serial.print(\" \");\r\n    Serial.println(testAckErrors);\r\n  } else {\r\n    Serial.println(\"TEST TIMEOUT\");\r\n  }\r\n}\r\n\r\n// ============================================================\r\n// SETUP\r\n// ============================================================\r\n\r\nvoid setup() {\r\n  digitalWrite(LASER_OVERRIDE_PIN, LOW);\r\n  pinMode(LASER_OVERRIDE_PIN, OUTPUT);\r\n\r\n  // GPIO1 TX -> laser\r\n  // GPIO3 RX <- USB serial\r\n  // Hold a complete incoming image while an alignment search is running.\r\n  Serial.setRxBufferSize(2048);\r\n  Serial.begin(LINK_BAUD);\r\n\r\n  Serial.setTimeout(100);\r\n\r\n  setupAlignment();\r\n}\r\n\r\n\r\n// ============================================================\r\n// LOOP\r\n// ============================================================\r\n\r\nvoid loop() {\r\n\r\n  while (Serial.available()) {\r\n\r\n    String line =\r\n      Serial.readStringUntil('\\n');\r\n\r\n    // Remove CR from Windows/Serial Monitor\r\n    if (line.endsWith(\"\\r\")) {\r\n      line.remove(line.length() - 1);\r\n    }\r\n\r\n\r\n    // ========================================================\r\n    // SCRIPT MODE\r\n    // ========================================================\r\n\r\n    if (scriptMode) {\r\n\r\n      if (line == \"ENDSCRIPT\") {\r\n\r\n        endScript();\r\n      }\r\n\r\n      else {\r\n        if (ensureAlignmentForMessage()) {\r\n          sendScriptLine(line);\r\n        }\r\n      }\r\n\r\n      continue;\r\n    }\r\n\r\n\r\n    // ========================================================\r\n    // NORMAL COMMAND MODE\r\n    // ========================================================\r\n    String command = line;\r\n    command.trim();\r\n\r\n\r\n    if (command.length() == 0) {\r\n      continue;\r\n    }\r\n\r\n\r\n    if (command == \"LASER SOLID\" || command == \"LASER TX\") {\r\n      if (command == \"LASER SOLID\") activeAlignmentEnabled = false;\r\n      setLaserSolid(command == \"LASER SOLID\");\r\n      Serial.println(command == \"LASER SOLID\" ? \"LASER SOLID OK\" : \"LASER TX OK\");\r\n      continue;\r\n    }\r\n\r\n    if (command.startsWith(\"BAUD \")) {\r\n      changeLinkSpeed(command.substring(5).toInt());\r\n      continue;\r\n    }\r\n    if (command == \"BENCH ON\" || command == \"BENCH OFF\") {\r\n      benchmarkMode = command == \"BENCH ON\";\r\n      lastAlignmentCheck = millis();\r\n      Serial.println(\"BENCH OK\");\r\n      continue;\r\n    }\r\n    if (command == \"SPEEDTEST\") {\r\n      runSpeedTest();\r\n      continue;\r\n    }\r\n    if (command == \"DINO START\") {\r\n      activeAlignmentEnabled = false;\r\n      setLaserSolid(false);\r\n      bool ready = prepareDinoReceiver(4);\r\n      Serial.println();\r\n      Serial.println(ready ? \"DINO READY\" : \"DINO ERROR receiver did not acknowledge start\");\r\n      continue;\r\n    }\r\n    if (command == \"DINO STOP\") {\r\n      activeAlignmentEnabled = false;\r\n      setLaserSolid(false);\r\n      bool stopped = prepareDinoReceiver(5);\r\n      Serial.println();\r\n      Serial.println(stopped ? \"DINO STOPPED\" : \"DINO ERROR receiver did not acknowledge stop\");\r\n      continue;\r\n    }\r\n    if (command == \"DINO\") {\r\n      uint8_t scene[19];\r\n      size_t count = 0;\r\n      unsigned long lastByte = millis();\r\n      while (count < sizeof(scene) && millis()-lastByte < 500) {\r\n        while (Serial.available() && count < sizeof(scene)) {\r\n          scene[count++] = (uint8_t)Serial.read();\r\n          lastByte = millis();\r\n        }\r\n        if (count < sizeof(scene)) delay(1);\r\n      }\r\n      if (count == sizeof(scene)) {\r\n        sendHeader(0x08, sizeof(scene));\r\n        Serial.write(scene, sizeof(scene));\r\n        Serial.flush();\r\n      } else Serial.println(\"DINO RECEIVE TIMEOUT\");\r\n      continue;\r\n    }\r\n\r\n    // IMAGE is followed by exactly 1024 binary bytes, not a text line.\r\n    if (command.equalsIgnoreCase(\"image\")) {\r\n      // Consume USB data before any blocking alignment search.\r\n      if (receiveUsbImage() && ensureAlignmentForMessage()) {\r\n        sendImageData(usbImageBuffer);\r\n      }\r\n      continue;\r\n    }\r\n\r\n\r\n    // App supplies Position 2 and selected automatic step at each search.\r\n    if (command.equalsIgnoreCase(\"target\") || command.equalsIgnoreCase(\"blank\") || command.equalsIgnoreCase(\"display\") || command == \"CVPREP\") {\r\n      if (!speedControlReady) {\r\n        Serial.println(\"ALIGN ERROR target radio unavailable\");\r\n        continue;\r\n      }\r\n      if (command == \"CVPREP\") {\r\n        activeAlignmentEnabled = false;\r\n        setLaserSolid(true);\r\n      }\r\n      if (command.equalsIgnoreCase(\"display\")) setLaserSolid(false);\r\n      SpeedMessage request = {TARGET_MAGIC, (command.equalsIgnoreCase(\"blank\") || command == \"CVPREP\") ? 2UL : command.equalsIgnoreCase(\"display\") ? 3UL : 1UL, 0};\r\n      bool sent = false;\r\n      for (int attempt = 0; attempt < 3; attempt++) {\r\n        if (esp_now_send(speedBroadcast, (uint8_t *)&request, sizeof(request)) == ESP_OK) sent = true;\r\n        delay(80);\r\n      }\r\n      if (!sent && command == \"CVPREP\") setLaserSolid(false);\r\n      Serial.println(sent ? \"TARGET REQUEST SENT\" : \"ALIGN ERROR target request failed\");\r\n      continue;\r\n    }\r\n\r\n    if (command.equalsIgnoreCase(\"verify\")) {\r\n      // CV owns all positioning. Verify packets without a preload, nudge,\r\n      // spiral or any servo command, including when confirmation fails.\r\n      searchCancelled = false;\r\n      alignmentLocked = false;\r\n      activeAlignmentEnabled = true;\r\n      setLaserSolid(false);\r\n      if (confirmCurrentLock()) printFinePosition(\"LOCK\", lockedPanX100, lockedTiltX100);\r\n      else if (!searchCancelled) {\r\n        activeAlignmentEnabled = false;\r\n        Serial.println(\"VERIFY FAILED - HELD POSITION\");\r\n      }\r\n      continue;\r\n    }\r\n\r\n    if (command.startsWith(\"ALIGNPOS \") || command.startsWith(\"ALIGNNEAR \")) {\r\n      bool nearOnly = command.startsWith(\"ALIGNNEAR \");\r\n      float pan, tilt, step;\r\n      float nearRadius = 1.0f;\r\n      if (nearOnly) {\r\n        float requestedRadius;\r\n        if (sscanf(command.c_str(), \"ALIGNNEAR P%f T%f S%f R%f\", &pan, &tilt, &step, &requestedRadius) == 4) nearRadius = requestedRadius;\r\n      }\r\n      if (!isfinite(nearRadius) || nearRadius < 0.1f || nearRadius > 1.0f) {\r\n        Serial.println(\"ALIGN ERROR invalid near radius\");\r\n        continue;\r\n      }\r\n      if (sscanf(command.c_str(), nearOnly ? \"ALIGNNEAR P%f T%f S%f\" : \"ALIGNPOS P%f T%f S%f\", &pan, &tilt, &step) != 3 ||\r\n          !isfinite(pan) || !isfinite(tilt) || !isfinite(step) ||\r\n          pan < PAN_MIN || pan > PAN_MAX || tilt < TILT_MIN || tilt > TILT_MAX ||\r\n          (fabsf(step - 0.1f) > 0.001f && fabsf(step - 0.25f) > 0.001f &&\r\n           fabsf(step - 0.5f) > 0.001f && fabsf(step - 1.0f) > 0.001f)) {\r\n        Serial.println(\"ALIGN ERROR invalid position or step\");\r\n        continue;\r\n      }\r\n      searchPanX100 = lroundf(pan * 100);\r\n      searchTiltX100 = lroundf(tilt * 100);\r\n      searchStepX100 = lroundf(step * 100);\r\n      activeAlignmentEnabled = true;\r\n      bool found;\r\n      if (nearOnly) {\r\n        searchCancelled = false;\r\n        alignmentLocked = false;\r\n        printFinePosition(\"SEARCH START\", searchPanX100, searchTiltX100);\r\n        int radius = lroundf(nearRadius * 100);\r\n        nearSearchStarted = millis();\r\n        nearSearchTimed = true;\r\n        found = fineSpiralSearch(searchPanX100, searchTiltX100, radius, radius, searchStepX100);\r\n        nearSearchTimed = false;\r\n        if (!found && !searchCancelled && !searchHasHit) moveMountFineDegrees(searchPanX100, searchTiltX100);\r\n      } else {\r\n        found = searchForReceiver();\r\n      }\r\n      if (found) printFinePosition(\"LOCK\", lockedPanX100, lockedTiltX100);\r\n      else if (!searchCancelled) Serial.println(searchHasHit ? \"NO RECEIVER FOUND - HELD HIT POSITION\" : \"NO RECEIVER FOUND - RETURNED SEARCH START\");\r\n      continue;\r\n    }\r\n\r\n    // Find the receiver and optionally send text immediately:\r\n    // ALIGN Hello from the laser\r\n    if (\r\n      command.equalsIgnoreCase(\"align\") || (command.length() >= 6 && command.substring(0, 6).equalsIgnoreCase(\"align \"))) {\r\n      activeAlignmentEnabled = true;\r\n\r\n      String message = \"\";\r\n\r\n      if (line.length() > 6) {\r\n        message = line.substring(6);\r\n      }\r\n\r\n      if (searchForReceiver()) {\r\n        printFinePosition(\"LOCK\", lockedPanX100, lockedTiltX100);\r\n\r\n        delay(50);\r\n\r\n        if (message.length() > 0) {\r\n          sendText(message);\r\n        }\r\n      } else if (!searchCancelled) {\r\n        Serial.println(\"NO RECEIVER FOUND - RETURNED SEARCH START\");\r\n      }\r\n\r\n      continue;\r\n    }\r\n\r\n\r\n    // Return to the configured home position.\r\n    if (command.equalsIgnoreCase(\"home\")) {\r\n      setLaserSolid(false);\r\n      activeAlignmentEnabled = false;\r\n      goHome();\r\n      Serial.print(\"HOME P\");\r\n      Serial.print(PAN_HOME);\r\n      Serial.print(\" T\");\r\n      Serial.println(TILT_HOME);\r\n      continue;\r\n    }\r\n\r\n\r\n    // Manual position command supports fractions, for example P55.10 T116.05.\r\n    float manualPan;\r\n    float manualTilt;\r\n    if (sscanf(command.c_str(), \"P%f T%f\", &manualPan, &manualTilt) == 2 ||\r\n        sscanf(command.c_str(), \"p%f t%f\", &manualPan, &manualTilt) == 2) {\r\n      if (!isfinite(manualPan) || !isfinite(manualTilt)) continue;\r\n      int panX100 = (int)lroundf(constrain(manualPan, (float)PAN_MIN, (float)PAN_MAX) * 100);\r\n      int tiltX100 = (int)lroundf(constrain(manualTilt, (float)TILT_MIN, (float)TILT_MAX) * 100);\r\n      moveMountFineDegrees(panX100, tiltX100);\r\n      lockedPanX100 = currentPanX100;\r\n      lockedTiltX100 = currentTiltX100;\r\n      lockedPanX4 = currentPanX4;\r\n      lockedTiltX4 = currentTiltX4;\r\n      lockedPanX2 = (lockedPanX4 + 1) / 2;\r\n      lockedTiltX2 = (lockedTiltX4 + 1) / 2;\r\n      alignmentLocked = false;\r\n      activeAlignmentEnabled = false;\r\n      Serial.print(\"MOVED P\");\r\n      Serial.print(panX100 / 100.0f, 2);\r\n      Serial.print(\" T\");\r\n      Serial.println(tiltX100 / 100.0f, 2);\r\n      continue;\r\n    }\r\n\r\n\r\n    // Send stored image\r\n    if (command.equalsIgnoreCase(\"send\")) {\r\n      if (ensureAlignmentForMessage()) {\r\n        sendImage();\r\n      }\r\n    }\r\n\r\n\r\n    // Begin huge text transmission\r\n    else if (command.equalsIgnoreCase(\"script\")) {\r\n      if (ensureAlignmentForMessage()) {\r\n        startScript();\r\n      }\r\n    }\r\n\r\n\r\n    // Normal text message\r\n    else {\r\n      if (ensureAlignmentForMessage()) {\r\n        sendText(line);\r\n      }\r\n    }\r\n  }\r\n\r\n  if (pendingSolidHit && laserSolidEnabled) {\r\n    pendingSolidHit = false;\r\n    printFinePosition(\"CV HIT\", currentPanX100, currentTiltX100);\r\n  }\r\n  if (!benchmarkMode) maintainAlignment();\r\n}\r\n"}],"id":"6a9b7e82-b90d-4be2-8b2f-27d808bd6f28"},{"type":"code","heading":"Transmitter App","files":[{"type":"code","heading":"Code","filename":"laser_text_terminal.py","language":"Python","code":"import json\r\nimport re\r\nimport math\r\nimport time\r\nimport queue\r\nimport threading\r\nimport tkinter as tk\r\nfrom tkinter import filedialog, messagebox\r\nfrom datetime import datetime\r\nfrom pathlib import Path\r\n\r\nimport serial\r\nfrom PIL import Image, ImageTk\r\nfrom laser_animation import convert_frame, load_animation, walking_frames, horse_frames\r\nfrom laser_dino import DinoGame\r\n\r\n\r\nPORT = \"COM4\"\r\n# Boot at firmware LINK_BAUD, then negotiate the desired runtime rate.\r\nBAUD_RATE = 38400\r\nBOOT_BAUD_RATE = 38400\r\nSPEED_RATES = (9600, 19200, 38400, 57600, 115200, 230400,\r\n               460800, 921600, 1000000, 1500000, 2000000,\r\n               2500000, 3000000, 4000000, 5000000)\r\nMAX_MESSAGE_BYTES = 512\r\nSERVO_MIN = 0\r\nSERVO_MAX = 180\r\nPAN_HOME = 41\r\nTILT_HOME = 104\r\nPOSITION_FILE = Path(__file__).resolve().with_name(\"alignment_positions.json\")\r\n\r\nIMAGE_WIDTH = 128\r\nIMAGE_HEIGHT = 64\r\nIMAGE_SIZE = 1024\r\nIMAGE_THRESHOLD = 128\r\n\r\n# Keeps the history between app launches.\r\nHISTORY_FOLDER = Path.home() / \"LaserTextTerminal\"\r\nHISTORY_FILE = HISTORY_FOLDER / \"sent_messages.jsonl\"\r\n\r\n\r\ndef speed_test_payload(sequence):\r\n    payload = bytearray(sequence.to_bytes(4, \"big\"))\r\n    state = sequence\r\n    for _ in range(IMAGE_SIZE - 4):\r\n        state = (state * 1664525 + 1013904223) & 0xFFFFFFFF\r\n        payload.append(state >> 24)\r\n    return bytes(payload)\r\n\r\n\r\ndef alignment_status_line(raw):\r\n    # Optical packets and diagnostics share TX. Probe bytes may precede a log line.\r\n    line = raw.decode(\"ascii\", errors=\"ignore\").strip()\r\n    # Accept intact acknowledgment words even when UART drops separators.\r\n    # Do not infer success from a partially corrupted phrase.\r\n    if re.search(r\"(?<![A-Z])TARGET\\s*REQUEST\\s*SENT\\s*$\", line):\r\n        return \"TARGET REQUEST SENT\"\r\n    match = re.search(r\"CV HIT P|HIT NEAR P|LOCK P|LOCK CONFIRMED P|LOCK REACQUIRED|LOCK LOST|LOCAL SEARCH|SEARCH PASS|SEARCH START|ALIGN ERROR|NO RECEIVER FOUND|HOME P|MOVED P|MISSED PROBE|TARGET REQUEST SENT|LASER SOLID OK|LASER TX OK|VERIFY FAILED\", line)\r\n    return line[match.start():] if match else \"\"\r\n\r\n\r\nclass LaserTextTerminal:\r\n    def __init__(self, root):\r\n        self.root = root\r\n        self.root.title(\"Laser Text Terminal\")\r\n        icon_path = Path(__file__).resolve().parent / \"assets\" / \"laser_horse.ico\"\r\n        if icon_path.exists():\r\n            self.root.iconbitmap(str(icon_path))\r\n        self.root.minsize(1200, 720)\r\n\r\n        # Maximize the window on Windows.\r\n        if not getattr(self.root, \"startup_hidden\", False):\r\n            self.root.state(\"zoomed\")\r\n\r\n        self.connection = None\r\n        self.busy = False\r\n        self.tracking_mode = tk.StringVar(value=\"Phone camera (stationary)\")\r\n        self.active_tracking_mode = \"Phone camera (stationary)\"\r\n        self.mode_switch_pending = False\r\n        self.manual_mode = tk.BooleanVar(value=False)\r\n        self.laser_solid = False\r\n        self.manual_pressed_keys = set()\r\n        self.manual_active_keys = set()\r\n        self.manual_hold_job = None\r\n        self.job_kind = None\r\n        self.nudge_step = tk.StringVar(value=\"0.5\")\r\n        self.search_step = tk.StringVar(value=\"0.25\")\r\n        self.position2_pan = tk.StringVar(value=str(PAN_HOME))\r\n        self.position2_tilt = tk.StringVar(value=str(TILT_HOME))\r\n        self.load_position2()\r\n        self.pan_angle = tk.StringVar(value=str(PAN_HOME))\r\n        self.tilt_angle = tk.StringVar(value=str(TILT_HOME))\r\n        self.alignment_status = tk.StringVar(value=\"Servo mount: pan GPIO 13, tilt GPIO 14. Position not yet confirmed.\")\r\n        self.idle_serial_buffer = bytearray()\r\n        self.animation_fps = tk.IntVar(value=5)\r\n        self.test_sequence = 0\r\n        self.worker_events = queue.Queue()\r\n        self.speed_choice = tk.StringVar(value=str(BAUD_RATE))\r\n        self.selected_image_path = None\r\n        self.image_payload = None\r\n        self.preview_photo = None\r\n        self.image_fit = tk.StringVar(value=\"Fit whole image\")\r\n        self.image_dither = tk.BooleanVar(value=False)\r\n        self.image_invert = tk.BooleanVar(value=False)\r\n        self.image_threshold = tk.IntVar(value=IMAGE_THRESHOLD)\r\n\r\n        self.build_interface()\r\n        self.vision_window = None\r\n        self.open_vision()\r\n        if self.vision_window is not None:\r\n            self.root.after(100, self.vision_window.open_camera)\r\n        for key in (\"Left\", \"Right\", \"Up\", \"Down\", \"w\", \"a\", \"s\", \"d\", \"W\", \"A\", \"S\", \"D\"):\r\n            self.root.bind(f\"<KeyPress-{key}>\", self.on_mount_arrow)\r\n            self.root.bind(f\"<KeyRelease-{key}>\", self.on_key_release)\r\n        for key in (\"l\", \"L\", \"m\", \"M\", \"p\", \"P\", \"h\", \"H\", \"o\", \"O\", \"t\", \"T\", \"u\", \"U\", \"g\", \"G\"):\r\n            self.root.bind(f\"<KeyPress-{key}>\", self.on_shortcut)\r\n            self.root.bind(f\"<KeyRelease-{key}>\", self.on_key_release)\r\n        self.root.bind(\"<FocusOut>\", lambda event: self.stop_manual_hold())\r\n        self.root.bind(\"<space>\", self.on_dino_jump)\r\n        self.root.bind('<Control-t>', self.toggle_typing)\r\n        self.root.bind('<Control-T>', self.toggle_typing)\r\n        self.root.bind('<Escape>', self.leave_typing)\r\n        self.load_history()\r\n        self.root.after(0, lambda: self.connect(automatic=True))\r\n        self.root.after(100, self.poll_worker)\r\n\r\n        self.root.protocol(\"WM_DELETE_WINDOW\", self.close_app)\r\n\r\n    def build_interface(self):\r\n        recovery = tk.Frame(self.root, padx=8, pady=4)\r\n        recovery.pack(side=\"bottom\", fill=\"x\")\r\n        tk.Button(recovery, text=\"Stop / Home\", command=self.emergency_home).pack(side=\"left\")\r\n        tk.Label(recovery, text=\"Stops CV and cancels the current command before returning Home.\").pack(side=\"left\", padx=8)\r\n        split = tk.PanedWindow(self.root, orient=\"horizontal\", sashwidth=8)\r\n        split.pack(fill=\"both\", expand=True)\r\n        self.terminal_panel = tk.Frame(split)\r\n        self.camera_panel = tk.Frame(split, padx=8, pady=8)\r\n        self.camera_mode_bar = tk.Frame(self.camera_panel)\r\n        self.camera_mode_bar.pack(fill=\"x\")\r\n        tk.Label(self.camera_mode_bar, text=\"Tracking mode:\").pack(side=\"left\")\r\n        tk.OptionMenu(self.camera_mode_bar, self.tracking_mode, \"Phone camera (stationary)\", \"Mount camera (LED)\", command=self.switch_tracking_mode).pack(side=\"left\")\r\n        split.add(self.terminal_panel, minsize=480, width=560, stretch=\"never\")\r\n        split.add(self.camera_panel, minsize=640, stretch=\"always\")\r\n        self.terminal_panel.rowconfigure(1, weight=1)\r\n        self.terminal_panel.columnconfigure(0, weight=1)\r\n\r\n        # Top bar\r\n        top_bar = tk.Frame(self.terminal_panel, padx=12, pady=10)\r\n        top_bar.grid(row=0, column=0, sticky=\"ew\")\r\n        top_bar.columnconfigure(0, weight=1)\r\n\r\n        tk.Label(\r\n            top_bar,\r\n            text=\"Laser Text Terminal\",\r\n            font=(\"Segoe UI\", 16, \"bold\")\r\n        ).grid(row=0, column=0, sticky=\"w\")\r\n\r\n        self.status_label = tk.Label(\r\n            top_bar,\r\n            text=f\"Connecting to {PORT}...\",\r\n            font=(\"Segoe UI\", 10)\r\n        )\r\n        self.status_label.grid(row=1, column=0, sticky=\"w\", pady=(4, 0))\r\n\r\n        self.connect_button = tk.Button(\r\n            top_bar,\r\n            text=\"Reconnect\",\r\n            command=self.connect\r\n        )\r\n        self.connect_button.grid(row=0, column=1, rowspan=2, padx=8)\r\n\r\n        speed_bar = tk.Frame(top_bar)\r\n        speed_bar.grid(row=2, column=0, columnspan=2, sticky=\"w\", pady=(8, 0))\r\n        tk.Label(speed_bar, text=\"Link baud:\").pack(side=\"left\")\r\n        self.speed_menu = tk.OptionMenu(speed_bar, self.speed_choice, *map(str, SPEED_RATES))\r\n        self.speed_menu.pack(side=\"left\")\r\n        self.apply_speed_button = tk.Button(speed_bar, text=\"Apply Speed\", command=lambda: self.start_speed_job(\"apply\"))\r\n        self.apply_speed_button.pack(side=\"left\", padx=4)\r\n\r\n\r\n        self.stop_speed_button = tk.Button(speed_bar, text=\"Stop\", state=\"disabled\", command=self.stop_speed_job)\r\n        self.stop_speed_button.pack(side=\"left\", padx=4)\r\n\r\n        alignment_bar = tk.LabelFrame(top_bar, text=\"Servo mount / alignment\", padx=8, pady=6)\r\n        alignment_bar.grid(row=3, column=0, columnspan=2, sticky=\"ew\", pady=(8, 0))\r\n        self.alignment_controls = []\r\n        manual_row = tk.Frame(alignment_bar)\r\n        manual_row.pack(anchor=\"w\")\r\n        for title, action in ((f\"Home P{PAN_HOME} T{TILT_HOME}\", \"home\"),):\r\n            button = tk.Button(manual_row, text=title, command=lambda a=action: self.start_alignment(a))\r\n            button.pack(side=\"left\", padx=3)\r\n            self.alignment_controls.append(button)\r\n        for title, variable in ((\"Pan:\", self.pan_angle), (\"Tilt:\", self.tilt_angle)):\r\n            tk.Label(manual_row, text=title).pack(side=\"left\")\r\n            entry = tk.Spinbox(manual_row, from_=SERVO_MIN, to=SERVO_MAX,\r\n                               increment=0.5, textvariable=variable, width=7)\r\n            entry.pack(side=\"left\")\r\n            self.alignment_controls.append(entry)\r\n        manual_row = tk.Frame(alignment_bar)\r\n        manual_row.pack(anchor=\"w\", pady=(4, 0))\r\n        for title, callback in (\r\n            (\"Move\", lambda: self.start_alignment(\"move\")),\r\n            (\"Left\", lambda: self.nudge_direction(\"Left\")),\r\n            (\"Right\", lambda: self.nudge_direction(\"Right\")),\r\n            (\"Down\", lambda: self.nudge_direction(\"Down\")),\r\n            (\"Up\", lambda: self.nudge_direction(\"Up\"))\r\n        ):\r\n            button = tk.Button(manual_row, text=title, command=callback)\r\n            button.pack(side=\"left\", padx=3)\r\n            self.alignment_controls.append(button)\r\n        tk.Label(manual_row, text=\"Step (degrees):\").pack(side=\"left\")\r\n        step_menu = tk.OptionMenu(manual_row, self.nudge_step, \"0.05\", \"0.1\", \"0.25\", \"0.5\", \"1\")\r\n        step_menu.pack(side=\"left\")\r\n        self.alignment_controls.append(step_menu)\r\n\r\n        keyboard_hint = tk.Label(alignment_bar, text=\"A: aim | D: Dino | S: stop | H: home | O: horse | P: follow | L: laser | M: manual | T: type | U: pictures | G: GIFs\", takefocus=True, wraplength=530, justify='left')\r\n        self.keyboard_hint = keyboard_hint\r\n        keyboard_hint.pack(anchor=\"w\")\r\n        tk.Checkbutton(alignment_bar, text=\"Manual keyboard movement (M)\", variable=self.manual_mode, command=self.manual_mode_changed).pack(anchor=\"w\")\r\n        keyboard_hint.bind(\"<Button-1>\", lambda event: keyboard_hint.focus_set())\r\n        tk.Label(top_bar, textvariable=self.alignment_status, anchor=\"w\", font=(\"Segoe UI\", 9)).grid(\r\n            row=4, column=0, columnspan=2, sticky=\"ew\", pady=(3, 0))\r\n\r\n        # Chat history\r\n        history_frame = tk.Frame(self.terminal_panel, padx=12)\r\n        history_frame.grid(row=1, column=0, sticky=\"nsew\")\r\n        history_frame.rowconfigure(0, weight=1)\r\n        history_frame.columnconfigure(0, weight=1)\r\n\r\n        self.chat_history = tk.Text(\r\n            history_frame,\r\n            wrap=\"word\",\r\n            state=\"disabled\",\r\n            font=(\"Segoe UI\", 11),\r\n            padx=12,\r\n            pady=10\r\n        )\r\n        self.chat_history.grid(row=0, column=0, sticky=\"nsew\")\r\n\r\n        scrollbar = tk.Scrollbar(\r\n            history_frame,\r\n            command=self.chat_history.yview\r\n        )\r\n        scrollbar.grid(row=0, column=1, sticky=\"ns\")\r\n        self.chat_history.configure(yscrollcommand=scrollbar.set)\r\n\r\n        self.chat_history.tag_configure(\r\n            \"message_header\",\r\n            foreground=\"#555555\",\r\n            font=(\"Segoe UI\", 9, \"bold\")\r\n        )\r\n        self.chat_history.tag_configure(\r\n            \"message_text\",\r\n            foreground=\"#111111\",\r\n            font=(\"Segoe UI\", 11)\r\n        )\r\n\r\n        # Image selection and preview\r\n        image_frame = tk.Frame(\r\n            self.terminal_panel,\r\n            padx=12,\r\n            pady=8,\r\n            relief=\"groove\",\r\n            borderwidth=1\r\n        )\r\n        image_frame.grid(row=2, column=0, sticky=\"ew\", padx=12)\r\n        image_frame.columnconfigure(1, weight=1)\r\n\r\n        self.select_image_button = tk.Button(\r\n            image_frame,\r\n            text=\"Choose Image...\",\r\n            command=self.select_image\r\n        )\r\n        self.select_image_button.grid(\r\n            row=0,\r\n            column=0,\r\n            sticky=\"nw\",\r\n            padx=(0, 12)\r\n        )\r\n\r\n        self.image_info_label = tk.Label(\r\n            image_frame,\r\n            text=\"Choose an image for the OLED.\",\r\n            wraplength=200,\r\n            font=(\"Segoe UI\", 9),\r\n            justify=\"left\",\r\n            anchor=\"w\"\r\n        )\r\n        self.image_info_label.grid(row=0, column=1, sticky=\"nw\")\r\n\r\n        self.preview_label = tk.Label(\r\n            image_frame,\r\n            text=\"Image preview\",\r\n            width=20,\r\n            height=5,\r\n            relief=\"sunken\",\r\n            background=\"#dddddd\"\r\n        )\r\n        self.preview_label.grid(\r\n            row=0,\r\n            column=2,\r\n            sticky=\"e\",\r\n            padx=(12, 0)\r\n        )\r\n\r\n        self.send_image_button = tk.Button(\r\n            image_frame,\r\n            text=\"Send Image\",\r\n            width=12,\r\n            command=self.send_image,\r\n            state=\"disabled\"\r\n        )\r\n        self.send_image_button.grid(\r\n            row=1,\r\n            column=0,\r\n            sticky=\"w\",\r\n            pady=(8, 0)\r\n        )\r\n\r\n        tk.Label(\r\n            image_frame,\r\n            text=\"Preview: white pixels light the OLED.\",\r\n            font=(\"Segoe UI\", 9),\r\n            foreground=\"#666666\"\r\n        ).grid(\r\n            row=1,\r\n            column=1,\r\n            columnspan=2,\r\n            sticky=\"w\",\r\n            pady=(8, 0)\r\n        )\r\n\r\n        options = tk.Frame(image_frame)\r\n        options.grid(row=2, column=0, columnspan=3, sticky=\"w\", pady=(8, 0))\r\n        tk.OptionMenu(\r\n            options, self.image_fit, \"Fit whole image\", \"Center crop\",\r\n            command=lambda _: self.refresh_image()\r\n        ).pack(side=\"left\")\r\n        tk.Checkbutton(\r\n            options, text=\"Dither (photo detail)\", variable=self.image_dither,\r\n            command=self.refresh_image\r\n        ).pack(side=\"left\")\r\n        tk.Checkbutton(\r\n            options, text=\"Invert\", variable=self.image_invert,\r\n            command=self.refresh_image\r\n        ).pack(side=\"left\")\r\n        tk.Label(options, text=\"Threshold\").pack(side=\"left\")\r\n        tk.Scale(\r\n            options, from_=0, to=255, orient=\"horizontal\",\r\n            variable=self.image_threshold, length=90,\r\n            command=lambda _: self.refresh_image()\r\n        ).pack(side=\"left\")\r\n\r\n        animation_bar = tk.Frame(image_frame)\r\n        animation_bar.grid(row=3, column=0, columnspan=3, sticky=\"w\", pady=(8, 0))\r\n\r\n\r\n        self.horse_button = tk.Button(animation_bar, text=\"Play Horse\", command=lambda: self.start_animation(\"horse\"))\r\n        self.horse_button.pack(side=\"left\", padx=(0, 6))\r\n        self.dino_button = tk.Button(animation_bar, text=\"Play Dino\", command=self.start_dino)\r\n        self.dino_button.pack(side=\"left\", padx=4)\r\n        self.gif_button = tk.Button(animation_bar, text=\"Play GIF...\", command=lambda: self.start_animation(\"gif\"))\r\n        self.gif_button.pack(side=\"left\", padx=6)\r\n        tk.Label(animation_bar, text=\"Frames/sec:\").pack(side=\"left\")\r\n        self.fps_menu = tk.OptionMenu(animation_bar, self.animation_fps, 1, 2, 3, 4, 5)\r\n        self.fps_menu.pack(side=\"left\")\r\n\r\n\r\n        # Text entry and send button\r\n        bottom_frame = tk.Frame(self.terminal_panel, padx=12, pady=12)\r\n        bottom_frame.grid(row=3, column=0, sticky=\"ew\")\r\n        bottom_frame.columnconfigure(0, weight=1)\r\n\r\n        self.message_entry = tk.Entry(\r\n            bottom_frame,\r\n            font=(\"Segoe UI\", 12)\r\n        )\r\n        self.message_entry.grid(row=0, column=0, sticky=\"ew\", ipady=8)\r\n        self.message_entry.bind(\"<Return>\", self.send_message)\r\n        self.typing_mode = False\r\n        self.typing_status = tk.StringVar(value='Shortcuts active - T to type')\r\n        self.message_entry.bind('<FocusIn>', lambda event: self.set_typing_state(True))\r\n        self.message_entry.bind('<FocusOut>', lambda event: self.set_typing_state(False))\r\n\r\n        self.send_button = tk.Button(\r\n            bottom_frame,\r\n            text=\"Send Text\",\r\n            width=12,\r\n            command=self.send_message\r\n        )\r\n        self.send_button.grid(row=0, column=1, padx=(8, 0), ipady=5)\r\n\r\n        tk.Label(\r\n            bottom_frame,\r\n            textvariable=self.typing_status,\r\n            font=(\"Segoe UI\", 9),\r\n            foreground=\"#666666\"\r\n        ).grid(row=1, column=0, sticky=\"w\", pady=(5, 0))\r\n\r\n        self.keyboard_hint.focus_set()\r\n\r\n    def set_alignment_controls(self, enabled):\r\n        for widget in getattr(self, \"alignment_controls\", ()):\r\n            widget.config(state=\"normal\" if enabled else \"disabled\")\r\n\r\n    @staticmethod\r\n    def validate_angles(pan, tilt):\r\n        pan, tilt = float(pan), float(tilt)\r\n        if (not math.isfinite(pan) or not math.isfinite(tilt) or\r\n                not SERVO_MIN <= pan <= SERVO_MAX or not SERVO_MIN <= tilt <= SERVO_MAX):\r\n            raise ValueError(\"Use finite pan and tilt angles from 0 to 180 degrees.\")\r\n        return round(pan, 2), round(tilt, 2)\r\n\r\n    def mount_angles(self):\r\n        return self.validate_angles(self.pan_angle.get(), self.tilt_angle.get())\r\n\r\n    def load_position2(self):\r\n        try:\r\n            values = json.loads(POSITION_FILE.read_text(encoding=\"utf-8\"))\r\n            pan, tilt = self.validate_angles(values[\"pan\"], values[\"tilt\"])\r\n            self.position2_pan.set(f\"{pan:g}\")\r\n            self.position2_tilt.set(f\"{tilt:g}\")\r\n        except (OSError, ValueError, TypeError, KeyError):\r\n            pass\r\n\r\n    def save_position2(self):\r\n        if self.busy:\r\n            return\r\n        try:\r\n            pan, tilt = self.validate_angles(self.position2_pan.get(), self.position2_tilt.get())\r\n            POSITION_FILE.write_text(json.dumps({\"pan\": pan, \"tilt\": tilt}, indent=2) + \"\\n\", encoding=\"utf-8\")\r\n            self.position2_pan.set(f\"{pan:g}\")\r\n            self.position2_tilt.set(f\"{tilt:g}\")\r\n            self.alignment_status.set(f\"Position 2 saved: P{pan:g} T{tilt:g}\")\r\n        except (OSError, ValueError, TypeError) as error:\r\n            messagebox.showerror(\"Position 2\", str(error))\r\n\r\n    def capture_position2(self):\r\n        if self.busy:\r\n            return\r\n        try:\r\n            pan, tilt = self.mount_angles()\r\n            self.position2_pan.set(f\"{pan:g}\")\r\n            self.position2_tilt.set(f\"{tilt:g}\")\r\n            self.save_position2()\r\n        except (ValueError, TypeError) as error:\r\n            messagebox.showerror(\"Position 2\", str(error))\r\n\r\n    def go_position2(self):\r\n        if self.busy:\r\n            return\r\n        try:\r\n            pan, tilt = self.validate_angles(self.position2_pan.get(), self.position2_tilt.get())\r\n            self.pan_angle.set(f\"{pan:g}\")\r\n            self.tilt_angle.set(f\"{tilt:g}\")\r\n            self.start_alignment(\"move\")\r\n        except (ValueError, TypeError) as error:\r\n            messagebox.showerror(\"Position 2\", str(error))\r\n\r\n    def open_vision(self):\r\n        try:\r\n            from laser_vision import VisionWindow\r\n            if self.vision_window is not None and not self.vision_window.closed:\r\n                self.vision_window.window.lift()\r\n            else:\r\n                if self.active_tracking_mode == \"Mount camera (LED)\":\r\n                    from laser_mount_vision import MountVisionWindow\r\n                    self.vision_window = MountVisionWindow(self)\r\n                else:\r\n                    self.vision_window = VisionWindow(self)\r\n        except ImportError as error:\r\n            messagebox.showerror(\"Camera targeting\", f\"Install the camera dependency: python -m pip install opencv-python>=4.7\\n\\n{error}\")\r\n\r\n    def switch_tracking_mode(self, mode):\r\n        if self.busy or self.mode_switch_pending:\r\n            self.tracking_mode.set(self.active_tracking_mode)\r\n            self.alignment_status.set(\"Stop / Home or finish the current command before switching cameras.\")\r\n            return\r\n        if mode == self.active_tracking_mode:\r\n            return\r\n        self.stop_manual_hold()\r\n        self.manual_mode.set(False)\r\n        old = self.vision_window\r\n        old.save_setup()\r\n        old.stop_auto()\r\n        old.closed = True\r\n        old.capture_stop.set()\r\n        self.mode_switch_pending = True\r\n        def finish_switch():\r\n            if old.running:\r\n                self.root.after(100, finish_switch)\r\n                return\r\n            for widget in self.camera_panel.winfo_children():\r\n                if widget != self.camera_mode_bar:\r\n                    widget.destroy()\r\n            self.active_tracking_mode = mode\r\n            self.tracking_mode.set(mode)\r\n            self.vision_window = None\r\n            self.open_vision()\r\n            self.mode_switch_pending = False\r\n            self.vision_window.open_camera()\r\n        finish_switch()\r\n\r\n    def nudge_direction(self, direction):\r\n        if self.busy:\r\n            return\r\n        # The mount's physical directions are opposite to increasing angles.\r\n        pan_sign, tilt_sign = {\"Left\": (1, 0), \"Right\": (-1, 0),\r\n                               \"Up\": (0, -1), \"Down\": (0, 1)}[direction]\r\n        step = float(self.nudge_step.get())\r\n        self.nudge_mount(pan_sign * step, tilt_sign * step)\r\n\r\n    @staticmethod\r\n    def shortcut_in_input(event):\r\n        return event.widget.winfo_class() in (\"Entry\", \"TEntry\", \"Text\", \"Spinbox\", \"TSpinbox\", \"Listbox\", \"Scale\", \"TScale\", \"TCombobox\")\r\n\r\n    def manual_mode_changed(self):\r\n        self.stop_manual_hold()\r\n        if self.manual_mode.get() and self.busy:\r\n            self.manual_mode.set(False)\r\n            self.alignment_status.set(\"Use Stop / Home or wait for the command before enabling manual movement.\")\r\n            return\r\n        if self.manual_mode.get():\r\n            vision = getattr(self, \"vision_window\", None)\r\n            if vision is not None:\r\n                vision.stop_auto()\r\n        self.alignment_status.set(\"Manual keyboard movement \" + (\"ON: hold WASD or arrows to move.\" if self.manual_mode.get() else \"OFF.\"))\r\n\r\n    def toggle_manual_mode(self):\r\n        self.manual_mode.set(not self.manual_mode.get())\r\n        self.manual_mode_changed()\r\n\r\n    def toggle_laser(self):\r\n        if self.busy:\r\n            self.alignment_status.set(\"Wait for the command or use Stop / Home before toggling the laser.\")\r\n            return\r\n        vision = getattr(self, \"vision_window\", None)\r\n        if vision is not None:\r\n            vision.stop_auto()\r\n        self.start_alignment(\"tx\" if getattr(self, \"laser_solid\", False) else \"solid\")\r\n\r\n    def key_press_once(self, key):\r\n        if not hasattr(self, \"manual_pressed_keys\"):\r\n            self.manual_pressed_keys = set()\r\n        key = key.lower()\r\n        if key in self.manual_pressed_keys:\r\n            return False\r\n        self.manual_pressed_keys.add(key)\r\n        return True\r\n\r\n    def stop_manual_hold(self):\r\n        job = getattr(self, \"manual_hold_job\", None)\r\n        if job is not None:\r\n            self.root.after_cancel(job)\r\n        self.manual_hold_job = None\r\n        self.manual_active_keys = set()\r\n\r\n    def manual_hold_tick(self):\r\n        self.manual_hold_job = None\r\n        active = getattr(self, \"manual_active_keys\", set())\r\n        if not self.manual_mode.get() or not active:\r\n            self.stop_manual_hold()\r\n            return\r\n        if not self.busy:\r\n            directions = {\"w\": (0,-1), \"up\": (0,-1), \"s\": (0,1), \"down\": (0,1),\r\n                          \"a\": (1,0), \"left\": (1,0), \"d\": (-1,0), \"right\": (-1,0)}\r\n            pan = sum(directions[key][0] for key in active)\r\n            tilt = sum(directions[key][1] for key in active)\r\n            step = float(self.nudge_step.get())\r\n            if pan or tilt:\r\n                self.nudge_mount(max(-1,min(1,pan))*step, max(-1,min(1,tilt))*step)\r\n        self.manual_hold_job = self.root.after(150, self.manual_hold_tick)\r\n\r\n    def on_key_release(self, event):\r\n        key = event.keysym.lower()\r\n        if hasattr(self, \"manual_pressed_keys\"):\r\n            self.manual_pressed_keys.discard(key)\r\n        if hasattr(self, \"manual_active_keys\"):\r\n            self.manual_active_keys.discard(key)\r\n            if not self.manual_active_keys:\r\n                self.stop_manual_hold()\r\n\r\n    def on_shortcut(self, event):\r\n        if self.shortcut_in_input(event):\r\n            return\r\n        if not self.key_press_once(event.keysym):\r\n            return \"break\"\r\n        if event.keysym.lower() == \"l\":\r\n            self.toggle_laser()\r\n        elif event.keysym.lower() == \"m\":\r\n            self.toggle_manual_mode()\r\n        elif event.keysym.lower() == \"h\":\r\n            self.emergency_home()\r\n        elif event.keysym.lower() == \"o\":\r\n            self.start_animation(\"horse\")\r\n        elif event.keysym.lower() == \"p\":\r\n            vision = getattr(self, \"vision_window\", None)\r\n            if vision is not None:\r\n                vision.toggle_person_tracking()\r\n        elif event.keysym.lower() == 't':\r\n            self.toggle_typing()\r\n        elif event.keysym.lower() == 'u':\r\n            if not self.busy:\r\n                self.select_image()\r\n        elif event.keysym.lower() == 'g':\r\n            self.start_animation('gif')\r\n        return \"break\"\r\n\r\n    def set_typing_state(self, enabled):\r\n        self.typing_mode = enabled\r\n        self.typing_status.set('Typing - Enter sends; Esc / Ctrl+T returns to shortcuts' if enabled else 'Shortcuts active - T to type')\r\n\r\n    def toggle_typing(self, event=None):\r\n        enabled = not getattr(self, 'typing_mode', False)\r\n        self.set_typing_state(enabled)\r\n        if enabled:\r\n            self.stop_manual_hold()\r\n            self.message_entry.focus_set()\r\n            self.message_entry.icursor(tk.END)\r\n        else:\r\n            self.keyboard_hint.focus_set()\r\n        return 'break'\r\n\r\n    def leave_typing(self, event=None):\r\n        if getattr(self, 'typing_mode', False):\r\n            self.set_typing_state(False)\r\n            self.keyboard_hint.focus_set()\r\n            return 'break'\r\n\r\n    def on_mount_arrow(self, event):\r\n        if getattr(self, 'job_kind', None) == \"dino\" and event.keysym == \"Up\":\r\n            return self.on_dino_jump(event)\r\n        # Preserve cursor movement and value editing inside input widgets.\r\n        if event.widget.winfo_toplevel() != self.root:\r\n            return\r\n        if self.shortcut_in_input(event):\r\n            return\r\n        first_press = self.key_press_once(event.keysym)\r\n        if not self.manual_mode.get():\r\n            if event.keysym.lower() == \"a\":\r\n                if first_press and getattr(self, \"vision_window\", None) is not None:\r\n                    self.vision_window.start_auto()\r\n                return \"break\"\r\n            if event.keysym.lower() == 'd':\r\n                if first_press:\r\n                    self.start_dino()\r\n                return 'break'\r\n            if event.keysym.lower() == 's':\r\n                if first_press:\r\n                    self.stop_current_activity()\r\n                return 'break'\r\n            return\r\n        if not first_press:\r\n            return \"break\"\r\n        direction = {\"w\": \"Up\", \"a\": \"Left\", \"s\": \"Down\", \"d\": \"Right\"}.get(event.keysym.lower(), event.keysym)\r\n        if not hasattr(self, \"manual_active_keys\"):\r\n            self.manual_active_keys = set()\r\n        self.manual_active_keys.add(event.keysym.lower())\r\n        self.nudge_direction(direction)\r\n        if getattr(self, \"manual_hold_job\", None) is None:\r\n            self.manual_hold_job = self.root.after(150, self.manual_hold_tick)\r\n        return \"break\"\r\n\r\n    def nudge_mount(self, pan_delta, tilt_delta):\r\n        if self.busy:\r\n            return\r\n        try:\r\n            pan, tilt = self.mount_angles()\r\n            self.pan_angle.set(f\"{round(max(SERVO_MIN, min(SERVO_MAX, pan + pan_delta)), 2):g}\")\r\n            self.tilt_angle.set(f\"{round(max(SERVO_MIN, min(SERVO_MAX, tilt + tilt_delta)), 2):g}\")\r\n        except ValueError as error:\r\n            messagebox.showerror(\"Servo angles\", str(error))\r\n            return\r\n        self.start_alignment(\"move\")\r\n\r\n    def stop_current_activity(self):\r\n        self.stop_manual_hold()\r\n        vision = getattr(self, 'vision_window', None)\r\n        if vision is not None:\r\n            vision.stop_auto()\r\n        if self.busy:\r\n            self.stop_speed_job()\r\n        else:\r\n            self.alignment_status.set('Stopped. Holding mount position.')\r\n        self.close_dino_window()\r\n\r\n    def close_dino_window(self):\r\n        popup = getattr(self, 'dino_window', None)\r\n        if popup is not None:\r\n            if popup.winfo_exists():\r\n                popup.destroy()\r\n            self.dino_window = None\r\n            self.keyboard_hint.focus_set()\r\n\r\n    def emergency_home(self):\r\n        self.stop_manual_hold()\r\n        vision = getattr(self, \"vision_window\", None)\r\n        if vision is not None:\r\n            vision.stop_auto()\r\n        if self.busy:\r\n            self.speed_stop.set()\r\n            if self.job_kind != \"alignment\":\r\n                self.home_after_job = True\r\n            self.alignment_status.set(\"Cancelling current command and returning Home...\")\r\n        else:\r\n            self.start_alignment(\"home\")\r\n\r\n    def start_alignment(self, action):\r\n        if self.busy:\r\n            if action == \"home\":\r\n                self.emergency_home()\r\n            return\r\n        if self.connection is None or not self.connection.is_open:\r\n            messagebox.showerror(\"Not connected\", \"Connect the transmitter first.\")\r\n            return\r\n        try:\r\n            if action == \"move\":\r\n                pan, tilt = self.mount_angles()\r\n                command = f\"P{pan:.2f} T{tilt:.2f}\"\r\n            elif action == \"align\":\r\n                pan, tilt = self.validate_angles(self.position2_pan.get(), self.position2_tilt.get())\r\n                command = f\"ALIGNPOS P{pan:.2f} T{tilt:.2f} S{float(self.search_step.get()):.2f}\"\r\n            elif action == \"cvlock\":\r\n                if getattr(self, \"cv_verify_only\", False):\r\n                    command = \"VERIFY\"\r\n                else:\r\n                    pan, tilt = getattr(self, \"cv_hit_anchor\", None) or self.mount_angles()\r\n                    radius = getattr(self, \"cv_hit_radius\", None) or 1.0\r\n                    command = f\"ALIGNNEAR P{pan:.2f} T{tilt:.2f} S0.50 R{radius:.2f}\"\r\n            elif action == \"cvprepare\":\r\n                command = \"CVPREP\"\r\n            elif action == \"solid\":\r\n                command = \"LASER SOLID\"\r\n            elif action == \"tx\":\r\n                command = \"LASER TX\"\r\n            elif action == \"display\":\r\n                command = \"DISPLAY\"\r\n            elif action == \"blank\":\r\n                command = \"BLANK\"\r\n            elif action == \"target\":\r\n                command = \"TARGET\"\r\n            else:\r\n                command = action.upper()\r\n        except ValueError as error:\r\n            messagebox.showerror(\"Servo angles\", str(error))\r\n            return\r\n        self.busy = True\r\n        self.job_kind = \"alignment\"\r\n        self.speed_stop = threading.Event()\r\n        self.set_alignment_controls(False)\r\n        for widget in (self.connect_button, self.send_button, self.send_image_button,\r\n                       self.apply_speed_button, self.horse_button, self.gif_button, self.select_image_button, self.fps_menu):\r\n            widget.config(state=\"disabled\")\r\n        self.stop_speed_button.config(state=\"normal\", text=\"Cancel command / Home\")\r\n        self.alignment_status.set(\"Searching for receiver...\" if action in (\"align\", \"cvlock\") else f\"Commanding {command}...\")\r\n        threading.Thread(target=self.alignment_worker, args=(action, command), daemon=True).start()\r\n\r\n    def alignment_worker(self, action, command):\r\n        result = \"\"\r\n        self.alignment_trace = []\r\n        try:\r\n            # Corrupted position digits were observed at the high runtime rate.\r\n            # Keep CV moves and optical checks at the known working boot rate.\r\n            if action in (\"cvprepare\", \"cvlock\", \"align\"):\r\n                self.worker_events.put((\"manual_off\", None))\r\n            if action == \"cvprepare\" and self.connection.baudrate in SPEED_RATES[3:]:\r\n                self.alignment_restore_baud = self.connection.baudrate\r\n                self.worker_events.put((\"alignment\", \"Switching alignment link to 38,400 baud for reliable position replies...\"))\r\n                self.alignment_trace.append({\"direction\": \"baud\", \"text\": f\"Negotiating alignment speed from {self.connection.baudrate} to {BOOT_BAUD_RATE}\"})\r\n                self.ensure_alignment_speed()\r\n            self.alignment_trace.append({\"direction\": \"send\", \"text\": command})\r\n            self.connection.reset_input_buffer()\r\n            self.connection.write((command + \"\\n\").encode(\"ascii\"))\r\n            self.connection.flush()\r\n            short_command = action in (\"target\", \"blank\", \"display\", \"cvprepare\", \"solid\", \"tx\", \"home\")\r\n            deadline = time.monotonic() + (8 if short_command else 43200 if action == \"align\" else 30)\r\n            command_retries = 0\r\n            next_command_retry = time.monotonic()+2 if short_command else 0\r\n            home_queued = False\r\n            move_retries = 0\r\n            next_move_retry = time.monotonic()+3\r\n            response_buffer = bytearray()\r\n            while time.monotonic() < deadline:\r\n                if self.speed_stop.is_set() and not home_queued:\r\n                    self.connection.write(b\"HOME\\n\")\r\n                    self.connection.flush()\r\n                    home_queued = True\r\n                    deadline = time.monotonic()+5\r\n                    self.worker_events.put((\"alignment\", \"Cancelling search and returning home...\"))\r\n                if short_command and not home_queued and command_retries < 2 and time.monotonic() >= next_command_retry:\r\n                    self.connection.write((command+\"\\n\").encode(\"ascii\"))\r\n                    self.connection.flush()\r\n                    command_retries += 1\r\n                    next_command_retry = time.monotonic()+2\r\n                    self.alignment_trace.append({\"direction\": \"retry\", \"text\": command})\r\n                if action == \"move\" and not home_queued and move_retries < 3 and time.monotonic() >= next_move_retry:\r\n                    # Retry even when unsolicited hit/status lines keep arriving.\r\n                    self.connection.write((command + \"\\n\").encode(\"ascii\"))\r\n                    self.connection.flush()\r\n                    move_retries += 1\r\n                    next_move_retry = time.monotonic()+3\r\n                    self.alignment_trace.append({\"direction\": \"retry\", \"text\": command})\r\n                    self.worker_events.put((\"alignment\", f\"No movement reply; retrying same position ({move_retries}/3)...\"))\r\n                # A timeout may split a status line; retain its first bytes.\r\n                response_buffer.extend(self.connection.readline())\r\n                if b\"\\n\" not in response_buffer:\r\n                    if len(response_buffer) > 8192:\r\n                        response_buffer.clear()\r\n                    continue\r\n                raw, _, remaining = response_buffer.partition(b\"\\n\")\r\n                response_buffer = bytearray(remaining)\r\n                self.alignment_trace.append({\"direction\": \"receive\", \"text\": raw.decode(\"ascii\", errors=\"replace\")[:256]})\r\n                self.alignment_trace = self.alignment_trace[-80:]\r\n                line = alignment_status_line(raw)\r\n                if not line:\r\n                    continue\r\n                if line.startswith(\"HOME P\") and line != f\"HOME P{PAN_HOME} T{TILT_HOME}\":\r\n                    # A dropped digit must not redefine the known Home pose.\r\n                    continue\r\n                if action == \"move\" and not home_queued and line.startswith(\"MOVED P\"):\r\n                    requested = re.fullmatch(r\"P([0-9.]+) T([0-9.]+)\", command)\r\n                    reported = re.fullmatch(r\"MOVED P([0-9.]+) T([0-9.]+)\", line)\r\n                    if requested and reported and any(abs(float(requested[i])-float(reported[i])) > 0.01 for i in (1, 2)):\r\n                        # Late replies from a retry cannot confirm a new move\r\n                        # or overwrite the mount coordinates used by its square.\r\n                        continue\r\n                # Optical probe bytes share this UART; display only readable status lines.\r\n                if line.startswith((\"CV HIT\", \"HIT NEAR\", \"LOCK\", \"LOCAL\", \"SEARCH\", \"ALIGN ERROR\", \"NO RECEIVER\", \"HOME \", \"MOVED \")):\r\n                    self.worker_events.put((\"alignment\", line))\r\n                if action == \"move\" and not home_queued and line.startswith(\"CV HIT P\"):\r\n                    # A sensor report includes the transmitter's current pose.\r\n                    # It can confirm the absolute command when MOVED was lost,\r\n                    # but never confirms optical communication/LOCK itself.\r\n                    requested = re.fullmatch(r\"P([0-9.]+) T([0-9.]+)\", command)\r\n                    reported = re.fullmatch(r\"CV HIT P([0-9.]+) T([0-9.]+)\", line)\r\n                    if requested and reported and all(abs(float(requested[i])-float(reported[i])) <= 0.01 for i in (1, 2)):\r\n                        self.worker_events.put((\"history\", f\"[Solid-light candidate: {line}]\"))\r\n                        result = \"MOVED \" + line[len(\"CV HIT \"):]\r\n                        break\r\n                if home_queued:\r\n                    complete = line.startswith(\"HOME P\")\r\n                elif action in (\"align\", \"cvlock\"):\r\n                    complete = line.startswith((\"LOCK P\", \"VERIFY FAILED\", \"NO RECEIVER FOUND\", \"ALIGN ERROR\"))\r\n                elif action in (\"target\", \"blank\", \"display\", \"cvprepare\"):\r\n                    complete = line.startswith((\"TARGET REQUEST SENT\", \"ALIGN ERROR\"))\r\n                elif action in (\"solid\", \"tx\"):\r\n                    complete = line.startswith((\"LASER SOLID OK\", \"LASER TX OK\", \"ALIGN ERROR\"))\r\n                elif action == \"home\":\r\n                    complete = line.startswith(\"HOME P\")\r\n                else:\r\n                    complete = line.startswith(\"MOVED P\")\r\n                if complete:\r\n                    result = line\r\n                    break\r\n            if not result:\r\n                raise RuntimeError(\"No final servo response. Reset the transmitter and reconnect if it is still searching.\")\r\n            # Keep the proven alignment rate for OLED animation and messages.\r\n            # An automatic high-rate switch here caused lost replies after lock.\r\n            if action == \"display\" and result.startswith(\"TARGET REQUEST SENT\"):\r\n                self.alignment_restore_baud = None\r\n                requested_baud = getattr(self, \"requested_transmission_baud\", self.connection.baudrate)\r\n                if requested_baud != self.connection.baudrate:\r\n                    self.set_link_speed(requested_baud)\r\n                    self.alignment_trace.append({\"direction\": \"baud\", \"text\": f\"Restored selected transmission baud {requested_baud}\"})\r\n            if not result.startswith(\"ALIGN ERROR\") and action in (\"solid\", \"tx\", \"cvprepare\", \"cvlock\", \"align\", \"display\", \"home\"):\r\n                self.worker_events.put((\"laser\", action in (\"solid\", \"cvprepare\")))\r\n            self.worker_events.put((\"history\", f\"[Servo mount: {result}]\"))\r\n        except (serial.SerialException, RuntimeError, OSError) as error:\r\n            result = f\"Alignment command failed: {error}\"\r\n            self.worker_events.put((\"alignment\", result))\r\n        finally:\r\n            try:\r\n                trace = {\"time\": datetime.now().isoformat(), \"action\": action, \"command\": command,\r\n                         \"baud\": self.connection.baudrate, \"result\": result,\r\n                         \"events\": self.alignment_trace}\r\n                Path(__file__).resolve().with_name(\"alignment_trace.json\").write_text(json.dumps(trace, indent=2), encoding=\"utf-8\")\r\n            except (OSError, TypeError):\r\n                pass\r\n            self.worker_events.put((\"done\", result))\r\n\r\n    def update_alignment_status(self, line):\r\n        if line.startswith(\"HOME P\") and line != f\"HOME P{PAN_HOME} T{TILT_HOME}\":\r\n            return\r\n        self.alignment_status.set(line)\r\n        candidate = re.match(r\"^CV HIT P([0-9.]+) T([0-9.]+)$\", line)\r\n        vision = getattr(self, \"vision_window\", None)\r\n        if candidate and vision is not None and not vision.closed and (vision.auto or getattr(vision, \"cv_start_pending\", False)):\r\n            vision.cv_sensor_hit = True\r\n            self.cv_hit_anchor = (float(candidate[1]), float(candidate[2]))\r\n            self.cv_hit_radius = 0.5\r\n        match = re.match(r\"^(?:HIT NEAR|LOCK|MOVED|HOME) P([0-9.]+) T([0-9.]+)$\", line)\r\n        if match:\r\n            if line.startswith(\"HIT NEAR P\"):\r\n                self.cv_hit_radius = 0.5\r\n                if getattr(self, \"cv_hit_anchor\", None) is None:\r\n                    self.cv_hit_anchor = (float(match[1]), float(match[2]))\r\n                if getattr(self, \"vision_window\", None) is not None:\r\n                    self.vision_window.hit_anchor = True\r\n            self.pan_angle.set(f\"{float(match[1]):g}\")\r\n            self.tilt_angle.set(f\"{float(match[2]):g}\")\r\n\r\n    def poll_alignment_status(self):\r\n        if self.busy or self.connection is None or not self.connection.is_open:\r\n            return\r\n        try:\r\n            available = self.connection.in_waiting\r\n            if not available:\r\n                return\r\n            self.idle_serial_buffer.extend(self.connection.read(min(available, 8192)))\r\n            while b\"\\n\" in self.idle_serial_buffer:\r\n                raw, _, remainder = self.idle_serial_buffer.partition(b\"\\n\")\r\n                self.idle_serial_buffer = bytearray(remainder)\r\n                line = alignment_status_line(raw)\r\n                if line.startswith((\"CV HIT\", \"LOCK\", \"MISSED PROBE\", \"LOCAL SEARCH\", \"HOME P\", \"MOVED P\", \"NO RECEIVER\")):\r\n                    self.update_alignment_status(line)\r\n            if len(self.idle_serial_buffer) > 8192:\r\n                self.idle_serial_buffer.clear()\r\n        except (serial.SerialException, OSError) as error:\r\n            self.alignment_status.set(f\"Serial status unavailable: {error}\")\r\n\r\n    def show_connection_error(self, title, details):\r\n        # Keep diagnostics accessible even when the Windows popup cannot be copied.\r\n        try:\r\n            log_path = Path(__file__).resolve().with_name(\"connection_error.txt\")\r\n            log_path.write_text(\r\n                f\"{datetime.now().isoformat()}\\n{title}\\n\\n{details}\\n\",\r\n                encoding=\"utf-8\"\r\n            )\r\n        except OSError:\r\n            pass\r\n\r\n        popup = tk.Toplevel(self.root)\r\n        popup.title(title)\r\n        popup.transient(self.root)\r\n        popup.geometry(\"640x350\")\r\n        popup.rowconfigure(0, weight=1)\r\n        popup.columnconfigure(0, weight=1)\r\n        text = tk.Text(popup, wrap=\"word\", padx=12, pady=12, font=(\"Segoe UI\", 10))\r\n        text.grid(row=0, column=0, sticky=\"nsew\")\r\n        text.insert(\"1.0\", details)\r\n        text.config(state=\"disabled\")\r\n        scrollbar = tk.Scrollbar(popup, command=text.yview)\r\n        scrollbar.grid(row=0, column=1, sticky=\"ns\")\r\n        text.config(yscrollcommand=scrollbar.set)\r\n        buttons = tk.Frame(popup, padx=12, pady=10)\r\n        buttons.grid(row=1, column=0, columnspan=2, sticky=\"ew\")\r\n\r\n        def copy_details():\r\n            self.root.clipboard_clear()\r\n            self.root.clipboard_append(details)\r\n            copy_button.config(text=\"Copied\")\r\n\r\n        copy_button = tk.Button(buttons, text=\"Copy Details\", command=copy_details)\r\n        copy_button.pack(side=\"left\")\r\n        tk.Button(buttons, text=\"Close\", command=popup.destroy).pack(side=\"right\")\r\n        popup.bind(\"<Escape>\", lambda _: popup.destroy())\r\n        text.focus_set()\r\n        popup.grab_set()\r\n        self.root.wait_window(popup)\r\n\r\n    def connect(self, automatic=False):\r\n        def show_error(title, details):\r\n            if automatic:\r\n                self.alignment_status.set(\"Offline: app is ready. Connect the transmitter and click Reconnect when needed.\")\r\n            else:\r\n                self.show_connection_error(title, details)\r\n\r\n        if self.busy:\r\n            return\r\n        if self.connection is not None and self.connection.is_open:\r\n            self.connection.close()\r\n        self.connection = None\r\n\r\n        try:\r\n            self.connection = serial.Serial(\r\n                port=PORT,\r\n                baudrate=BOOT_BAUD_RATE,\r\n                timeout=0.2,\r\n                write_timeout=10\r\n            )\r\n        except (serial.SerialException, OSError) as error:\r\n            self.status_label.config(text=f\"Could not open {PORT}\")\r\n            show_error(\r\n                \"Serial port unavailable\",\r\n                f\"Could not open {PORT}.\\n\\n\"\r\n                \"Close Arduino Serial Monitor, Serial Plotter, and any other \"\r\n                \"terminal app using this port, then click Reconnect.\\n\\n\"\r\n                f\"Details: {error}\"\r\n            )\r\n            return\r\n\r\n        try:\r\n            # Opening the serial port can reset some ESP32 boards.\r\n            time.sleep(2)\r\n            self.set_link_speed(BAUD_RATE)\r\n            self.speed_choice.set(str(BAUD_RATE))\r\n            self.idle_serial_buffer.clear()\r\n            self.alignment_status.set(\"Connected. Click Home to confirm the mount position, then open the camera and load calibration.\")\r\n            self.status_label.config(text=f\"Connected to {PORT} at {BAUD_RATE} baud\")\r\n        except (serial.SerialException, RuntimeError, OSError) as error:\r\n            if isinstance(error, RuntimeError) and str(error).startswith(\"BAUD ERROR receiver did not acknowledge\"):\r\n                # This reply proves the USB/transmitter path works. Firmware\r\n                # keeps its UART speed unchanged after a failed radio handshake.\r\n                self.speed_choice.set(str(self.connection.baudrate))\r\n                self.idle_serial_buffer.clear()\r\n                self.status_label.config(text=f\"Transmitter connected on {PORT}; receiver radio not confirmed\")\r\n                self.alignment_status.set(\"Receiver did not acknowledge. Power/reset the receiver, then Reconnect. Mount and laser controls remain available; optical link is unconfirmed.\")\r\n                return\r\n            self.connection.close()\r\n            self.connection = None\r\n            self.status_label.config(text=f\"{PORT} opened, but speed synchronization failed\")\r\n            show_error(\r\n                \"ESP32 speed synchronization failed\",\r\n                f\"Windows opened {PORT}, but the boards did not complete the \"\r\n                \"runtime-speed handshake.\\n\\n\"\r\n                \"Upload the latest servo_find_Send sketch to the transmitter \"\r\n                \"and servo_find_receive sketch to the receiver. Power on both \"\r\n                \"boards, reset both, close Serial Monitor, then click Reconnect.\\n\\n\"\r\n                f\"Details: {error}\"\r\n            )\r\n\r\n    def is_transmitter_command(self, text):\r\n        \"\"\"Avoid accidentally sending commands as normal text.\"\"\"\r\n        command = text.strip().lower()\r\n\r\n        if command in {\"home\", \"send\", \"script\", \"endscript\", \"image\", \"speedtest\", \"blank\", \"target\", \"display\", \"verify\", \"cvprep\", \"laser solid\", \"laser tx\"}:\r\n            return True\r\n        if command.startswith(\"baud \") or command.startswith(\"bench \"):\r\n            return True\r\n\r\n        if command == \"align\" or command.startswith((\"align \", \"alignpos \")):\r\n            return True\r\n\r\n        # Matches commands such as: P92 T68\r\n        if re.fullmatch(r\"[pt]\\d+(?:\\.\\d+)?\\s+[pt]\\d+(?:\\.\\d+)?\", command):\r\n            return True\r\n\r\n        return False\r\n\r\n    def add_message_to_history(self, timestamp, text):\r\n        self.chat_history.configure(state=\"normal\")\r\n\r\n        self.chat_history.insert(\r\n            \"end\",\r\n            f\"You  Ã‚Â·  {timestamp}\\n\",\r\n            \"message_header\"\r\n        )\r\n        self.chat_history.insert(\r\n            \"end\",\r\n            text + \"\\n\\n\",\r\n            \"message_text\"\r\n        )\r\n\r\n        self.chat_history.configure(state=\"disabled\")\r\n        self.chat_history.see(\"end\")\r\n\r\n    def load_history(self):\r\n        if not HISTORY_FILE.exists():\r\n            return\r\n\r\n        try:\r\n            with HISTORY_FILE.open(\"r\", encoding=\"utf-8\") as history:\r\n                for line in history:\r\n                    try:\r\n                        record = json.loads(line)\r\n                        self.add_message_to_history(\r\n                            record[\"timestamp\"],\r\n                            record[\"text\"]\r\n                        )\r\n                    except (json.JSONDecodeError, KeyError):\r\n                        # Ignore a damaged or incomplete history entry.\r\n                        continue\r\n\r\n        except OSError as error:\r\n            self.status_label.config(\r\n                text=f\"Could not load saved history: {error}\"\r\n            )\r\n\r\n    def save_message(self, timestamp, text):\r\n        HISTORY_FOLDER.mkdir(parents=True, exist_ok=True)\r\n\r\n        record = {\r\n            \"timestamp\": timestamp,\r\n            \"text\": text\r\n        }\r\n\r\n        with HISTORY_FILE.open(\"a\", encoding=\"utf-8\") as history:\r\n            history.write(json.dumps(record, ensure_ascii=False) + \"\\n\")\r\n\r\n    def save_history_entry(self, text):\r\n        timestamp = datetime.now().strftime(\"%Y-%m-%d %H:%M:%S\")\r\n        self.add_message_to_history(timestamp, text)\r\n\r\n        try:\r\n            self.save_message(timestamp, text)\r\n        except OSError as error:\r\n            self.status_label.config(\r\n                text=f\"Sent, but could not save history: {error}\"\r\n            )\r\n            return\r\n\r\n        self.status_label.config(\r\n            text=f\"Sent. History saved to {HISTORY_FILE}\"\r\n        )\r\n\r\n    def select_image(self):\r\n        if self.busy:\r\n            return\r\n        file_path = filedialog.askopenfilename(\r\n            title=\"Choose an image\",\r\n            initialdir=str(Path(__file__).resolve().parent / 'Good Images to Send'),\r\n            filetypes=[\r\n                (\"Image files\", \"*.png *.jpg *.jpeg *.bmp *.gif *.tif *.tiff\"),\r\n                (\"All files\", \"*.*\")\r\n            ]\r\n        )\r\n\r\n        if not file_path:\r\n            return\r\n\r\n        self.selected_image_path = Path(file_path)\r\n        self.refresh_image()\r\n\r\n    def refresh_image(self):\r\n        if self.busy or self.selected_image_path is None:\r\n            return\r\n        try:\r\n            payload, preview = self.convert_image_to_bitmap(self.selected_image_path)\r\n            if len(payload) != IMAGE_SIZE:\r\n                raise ValueError(f\"Expected {IMAGE_SIZE} image bytes, got {len(payload)}\")\r\n            self.image_payload = payload\r\n            self.preview_photo = ImageTk.PhotoImage(preview)\r\n            self.preview_label.configure(image=self.preview_photo, text=\"\", width=0, height=0)\r\n            processing = \"Dithered\" if self.image_dither.get() else f\"Threshold {self.image_threshold.get()}\"\r\n            self.image_info_label.configure(text=(\r\n                f\"{self.selected_image_path.name}\\n\"\r\n                f\"128x64 monochrome; {IMAGE_SIZE} bytes\\n\"\r\n                f\"{self.image_fit.get()}; {processing}\"\r\n            ))\r\n            self.send_image_button.configure(state=\"disabled\" if self.busy else \"normal\")\r\n        except Exception as error:\r\n            self.image_payload = None\r\n            self.send_image_button.configure(state=\"disabled\")\r\n            self.preview_label.configure(image=\"\", text=\"Image unavailable\")\r\n            messagebox.showerror(\"Image error\", f\"Could not convert this image.\\n\\nDetails: {error}\")\r\n\r\n    def convert_image_to_bitmap(self, file_path):\r\n        \"\"\"\r\n        Make the receiver's expected format:\r\n        128x64 pixels, row-major, 8 horizontal pixels per byte,\r\n        leftmost pixel in bit 7. A white pixel is 1.\r\n        \"\"\"\r\n        with Image.open(file_path) as source:\r\n            return convert_frame(\r\n                source, fit=self.image_fit.get(), dither=self.image_dither.get(),\r\n                invert=self.image_invert.get(), threshold=self.image_threshold.get()\r\n            )\r\n\r\n    def on_dino_jump(self, event=None):\r\n        if getattr(self, 'job_kind', None) != 'dino':\r\n            return\r\n        if event is not None and self.shortcut_in_input(event):\r\n            return\r\n        self.dino_input.put('jump')\r\n        return 'break'\r\n\r\n    def start_dino(self):\r\n        if self.busy or self.connection is None or not self.connection.is_open:\r\n            return\r\n        old_popup = getattr(self, 'dino_window', None)\r\n        if old_popup is not None and old_popup.winfo_exists():\r\n            old_popup.destroy()\r\n        vision = getattr(self, 'vision_window', None)\r\n        if vision is not None:\r\n            vision.stop_auto()\r\n        self.stop_manual_hold()\r\n        self.manual_mode.set(False)\r\n        self.busy = True\r\n        self.job_kind = 'dino'\r\n        self.speed_stop = threading.Event()\r\n        self.dino_input = queue.Queue()\r\n        self.set_alignment_controls(False)\r\n        for widget in (self.connect_button, self.send_button, self.send_image_button,\r\n                       self.apply_speed_button, self.horse_button, self.gif_button, self.select_image_button, self.fps_menu):\r\n            widget.config(state='disabled')\r\n        self.stop_speed_button.config(state='normal')\r\n        popup = tk.Toplevel(self.root)\r\n        self.dino_window = popup\r\n        popup.title('Laser Dino â€” Space / Up to jump')\r\n        self.dino_canvas = tk.Label(popup, background='black', width=64, height=20)\r\n        self.dino_canvas.pack(fill='both', expand=True)\r\n        self.dino_status_label = tk.Label(popup, text='Connecting game... Space / Up: jump or restart. Escape: stop.', wraplength=500)\r\n        self.dino_status_label.pack()\r\n        buttons = tk.Frame(popup)\r\n        buttons.pack(pady=8)\r\n        tk.Button(buttons, text='Jump / restart', command=self.on_dino_jump).pack(side='left', padx=4)\r\n        tk.Button(buttons, text='Pause / resume', command=lambda: self.dino_input.put('pause')).pack(side='left', padx=4)\r\n        tk.Button(buttons, text='Stop', command=self.stop_current_activity).pack(side='left', padx=4)\r\n        popup.bind('<space>', self.on_dino_jump)\r\n        popup.bind('<Up>', self.on_dino_jump)\r\n        popup.bind('<Escape>', lambda event: self.stop_current_activity())\r\n        for key in ('h', 'H'):\r\n            popup.bind(f'<KeyPress-{key}>', lambda event: self.emergency_home())\r\n        for key in ('s', 'S'):\r\n            popup.bind(f'<KeyPress-{key}>', lambda event: self.stop_current_activity())\r\n        for key in ('d', 'D'):\r\n            popup.bind(f'<KeyPress-{key}>', lambda event: self.start_dino())\r\n        def close_game():\r\n            if self.dino_window is popup and self.job_kind == 'dino':\r\n                self.speed_stop.set()\r\n            popup.destroy()\r\n            if self.dino_window is popup:\r\n                self.dino_window = None\r\n        popup.protocol('WM_DELETE_WINDOW', close_game)\r\n        popup.focus_set()\r\n        threading.Thread(target=self.dino_worker, daemon=True).start()\r\n\r\n    def dino_control(self, command, expected):\r\n        for attempt in range(3):\r\n            self.connection.reset_input_buffer()\r\n            self.connection.write(command+b'\\n')\r\n            self.connection.flush()\r\n            try:\r\n                response = self.read_response((expected, 'DINO ERROR'), timeout=2)\r\n            except RuntimeError:\r\n                if attempt == 2:\r\n                    raise\r\n                continue\r\n            if response.startswith('DINO ERROR'):\r\n                raise RuntimeError(response)\r\n            return\r\n\r\n    def dino_worker(self):\r\n        game = DinoGame()\r\n        ready = False\r\n        sequence = 0\r\n        original_baud = self.connection.baudrate\r\n        message = 'Dino stopped.'\r\n        try:\r\n            self.worker_events.put(('dino_preview', game.preview()))\r\n            # Small scenes fit comfortably at the reliable control baud.\r\n            self.ensure_alignment_speed()\r\n            self.set_benchmark_mode(True)\r\n            self.dino_control(b'DINO START', 'DINO READY')\r\n            ready = True\r\n            previous = time.monotonic()\r\n            while not self.speed_stop.is_set():\r\n                started = time.monotonic()\r\n                while not self.dino_input.empty():\r\n                    try:\r\n                        action = self.dino_input.get_nowait()\r\n                    except queue.Empty:\r\n                        break\r\n                    if action == 'jump':\r\n                        game.jump()\r\n                    elif action == 'pause':\r\n                        game.paused = not game.paused\r\n                game.step(started-previous)\r\n                previous = started\r\n                sequence = (sequence+1) & 65535\r\n                self.connection.reset_input_buffer()\r\n                self.connection.write(b'DINO\\n'+game.packet(sequence))\r\n                self.connection.flush()\r\n                self.worker_events.put(('dino_preview', game.preview()))\r\n                self.worker_events.put(('status', f'Dino score {game.score} / best {game.best} â€” '+('GAME OVER: Space to restart' if game.over else 'Space / Up to jump')))\r\n                self.speed_stop.wait(max(0, .05-(time.monotonic()-started)))\r\n        except (serial.SerialException, RuntimeError, OSError) as error:\r\n            message = f'Dino stopped: {error}'\r\n            if not ready:\r\n                message += ' Upload the updated Dino sketches to both boards.'\r\n        finally:\r\n            cleanup = []\r\n            if ready:\r\n                cleanup.append(lambda: self.dino_control(b'DINO STOP', 'DINO STOPPED'))\r\n            cleanup.append(lambda: self.set_benchmark_mode(False))\r\n            if original_baud != self.connection.baudrate:\r\n                cleanup.append(lambda: self.set_link_speed(original_baud))\r\n            for action in cleanup:\r\n                try:\r\n                    action()\r\n                except (serial.SerialException, RuntimeError, OSError) as error:\r\n                    message += f' Serial cleanup failed: {error}'\r\n            try:\r\n                Path(__file__).resolve().with_name('dino_trace.json').write_text(json.dumps(\r\n                    {'time': datetime.now().isoformat(), 'started': ready, 'original_baud': original_baud,\r\n                     'final_baud': self.connection.baudrate, 'score': game.score, 'result': message}, indent=2), encoding='utf-8')\r\n            except (OSError, TypeError):\r\n                pass\r\n            self.worker_events.put(('history', f'[Dino ended: score {game.score}, best {game.best}]'))\r\n            self.worker_events.put(('done', message))\r\n\r\n    def start_animation(self, kind, duration=None):\r\n        if self.busy:\r\n            return\r\n        if self.connection is None or not self.connection.is_open:\r\n            messagebox.showerror(\"Not connected\", \"Connect the transmitter first.\")\r\n            return\r\n        try:\r\n            if kind == \"walk\":\r\n                frames = walking_frames()\r\n                name = \"Walking stick figure\"\r\n            elif kind == \"horse\":\r\n                frames = horse_frames()\r\n                name = \"Galloping horse silhouette\"\r\n            else:\r\n                path = filedialog.askopenfilename(\r\n                    title=\"Choose an animated GIF or WebP\",\r\n                    initialdir=str(Path(__file__).resolve().parent / 'GIFs'),\r\n                    filetypes=[(\"Animations\", \"*.gif *.webp\"), (\"All files\", \"*.*\")]\r\n                )\r\n                if not path:\r\n                    return\r\n                frames = load_animation(\r\n                    path, fit=self.image_fit.get(), dither=self.image_dither.get(),\r\n                    invert=self.image_invert.get(), threshold=self.image_threshold.get()\r\n                )\r\n                name = Path(path).name\r\n        except (OSError, ValueError) as error:\r\n            messagebox.showerror(\"Animation error\", str(error))\r\n            return\r\n        self.busy = True\r\n        self.laser_solid = False\r\n        self.set_alignment_controls(False)\r\n        self.speed_stop = threading.Event()\r\n        for widget in (self.connect_button, self.send_button, self.send_image_button,\r\n                       self.apply_speed_button, self.horse_button, self.gif_button, self.select_image_button, self.fps_menu):\r\n            widget.config(state=\"disabled\")\r\n        self.stop_speed_button.config(state=\"normal\")\r\n        fps = self.animation_fps.get()\r\n        self.save_history_entry(f\"[Animation started: {name}, {len(frames)} frames, requested {fps} fps]\")\r\n        threading.Thread(target=self.animation_worker, args=(frames, name, fps, duration), daemon=True).start()\r\n\r\n    def verify_payload_link(self, probes=3):\r\n        for probe in range(probes):\r\n            if self.speed_stop.is_set():\r\n                raise RuntimeError(\"Playback cancelled.\")\r\n            self.test_sequence = (getattr(self, \"test_sequence\", 0)+1) & 0xffffffff\r\n            sequence = self.test_sequence\r\n            self.connection.reset_input_buffer()\r\n            self.connection.write(b\"SPEEDTEST\\n\"+speed_test_payload(sequence))\r\n            self.connection.flush()\r\n            try:\r\n                response = self.read_response((\"TEST RESULT \", \"TEST TIMEOUT\"), timeout=4)\r\n            except RuntimeError as error:\r\n                self.record_link_quality(sequence, str(error))\r\n                raise RuntimeError(f\"LINK QUALITY FAILED: no verified image-length reception at {self.connection.baudrate:,} baud\") from error\r\n            self.record_link_quality(sequence, response)\r\n            if response != f\"TEST RESULT {sequence} 0\":\r\n                raise RuntimeError(f\"LINK QUALITY FAILED at {self.connection.baudrate:,} baud: {response}\")\r\n            self.worker_events.put((\"status\", f\"Checking optical image reception: {probe+1}/{probes} clean payloads.\"))\r\n            if probe+1 < probes and self.speed_stop.wait(.15):\r\n                raise RuntimeError(\"Playback cancelled.\")\r\n\r\n    def record_link_quality(self, sequence, response):\r\n        entry = {\"time\": datetime.now().isoformat(), \"baud\": self.connection.baudrate,\r\n                 \"sequence\": sequence, \"response\": response}\r\n        try:\r\n            with Path(__file__).resolve().with_name(\"link_quality_trace.jsonl\").open(\"a\", encoding=\"utf-8\") as stream:\r\n                stream.write(json.dumps(entry)+\"\\n\")\r\n        except OSError:\r\n            pass\r\n        self.worker_events.put((\"history\", f\"[Link quality {entry['baud']:,} baud: {response}]\"))\r\n\r\n    def animation_worker(self, frames, name, fps, duration=None):\r\n        # Include both sequential transfers plus OLED/scheduling margin.\r\n        interval = max(1.0 / fps, 2059 * 10 / self.connection.baudrate + 0.12)\r\n        count = 0\r\n        message = \"\"\r\n        quality_warning = \"\"\r\n        def check_quality(probes=3):\r\n            nonlocal quality_warning\r\n            try:\r\n                self.verify_payload_link(probes=probes)\r\n            except RuntimeError as error:\r\n                if not str(error).startswith(\"LINK QUALITY FAILED\"):\r\n                    raise\r\n                quality_warning = \" Reception errors detected; continuing playback.\"\r\n                self.worker_events.put((\"history\", f\"[Playback continuing despite {error}]\"))\r\n        try:\r\n            self.set_benchmark_mode(True)\r\n            self.worker_events.put((\"status\", \"Holding position and checking image-length reception before playback...\"))\r\n            if self.speed_stop.wait(.4):\r\n                raise RuntimeError(\"Playback cancelled.\")\r\n            check_quality()\r\n            deadline = None if duration is None else time.monotonic()+duration\r\n            while not self.speed_stop.is_set() and (deadline is None or time.monotonic() < deadline):\r\n                if count and count % 4 == 0 and not quality_warning:\r\n                    check_quality(probes=1)\r\n                started = time.monotonic()\r\n                payload, preview = frames[count % len(frames)]\r\n                self.connection.reset_input_buffer() # discard the shared UART's echoed data\r\n                self.connection.write(b\"IMAGE\\n\" + payload)\r\n                self.connection.flush()\r\n                count += 1\r\n                self.worker_events.put((\"preview\", preview))\r\n                self.worker_events.put((\"status\", f\"Playing {name}: frame {count}, up to {1/interval:.1f} fps. Click Stop to finish.{quality_warning}\"))\r\n                if self.speed_stop.wait(max(0, interval-(time.monotonic()-started))):\r\n                    # Allow the last frame to finish before sending a control command.\r\n                    time.sleep(max(0, interval-(time.monotonic()-started)))\r\n                    break\r\n            message = f\"Animation stopped after {count} frames. Link remains at {self.connection.baudrate:,} baud.{quality_warning}\"\r\n        except (serial.SerialException, RuntimeError, OSError) as error:\r\n            message = f\"Animation stopped: {error}\"\r\n        finally:\r\n            try:\r\n                self.set_benchmark_mode(False)\r\n            except (serial.SerialException, RuntimeError, OSError) as error:\r\n                message += f\" Could not resume tracking: {error}\"\r\n            self.worker_events.put((\"history\", f\"[Animation ended: {name}, {count} frames submitted]\"))\r\n            self.worker_events.put((\"done\", message))\r\n\r\n    def send_message(self, event=None):\r\n        if self.busy:\r\n            return \"break\"\r\n        if self.connection is None or not self.connection.is_open:\r\n            messagebox.showerror(\r\n                \"Not connected\",\r\n                f\"The app is not connected to {PORT}.\"\r\n            )\r\n            return \"break\"\r\n\r\n        text = self.message_entry.get()\r\n\r\n        if not text:\r\n            return \"break\"\r\n\r\n        if \"\\n\" in text or \"\\r\" in text:\r\n            messagebox.showwarning(\r\n                \"One line at a time\",\r\n                \"This version sends one line per message.\"\r\n            )\r\n            return \"break\"\r\n\r\n        if self.is_transmitter_command(text):\r\n            messagebox.showwarning(\r\n                \"Reserved transmitter command\",\r\n                \"That text matches a command used by the transmitter \"\r\n                \"firmware. Please try different wording.\"\r\n            )\r\n            return \"break\"\r\n\r\n        payload = text.encode(\"utf-8\")\r\n\r\n        if len(payload) > MAX_MESSAGE_BYTES:\r\n            messagebox.showwarning(\r\n                \"Message too long\",\r\n                f\"This message is {len(payload)} bytes. The receiver's \"\r\n                f\"normal-text limit is {MAX_MESSAGE_BYTES} bytes.\"\r\n            )\r\n            return \"break\"\r\n\r\n        try:\r\n            # The transmitter reads normal text until newline.\r\n            self.connection.write(payload + b\"\\n\")\r\n            self.connection.flush()\r\n            self.laser_solid = False\r\n\r\n            self.save_history_entry(text)\r\n            self.message_entry.delete(0, tk.END)\r\n\r\n        except serial.SerialException as error:\r\n            self.status_label.config(text=\"Serial send failed\")\r\n            messagebox.showerror(\r\n                \"Send error\",\r\n                f\"Could not send the message.\\n\\nDetails: {error}\"\r\n            )\r\n\r\n        return \"break\"\r\n\r\n    def send_image(self):\r\n        if self.busy:\r\n            return\r\n        if self.connection is None or not self.connection.is_open:\r\n            messagebox.showerror(\r\n                \"Not connected\",\r\n                f\"The app is not connected to {PORT}.\"\r\n            )\r\n            return\r\n\r\n        if self.image_payload is None or len(self.image_payload) != IMAGE_SIZE:\r\n            messagebox.showwarning(\r\n                \"No image\",\r\n                \"Choose an image first.\"\r\n            )\r\n            return\r\n\r\n        if self.selected_image_path is None:\r\n            return\r\n\r\n        try:\r\n            # Requires the matching transmitter firmware:\r\n            # \"IMAGE\\n\" followed by exactly 1024 image bytes.\r\n            self.connection.write(b\"IMAGE\\n\" + self.image_payload)\r\n            self.connection.flush()\r\n            self.laser_solid = False\r\n\r\n            self.save_history_entry(\r\n                f\"[Image submitted to transmitter: {self.selected_image_path.name}]\"\r\n            )\r\n            self.status_label.config(\r\n                text=\"Image uploaded. Transmitter aligns and sends over laser; check the receiver OLED.\"\r\n            )\r\n\r\n        except serial.SerialException as error:\r\n            self.status_label.config(text=\"Image send failed\")\r\n            messagebox.showerror(\r\n                \"Image send error\",\r\n                f\"Could not send the image.\\n\\nDetails: {error}\"\r\n            )\r\n\r\n    def read_response(self, prefixes, timeout=3):\r\n        deadline = time.monotonic() + timeout\r\n        buffer = bytearray()\r\n        while time.monotonic() < deadline:\r\n            buffer.extend(self.connection.readline())\r\n            while b\"\\n\" in buffer:\r\n                raw, _, remainder = buffer.partition(b\"\\n\")\r\n                buffer = bytearray(remainder)\r\n                line = raw.decode(\"ascii\", errors=\"ignore\").strip()\r\n                # Probe bytes can precede the text acknowledgment on this UART.\r\n                for prefix in prefixes:\r\n                    offset = line.find(prefix)\r\n                    if offset >= 0:\r\n                        return line[offset:]\r\n            if len(buffer) > 8192:\r\n                buffer.clear()\r\n        raise RuntimeError(\"No response from transmitter. Check the new firmware is uploaded to both boards.\")\r\n\r\n    def ensure_alignment_speed(self):\r\n        original_baud = self.connection.baudrate\r\n        try:\r\n            self.set_link_speed(BOOT_BAUD_RATE)\r\n            return\r\n        except RuntimeError as error:\r\n            if str(error).startswith(\"BAUD ERROR\"):\r\n                raise\r\n        # A lost acknowledgment can leave firmware at the requested speed.\r\n        # Re-negotiate from each likely rate; never infer success from silence.\r\n        for candidate in dict.fromkeys((BOOT_BAUD_RATE, original_baud, 230400, 460800)):\r\n            if self.speed_stop.is_set():\r\n                raise RuntimeError(\"Baud recovery cancelled. Reconnect before Home.\")\r\n            self.connection.baudrate = candidate\r\n            time.sleep(0.2)\r\n            try:\r\n                self.set_link_speed(BOOT_BAUD_RATE)\r\n                return\r\n            except RuntimeError as error:\r\n                if str(error).startswith(\"BAUD ERROR\"):\r\n                    raise\r\n        raise RuntimeError(\"Could not restore alignment baud. Reset the transmitter and reconnect.\")\r\n\r\n    def set_link_speed(self, baud):\r\n        # Check the USB driver accepts this rate before either board switches.\r\n        original = self.connection.baudrate\r\n        try:\r\n            self.connection.baudrate = baud\r\n        finally:\r\n            self.connection.baudrate = original\r\n        self.connection.reset_input_buffer()\r\n        self.connection.write(f\"BAUD {baud}\\n\".encode(\"ascii\"))\r\n        self.connection.flush()\r\n        try:\r\n            response = self.read_response((\"BAUD OK \", \"BAUD ERROR\"))\r\n        except RuntimeError:\r\n            # The acknowledgment may be lost after both boards have switched.\r\n            # Confirm by issuing the same request at the target rate.\r\n            self.connection.baudrate = baud\r\n            time.sleep(0.2)\r\n            self.connection.reset_input_buffer()\r\n            self.connection.write(f\"BAUD {baud}\\n\".encode(\"ascii\"))\r\n            self.connection.flush()\r\n            try:\r\n                response = self.read_response((\"BAUD OK \", \"BAUD ERROR\"))\r\n            except RuntimeError:\r\n                self.connection.baudrate = original\r\n                raise\r\n        if response != f\"BAUD OK {baud}\" and not response.startswith(\"BAUD OK \"):\r\n            raise RuntimeError(response)\r\n        # Even a damaged OK reply means firmware may already be switching.\r\n        # Verify at the requested rate rather than leaving USB at the old rate.\r\n        time.sleep(0.15)\r\n        self.connection.baudrate = baud\r\n        self.connection.reset_input_buffer()\r\n        if response != f\"BAUD OK {baud}\":\r\n            self.connection.write(f\"BAUD {baud}\\n\".encode(\"ascii\"))\r\n            self.connection.flush()\r\n            verified = self.read_response((\"BAUD OK \", \"BAUD ERROR\"))\r\n            if verified != f\"BAUD OK {baud}\":\r\n                raise RuntimeError(f\"Could not verify requested baud {baud}: {verified}\")\r\n            time.sleep(0.15)\r\n            self.connection.reset_input_buffer()\r\n\r\n    def set_benchmark_mode(self, enabled):\r\n        for attempt in range(3):\r\n            self.connection.reset_input_buffer()\r\n            self.connection.write(b\"BENCH ON\\n\" if enabled else b\"BENCH OFF\\n\")\r\n            self.connection.flush()\r\n            try:\r\n                self.read_response((\"BENCH OK\",), timeout=1)\r\n                return\r\n            except RuntimeError:\r\n                if attempt == 2:\r\n                    raise\r\n\r\n    def stop_speed_job(self):\r\n        self.speed_stop.set()\r\n        if self.job_kind == \"alignment\":\r\n            self.status_label.config(text=\"Cancelling search and returning home...\")\r\n            return\r\n        self.status_label.config(text=\"Stopping after the current transfer...\")\r\n\r\n    def start_speed_job(self, action):\r\n        if self.busy or self.connection is None or not self.connection.is_open:\r\n            return\r\n        self.busy = True\r\n        self.set_alignment_controls(False)\r\n        self.speed_stop = threading.Event()\r\n        for widget in (self.connect_button, self.send_button, self.send_image_button,\r\n                       self.apply_speed_button, self.horse_button, self.gif_button, self.select_image_button, self.fps_menu):\r\n            widget.config(state=\"disabled\")\r\n        self.stop_speed_button.config(state=\"normal\")\r\n        target = int(self.speed_choice.get())\r\n        threading.Thread(target=self.speed_worker, args=(action, target), daemon=True).start()\r\n\r\n    def speed_worker(self, action, target):\r\n        original = self.connection.baudrate\r\n        restore = original\r\n        message = \"\"\r\n        try:\r\n            self.set_benchmark_mode(True)\r\n            if action == \"apply\":\r\n                self.set_link_speed(target)\r\n                restore = target\r\n                self.requested_transmission_baud = target\r\n                message = f\"Applied {target:,} baud. Use Test Speed to check reliability.\"\r\n            else:\r\n                rates = [original] + [rate for rate in SPEED_RATES if rate > original] if action == \"scan\" else [original]\r\n                best = None\r\n                for rate in rates:\r\n                    if self.speed_stop.is_set():\r\n                        break\r\n                    self.set_link_speed(rate)\r\n                    passed = 0\r\n                    failed = False\r\n                    started = time.monotonic()\r\n                    for packet in range(20):\r\n                        if self.speed_stop.is_set():\r\n                            break\r\n                        self.worker_events.put((\"status\", f\"Testing {rate:,} baud: packet {packet + 1}/20\"))\r\n                        self.connection.reset_input_buffer()\r\n                        self.test_sequence = (self.test_sequence + 1) & 0xFFFFFFFF or 1\r\n                        self.connection.write(b\"SPEEDTEST\\n\" + speed_test_payload(self.test_sequence))\r\n                        self.connection.flush()\r\n                        response = self.read_response((\"TEST RESULT \", \"TEST TIMEOUT\"), timeout=8)\r\n                        fields = response.split()\r\n                        if len(fields) != 4 or fields[:2] != [\"TEST\", \"RESULT\"] or fields[2] != str(self.test_sequence) or fields[3] != \"0\":\r\n                            failed = True\r\n                            break\r\n                        passed += 1\r\n                    elapsed = time.monotonic() - started\r\n                    self.worker_events.put((\"history\", f\"[Speed test {rate:,} baud: {passed}/20 packets passed in {elapsed:.2f}s]\"))\r\n                    if passed == 20 and not failed:\r\n                        best = rate\r\n                        restore = rate\r\n                        self.requested_transmission_baud = rate\r\n                    else:\r\n                        message = f\"Test stopped at {rate:,} baud ({passed}/20 passed). Restored {restore:,} baud.\"\r\n                        break\r\n                if not message:\r\n                    message = f\"Highest tested passing rate: {best:,} baud (20/20 packets).\" if best else f\"Test stopped. Restored {restore:,} baud.\"\r\n        except (serial.SerialException, RuntimeError, OSError) as error:\r\n            message = f\"Speed test stopped: {error}. Returning to {restore:,} baud.\"\r\n        finally:\r\n            try:\r\n                # Radio control can lower the receiver baud even after optical failure.\r\n                self.set_link_speed(restore)\r\n                self.set_benchmark_mode(False)\r\n            except (serial.SerialException, RuntimeError, OSError) as error:\r\n                recovered = False\r\n                for candidate in dict.fromkeys((restore, target, original, BOOT_BAUD_RATE)):\r\n                    try:\r\n                        self.connection.baudrate = candidate\r\n                        time.sleep(0.2)\r\n                        self.set_link_speed(BOOT_BAUD_RATE)\r\n                        self.set_benchmark_mode(False)\r\n                        recovered = True\r\n                        message += \" Recovered at 38,400 baud.\"\r\n                        break\r\n                    except (serial.SerialException, RuntimeError, OSError):\r\n                        continue\r\n                if not recovered:\r\n                    message += f\" Recovery failed: {error}. Reset both boards and reconnect.\"\r\n            try:\r\n                Path(__file__).resolve().with_name(\"speed_trace.json\").write_text(\r\n                    json.dumps({\"action\": action, \"original_baud\": original,\r\n                                \"requested_baud\": target, \"final_baud\": self.connection.baudrate,\r\n                                \"result\": message}, indent=2), encoding=\"utf-8\")\r\n            except (OSError, TypeError):\r\n                pass\r\n            self.worker_events.put((\"done\", message))\r\n\r\n    def poll_worker(self):\r\n        try:\r\n            while True:\r\n                kind, value = self.worker_events.get_nowait()\r\n                if kind == \"laser\":\r\n                    self.laser_solid = value\r\n                elif kind == \"manual_off\":\r\n                    self.manual_mode.set(False)\r\n                elif kind == \"alignment\":\r\n                    self.update_alignment_status(value)\r\n                elif kind == 'dino_preview':\r\n                    popup = getattr(self, 'dino_window', None)\r\n                    if popup is not None and popup.winfo_exists():\r\n                        self.dino_photo = ImageTk.PhotoImage(value.resize((512, 256), Image.Resampling.NEAREST))\r\n                        self.dino_canvas.config(image=self.dino_photo, width=512, height=256)\r\n                elif kind == \"preview\":\r\n                    self.preview_photo = ImageTk.PhotoImage(value)\r\n                    self.preview_label.config(image=self.preview_photo, text=\"\", width=0, height=0)\r\n                elif kind == \"history\":\r\n                    self.save_history_entry(value)\r\n                else:\r\n                    self.status_label.config(text=value)\r\n                    popup = getattr(self, 'dino_window', None)\r\n                    if self.job_kind == 'dino' and popup is not None and popup.winfo_exists():\r\n                        self.dino_status_label.config(text=value)\r\n                if kind == \"done\":\r\n                    self.busy = False\r\n                    self.last_alignment_result = value\r\n                    if getattr(self, \"vision_window\", None) is not None and not self.vision_window.closed:\r\n                        self.vision_window.alignment_finished(value)\r\n                    self.job_kind = None\r\n                    if getattr(self, \"home_after_job\", False):\r\n                        self.home_after_job = False\r\n                        self.root.after(0, lambda: self.start_alignment(\"home\"))\r\n                    self.set_alignment_controls(True)\r\n                    self.stop_speed_button.config(text=\"Stop\")\r\n                    self.idle_serial_buffer.clear()\r\n                    if value.startswith(\"Animation stopped\") and self.selected_image_path is not None:\r\n                        self.refresh_image()\r\n                    self.speed_choice.set(str(self.connection.baudrate))\r\n                    for widget in (self.connect_button, self.send_button, self.apply_speed_button,\r\n                                   self.horse_button, self.gif_button, self.select_image_button, self.fps_menu):\r\n                        widget.config(state=\"normal\")\r\n                    self.send_image_button.config(state=\"normal\" if self.image_payload is not None else \"disabled\")\r\n                    self.stop_speed_button.config(state=\"disabled\")\r\n        except queue.Empty:\r\n            pass\r\n        self.poll_alignment_status()\r\n        self.root.after(100, self.poll_worker)\r\n\r\n    def close_app(self):\r\n        self.stop_manual_hold()\r\n        if getattr(self, \"vision_window\", None) is not None and not self.vision_window.closed:\r\n            self.vision_window.close()\r\n        if self.busy:\r\n            deadline = getattr(self, \"close_deadline\", None)\r\n            if deadline is None:\r\n                self.close_deadline = time.monotonic()+2\r\n                self.stop_speed_job()\r\n            if time.monotonic() < self.close_deadline:\r\n                self.root.after(200, self.close_app)\r\n                return\r\n        if self.connection is not None and self.connection.is_open:\r\n            try:\r\n                self.connection.cancel_read()\r\n                self.connection.cancel_write()\r\n                self.connection.close()\r\n            except (serial.SerialException, OSError):\r\n                pass\r\n\r\n        self.root.destroy()\r\n\r\n\r\ndef main():\r\n    import subprocess\r\n    import sys\r\n    splash = None\r\n    folder = Path(__file__).resolve().parent\r\n    try:\r\n        # A separate event loop keeps the horse moving during serial startup.\r\n        pythonw = Path(sys.executable).with_name(\"pythonw.exe\")\r\n        executable = str(pythonw) if pythonw.exists() else sys.executable\r\n        splash = subprocess.Popen(\r\n            [executable, str(folder / \"laser_branding.py\"), \"--splash\"],\r\n            stdin=subprocess.PIPE, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,\r\n            creationflags=getattr(subprocess, \"CREATE_NO_WINDOW\", 0),\r\n        )\r\n        window = tk.Tk()\r\n        window.withdraw()\r\n        window.startup_hidden = True\r\n        app = LaserTextTerminal(window)\r\n        window.state(\"zoomed\")\r\n        window.deiconify()\r\n    finally:\r\n        if splash is not None and splash.stdin is not None:\r\n            splash.stdin.close()\r\n    window.mainloop()\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    main()\r\n"}],"id":"ef555de4-928c-499d-9efc-9cd4ed8a3c88"},{"type":"code","heading":"Full Package (you need this)","files":[{"kind":"archive","filename":"LaserProject-source.zip","language":"ZIP archive","code":"","src":"data:application/zip;base64,"}],"id":"218e5cc8-bb46-4773-9517-72cdcb30db03"}],"motivation":"I started this project intending to make a program that could decode and encode morse code. I realized that the idea I really wanted to investigate was if I could send signals wirelessly over a laser. I succeeded in making a system that could highjack the UART signal to power a laser and send text between two esp32s and display it on an OLED, but I wanted to do way more than that.\n\nSeveral months later, I have a system that uses machine vision and a 2 axis servo mount to automatically align a laser, and can send text, images, animations, or stream a simple game live.","engineeringDetails":"The system is separated into a transmitter and receiver. The transmitter has 2 digital servo motors, a laser diode, and a u20x 1080p camera module. The receiver is an enclosed box with a 15mm focal length lens, a digital photodiode, an esp32, and a 2.41\" OLED display.\n\nA custom python app has a GUI with a terminal that allows you to send multiple different types of messages, select a transmission rate, and calibrate the CV. The app processes and converts text, images, and GIFs to bitmaps before sending them to the esp32 to send over UART.\n\nThe transmitter locates the receiver using computer vision that searches for a blue led next to the transmitter. The offset between the transmitter and the detector is recorded, and the transmitter calibrates its motion with the motion of the LED on the camera sensor. It can then align the laser with the detector in around 3s.\n\nAfter alignment is reached, a test packet is sent and confirmed using espNOW and then a gif of a horse running is transmitted to visually confirm alignment.","gallery":[],"videos":[{"title":"Dino Game","src":"Media/IMG_7644.MOV","poster":"","caption":""}],"parts":[],"cadFiles":[{"name":"","filename":"","src":"","description":""},{"name":"cambracket.SLDPRT","filename":"cambracket.SLDPRT","src":"data:application/octet-stream;base64,","description":"","size":195985},{"name":"receiver_box.SLDPRT","filename":"receiver_box.SLDPRT","src":"data:application/octet-stream;base64,","description":"","size":406197},{"name":"recvrtop.SLDPRT","filename":"recvrtop.SLDPRT","src":"data:application/octet-stream;base64,","description":"","size":90353}],"facts":[{"title":"Text","body":"More text"},{"title":"","body":""},{"title":"","body":""}],"sectionOrder":["overview","motivation","videos","engineering","links","content:6a9b7e82-b90d-4be2-8b2f-27d808bd6f28","content:ef555de4-928c-499d-9efc-9cd4ed8a3c88","content:218e5cc8-bb46-4773-9517-72cdcb30db03","photos","cad","parts"]},{"title":"Laser Microphone","category":"OPTICS + SIGNALS","description":"Project documentation coming soon.","image":"","imageAlt":"","link":"","id":"laser-microphone","blocks":[],"motivation":"","engineeringDetails":"","gallery":[],"videos":[],"parts":[],"cadFiles":[],"facts":[{"title":"","body":""},{"title":"","body":""},{"title":"","body":""}],"sectionOrder":["overview","motivation","engineering","links","photos","videos","cad","parts"]},{"title":"Adjustable Polarizing Sunglasses","category":"OPTICAL DESIGN","description":"Project documentation coming soon.","image":"","imageAlt":"","link":"","id":"adjustable-polarizing-sunglasses","blocks":[],"motivation":"","engineeringDetails":"","gallery":[],"videos":[],"parts":[],"cadFiles":[],"facts":[{"title":"","body":""},{"title":"","body":""},{"title":"","body":""}],"sectionOrder":["overview","motivation","engineering","links","photos","videos","cad","parts"]},{"title":"Adders","category":"Electrical Engineering","description":"Full and Half Adder circuits made from 2N2222 Transistors","image":"","imageAlt":"","link":"","motivation":"Digital Logic is fundamental to all electronic devices. To better understand logic gates and how they can be used for computation, I built a full and half adder using only BJT transistors. i saw this project as a prerequisite for later making a transistor only pseudorandom number generator.","engineeringDetails":"","gallery":[{"src":"","alt":"","caption":""}],"videos":[],"parts":[{"name":"2N2222 Transistor","quantity":"Many","link":"https://www.amazon.com/BOJACK-2N2222-General-Purpose-Transistors/dp/B07T61M92G/ref=sr_1_6?sr=8-6","image":"Media/Parts/51qZtmdOcpL._SL1500_.jpg","notes":""},{"name":"5mm LEDs","quantity":"","link":"https://www.amazon.com/California-JOS-50-PCS-Colorful/dp/B0CR886L92/ref=sr_1_3?sr=8-3","image":"","notes":""},{"name":"Resistors","quantity":"A lot","link":"https://www.amazon.com/BOJACK-Values-Resistor-Resistors-Assortment/dp/B08FD1XVL6/ref=sr_1_3?sr=8-3","image":"","notes":""}],"cadFiles":[],"id":"new-project","blocks":[],"facts":[{"title":"","body":""},{"title":"","body":""},{"title":"","body":""}],"sectionOrder":["overview","motivation","engineering","links","photos","videos","cad","parts"]}],"colors":{"ink":"#153033","paper":"#f5f4ee","muted":"#596c6e","line":"#d3d9d3","accent":"#b9ed76"},"cubeBlocks":[{"type":"code","heading":"Arduino Code","files":[{"filename":"BalanceCube_Jump.ino","language":"Arduino / C++","code":"#include <SimpleFOC.h>\n#include <Wire.h>\n#include <SparkFun_BNO08x_Arduino_Library.h>\n\n// ============================================================\n// MOTOR + DRIVER\n// ============================================================\n\nBLDCMotor motor = BLDCMotor(11);\n\nBLDCDriver3PWM driver(\n  32,  // phase A\n  33,  // phase B\n  25,  // phase C\n  22   // enable\n);\n\n// ============================================================\n// AS5048A PWM ENCODER\n// ============================================================\n\nconstexpr int ENCODER_PIN = 15;\n\n// Measured PWM limits\nMagneticSensorPWM sensor(ENCODER_PIN, 3, 921);\n\nvoid encoderISR() {\n  sensor.handlePWM();\n}\n\n// ============================================================\n// BNO085 IMU\n// ============================================================\n\nTwoWire IMU_Wire = TwoWire(1);\nBNO08x imu;\n\nconstexpr int IMU_SDA = 23;\nconstexpr int IMU_SCL = 5;\nconstexpr uint8_t IMU_ADDRESS = 0x4B;\n\n// Requested report interval in milliseconds.\n//\n// 10 ms = 100 Hz\n// 5 ms  = 200 Hz\n// 4 ms  = 250 Hz\n// 2 ms  = 500 Hz requested\n//\n// U command changes this over serial.\nuint16_t imuIntervalMs = 5;\n\n// ============================================================\n// PID SETTINGS\n// ============================================================\n\nfloat balanceSetpointDeg = 42.5f;\n\n// Kp = volts / degree\n// Ki = volts / (degree * second)\n// Kd = volts / (degree / second)\n\nfloat Kp = 5.0f;\nfloat Ki = 3.0f;\nfloat Kd = 0.2f;\n\n// ============================================================\n// OUTER WHEEL-SPEED PID\n//\n// This slower loop moves the balance setpoint slightly so the\n// cube leans in the direction that removes stored wheel speed.\n// Its output is degrees, not motor voltage.\n// ============================================================\n\nfloat wheelSpeedSetpointRPM = 10.0f;\n\n// Kp = degrees / RPM\n// Ki = degrees / (RPM * second)\n// Kd = degrees / (RPM / second)\nfloat wheelKp = 0.01f;\nfloat wheelKi = 0.01f;\nfloat wheelKd = 0.000f;\n\n// Maximum amount the outer loop may move the balance point.\n// This is the quiet, normal-operation limit.\nfloat maxBalanceOffsetDeg = 1.0f;\n\n// Recovery authority grows from the normal limit to this value\n// as absolute wheel-speed error rises from the start threshold\n// to the full-recovery threshold.\nfloat emergencyMaxBalanceOffsetDeg = 3.0f;\nfloat recoveryStartErrorRPM = 15.0f;\nfloat recoveryFullErrorRPM = 60.0f;\n\n// Maximum rate at which the outer loop may move the balance\n// point. This prevents a jerk when wheel speed changes sign.\n// Set to 0 to disable the slew-rate limit.\nfloat maxBalanceOffsetRateDegS = 5.0f;\n\n// The slew rate also grows during recovery so the extra\n// authority arrives quickly enough to catch the cube.\nfloat emergencyBalanceOffsetRateDegS = 60.0f;\n\n// Maximum integral contribution to the balance-point offset.\nfloat wheelIntegralLimitDeg = 1.0f;\n\n// Encoder-velocity low-pass filter. Smaller = smoother/slower.\nfloat wheelSpeedFilterAlpha = 0.05f;\n\n// Reverse with Q if wheel speed grows instead of settling.\nfloat wheelLoopDirection = -1.0f;\n\n// ============================================================\n// VOLTAGE SETTINGS\n// ============================================================\n\nconstexpr float SUPPLY_VOLTAGE = 15.0f;\n\n// Maximum commanded q-axis voltage\nfloat voltageLimit = 12.0f;\n\n// Maximum voltage contribution from integral term\nfloat integralVoltageLimit = 3.0f;\n\n// ============================================================\n// SAFETY / BALANCE SETTINGS\n// ============================================================\n\n// Stop driving after cube has clearly fallen\nfloat maxAllowedAngleErrorDeg = 20.0f;\n\n// Adjustable deadband\nfloat deadbandDeg = 0.0f;\n\n// Overall control direction\nfloat motorDirection = -1.0f;\n\n// Gyro direction\nfloat gyroDirection = 1.0f;\n\n// ============================================================\n// GYRO FILTER\n// ============================================================\n\n// 1.0 = no additional filtering\n// smaller = more smoothing, but more delay\nfloat gyroFilterAlpha = 1.0f;\n\n// ============================================================\n// STATE\n// ============================================================\n\nfloat pitchDeg = 0.0f;\n\nfloat rawGyroDegS = 0.0f;\nfloat filteredGyroDegS = 0.0f;\n\nfloat integralError = 0.0f;\n\nfloat filteredWheelSpeedRPM = 0.0f;\nfloat previousWheelSpeedError = 0.0f;\nfloat wheelIntegralError = 0.0f;\n\nfloat wheelPTerm = 0.0f;\nfloat wheelITerm = 0.0f;\nfloat wheelDTerm = 0.0f;\nfloat balanceOffsetDeg = 0.0f;\nfloat effectiveBalanceSetpointDeg = 42.5f;\nfloat recoveryFactor = 0.0f;\nfloat activeBalanceOffsetLimitDeg = 1.0f;\nfloat activeBalanceOffsetRateDegS = 5.0f;\n\nbool pitchValid = false;\nbool gyroValid = false;\n\nbool controllerEnabled = false;\nbool loggingEnabled = false;\n\n// The cube now has a physical power switch, so enable balancing\n// automatically after boot and after an IMU reset.\nconstexpr bool AUTO_START_CONTROLLER = true;\n\n// ============================================================\n// JUMP-UP SETTINGS + STATE\n// ============================================================\n\n// Send JUMP to:\n//   1. Ramp the wheel drive to full voltage.\n//   2. Hold full voltage until 320 RPM in the pre-spin direction.\n//   3. Apply full voltage until 320 RPM in the opposite direction.\n//   4. Hand off to the balance PID inside the capture window.\n//\n// JUMP+ and JUMP- force the kick direction. X aborts immediately.\nconstexpr float JUMP_TARGET_RPM = 320.0f;\nconstexpr uint32_t JUMP_RAMP_MS = 1200;\nconstexpr uint32_t JUMP_SPIN_TIMEOUT_MS = 4000;\nconstexpr uint32_t JUMP_REVERSE_TIMEOUT_MS = 4000;\nconstexpr uint32_t JUMP_CAPTURE_TIMEOUT_MS = 1500;\nconstexpr float JUMP_CAPTURE_ANGLE_DEG = 15.0f;\n\nenum JumpState {\n  JUMP_IDLE,\n  JUMP_RAMP,\n  JUMP_SPIN,\n  JUMP_REVERSE,\n  JUMP_CAPTURE\n};\n\nJumpState jumpState = JUMP_IDLE;\nuint32_t jumpPhaseStartMs = 0;\n\n// Sign of the voltage used for the kick toward upright.\n// The pre-spin direction is the opposite of this sign.\nfloat jumpKickSign = 1.0f;\n\nvoid startJump(float requestedKickSign);\nvoid finishJump(bool captured);\nvoid runJump();\n\n// Goes true whenever a fresh gyro packet arrives\nbool newControlSample = false;\n\nuint32_t previousControlMicros = 0;\n\n// Latest PID terms for logging\nfloat pTerm = 0.0f;\nfloat iTerm = 0.0f;\nfloat dTerm = 0.0f;\n\nfloat lastRawAngleError = 0.0f;\nfloat lastControlAngleError = 0.0f;\n\n// ============================================================\n// SERIAL OUTPUT\n// ============================================================\n\nvoid printCommands() {\n\n  Serial.println();\n  Serial.println(\"========== COMMANDS ==========\");\n\n  Serial.println(\"A          enable controller\");\n  Serial.println(\"X          disable controller\");\n  Serial.println(\"JUMP       run automatic jump-up sequence\");\n  Serial.println(\"JUMP+      force positive kick direction\");\n  Serial.println(\"JUMP-      force negative kick direction\");\n  Serial.println(\"           X aborts a jump immediately\");\n\n  Serial.println(\"P5.0       set Kp\");\n  Serial.println(\"I3.0       set Ki\");\n  Serial.println(\"D0.2       set Kd\");\n\n  Serial.println(\"S0.01      set wheel-speed Kp\");\n  Serial.println(\"T0.01      set wheel-speed Ki\");\n  Serial.println(\"Y0.000     set wheel-speed Kd\");\n  Serial.println(\"C10        set target wheel RPM\");\n  Serial.println(\"M1.0       set max balance offset in degrees\");\n  Serial.println(\"K3.0       set emergency max balance offset\");\n  Serial.println(\"W5.0       set max offset rate in deg/s (W0 disables)\");\n  Serial.println(\"J1.0       set wheel integral limit in degrees\");\n  Serial.println(\"O0.05      set wheel-speed filter alpha\");\n  Serial.println(\"Q          reverse wheel-loop direction\");\n\n  Serial.println(\"B42.5      set balance point\");\n\n  Serial.println(\"H0.0       set deadband in degrees\");\n\n  Serial.println(\"V12.0      set voltage limit (max 15 V)\");\n  Serial.println(\"N3.0       set integral voltage limit\");\n\n  Serial.println(\"F1.0       set gyro filter alpha\");\n\n  Serial.println(\"E20.0      set fall cutoff angle\");\n\n  Serial.println(\"U5         set IMU report interval in ms\");\n  Serial.println(\"           U10 = 100 Hz\");\n  Serial.println(\"           U5  = 200 Hz\");\n  Serial.println(\"           U4  = 250 Hz\");\n  Serial.println(\"           U2  = 500 Hz requested\");\n\n  Serial.println(\"R          reverse motor direction\");\n  Serial.println(\"G          reverse gyro direction\");\n\n  Serial.println(\"Z          clear integral\");\n\n  Serial.println(\"L          toggle CSV logging\");\n\n  Serial.println(\"?          print settings\");\n\n  Serial.println(\"==============================\");\n  Serial.println();\n}\n\n// ============================================================\n// PRINT SETTINGS\n// ============================================================\n\nvoid printSettings() {\n\n  Serial.println();\n  Serial.println(\"========== PID SETTINGS ==========\");\n\n  Serial.print(\"Balance setpoint: \");\n  Serial.print(balanceSetpointDeg, 3);\n  Serial.println(\" deg\");\n\n  Serial.print(\"Kp: \");\n  Serial.println(Kp, 6);\n\n  Serial.print(\"Ki: \");\n  Serial.println(Ki, 6);\n\n  Serial.print(\"Kd: \");\n  Serial.println(Kd, 6);\n\n  Serial.print(\"Wheel target: \");\n  Serial.print(wheelSpeedSetpointRPM, 2);\n  Serial.println(\" RPM\");\n\n  Serial.print(\"Wheel Kp / Ki / Kd: \");\n  Serial.print(wheelKp, 6);\n  Serial.print(\" / \");\n  Serial.print(wheelKi, 6);\n  Serial.print(\" / \");\n  Serial.println(wheelKd, 6);\n\n  Serial.print(\"Max balance offset: \");\n  Serial.print(maxBalanceOffsetDeg, 3);\n  Serial.println(\" deg\");\n\n  Serial.print(\"Emergency max balance offset: \");\n  Serial.print(emergencyMaxBalanceOffsetDeg, 3);\n  Serial.println(\" deg\");\n\n  Serial.print(\"Recovery error range: \");\n  Serial.print(recoveryStartErrorRPM, 1);\n  Serial.print(\" to \");\n  Serial.print(recoveryFullErrorRPM, 1);\n  Serial.println(\" RPM\");\n\n  Serial.print(\"Max balance offset rate: \");\n  Serial.print(maxBalanceOffsetRateDegS, 3);\n  Serial.println(\" deg/s\");\n\n  Serial.print(\"Emergency balance offset rate: \");\n  Serial.print(emergencyBalanceOffsetRateDegS, 3);\n  Serial.println(\" deg/s\");\n\n  Serial.print(\"Wheel integral limit: \");\n  Serial.print(wheelIntegralLimitDeg, 3);\n  Serial.println(\" deg\");\n\n  Serial.print(\"Wheel filter alpha: \");\n  Serial.println(wheelSpeedFilterAlpha, 3);\n\n  Serial.print(\"Wheel-loop direction: \");\n  Serial.println(wheelLoopDirection, 0);\n\n  Serial.print(\"Deadband: \");\n  Serial.print(deadbandDeg, 3);\n  Serial.println(\" deg\");\n\n  Serial.print(\"Voltage limit: \");\n  Serial.print(voltageLimit, 2);\n  Serial.println(\" V\");\n\n  Serial.print(\"Integral voltage limit: \");\n  Serial.print(integralVoltageLimit, 2);\n  Serial.println(\" V\");\n\n  Serial.print(\"Fall cutoff: \");\n  Serial.print(maxAllowedAngleErrorDeg, 2);\n  Serial.println(\" deg\");\n\n  Serial.print(\"Motor direction: \");\n  Serial.println(motorDirection, 0);\n\n  Serial.print(\"Gyro direction: \");\n  Serial.println(gyroDirection, 0);\n\n  Serial.print(\"Gyro filter alpha: \");\n  Serial.println(gyroFilterAlpha, 3);\n\n  Serial.print(\"IMU interval: \");\n  Serial.print(imuIntervalMs);\n  Serial.println(\" ms\");\n\n  Serial.print(\"Requested IMU rate: \");\n  Serial.print(1000.0f / imuIntervalMs, 1);\n  Serial.println(\" Hz\");\n\n  Serial.print(\"Controller: \");\n  Serial.println(controllerEnabled ? \"ENABLED\" : \"DISABLED\");\n\n  Serial.print(\"Logging: \");\n  Serial.println(loggingEnabled ? \"ON\" : \"OFF\");\n\n  Serial.print(\"Jump state: \");\n  Serial.println(jumpState == JUMP_IDLE ? \"IDLE\" : \"ACTIVE\");\n\n  Serial.print(\"Jump target speed: \");\n  Serial.print(JUMP_TARGET_RPM, 0);\n  Serial.println(\" RPM\");\n\n  Serial.print(\"Jump ramp/spin/reverse timeouts: \");\n  Serial.print(JUMP_RAMP_MS);\n  Serial.print(\" / \");\n  Serial.print(JUMP_SPIN_TIMEOUT_MS);\n  Serial.print(\" / \");\n  Serial.print(JUMP_REVERSE_TIMEOUT_MS);\n  Serial.println(\" ms\");\n\n  Serial.println(\"==================================\");\n  Serial.println();\n}\n\n// ============================================================\n// STOP CONTROLLER\n// ============================================================\n\nvoid stopController(bool printMessage) {\n\n  controllerEnabled = false;\n  jumpState = JUMP_IDLE;\n\n  integralError = 0.0f;\n  wheelIntegralError = 0.0f;\n  previousWheelSpeedError = 0.0f;\n  balanceOffsetDeg = 0.0f;\n  effectiveBalanceSetpointDeg = balanceSetpointDeg;\n  recoveryFactor = 0.0f;\n  activeBalanceOffsetLimitDeg = maxBalanceOffsetDeg;\n  activeBalanceOffsetRateDegS = maxBalanceOffsetRateDegS;\n\n  wheelPTerm = 0.0f;\n  wheelITerm = 0.0f;\n  wheelDTerm = 0.0f;\n\n  pTerm = 0.0f;\n  iTerm = 0.0f;\n  dTerm = 0.0f;\n\n  motor.target = 0.0f;\n\n  if (printMessage) {\n    Serial.println(\"Controller DISABLED\");\n  }\n}\n\n// ============================================================\n// JUMP-UP SEQUENCE\n// ============================================================\n\nvoid startJump(float requestedKickSign) {\n\n  if (jumpState != JUMP_IDLE) {\n    Serial.println(\"Jump already active; send X to abort.\");\n    return;\n  }\n\n  if (!pitchValid || !gyroValid) {\n    Serial.println(\"Jump refused: waiting for valid IMU data.\");\n    return;\n  }\n\n  float rawAngleError =\n    pitchDeg -\n    balanceSetpointDeg;\n\n  // JUMP is a deliberate manual command. Do not reject it based on\n  // pitch: either resting side is only about 42.5 or 47.5 degrees\n  // from the 42.5-degree balance point, and IMU angle wrapping can\n  // make a fixed side-angle test unreliable.\n  Serial.print(\"JUMP: pitch/error = \");\n  Serial.print(pitchDeg, 2);\n  Serial.print(\" / \");\n  Serial.println(rawAngleError, 2);\n\n  controllerEnabled = false;\n  integralError = 0.0f;\n  wheelIntegralError = 0.0f;\n  previousWheelSpeedError = 0.0f;\n  balanceOffsetDeg = 0.0f;\n  effectiveBalanceSetpointDeg = balanceSetpointDeg;\n  recoveryFactor = 0.0f;\n  activeBalanceOffsetLimitDeg = maxBalanceOffsetDeg;\n  activeBalanceOffsetRateDegS = maxBalanceOffsetRateDegS;\n\n  if (requestedKickSign > 0.0f) {\n    jumpKickSign = 1.0f;\n  }\n  else if (requestedKickSign < 0.0f) {\n    jumpKickSign = -1.0f;\n  }\n  else {\n    // Select the voltage direction that the proven balance PID\n    // would use to correct the cube from its present side.\n    jumpKickSign =\n      (motorDirection * rawAngleError >= 0.0f) ?\n      1.0f : -1.0f;\n  }\n\n  motor.target = 0.0f;\n  jumpPhaseStartMs = millis();\n  jumpState = JUMP_RAMP;\n\n  Serial.print(\"JUMP START: kick direction = \");\n  Serial.println(jumpKickSign, 0);\n  Serial.println(\"Send X to abort.\");\n}\n\nvoid finishJump(bool captured) {\n\n  jumpState = JUMP_IDLE;\n  motor.target = 0.0f;\n  integralError = 0.0f;\n  wheelIntegralError = 0.0f;\n  balanceOffsetDeg = 0.0f;\n  effectiveBalanceSetpointDeg = balanceSetpointDeg;\n\n  if (captured) {\n    filteredGyroDegS = rawGyroDegS;\n    filteredWheelSpeedRPM =\n      motor.shaft_velocity * 60.0f / (2.0f * PI);\n    previousWheelSpeedError =\n      wheelSpeedSetpointRPM - filteredWheelSpeedRPM;\n    previousControlMicros = micros();\n    controllerEnabled = true;\n    Serial.println(\"JUMP CAPTURED: balance controller enabled.\");\n  }\n  else {\n    controllerEnabled = false;\n    Serial.println(\"JUMP ENDED: capture failed; motor stopped.\");\n  }\n}\n\nvoid runJump() {\n\n  if (jumpState == JUMP_IDLE) {\n    return;\n  }\n\n  uint32_t elapsedMs =\n    millis() -\n    jumpPhaseStartMs;\n\n  float rawAngleError =\n    pitchDeg -\n    balanceSetpointDeg;\n\n  // Transfer to the working balance controller immediately once\n  // the reverse kick brings the cube into the capture window.\n  if (\n    (jumpState == JUMP_REVERSE || jumpState == JUMP_CAPTURE) &&\n    fabs(rawAngleError) <= JUMP_CAPTURE_ANGLE_DEG\n  ) {\n    finishJump(true);\n    return;\n  }\n\n  switch (jumpState) {\n\n    case JUMP_RAMP: {\n\n      float rampFraction =\n        constrain(\n          elapsedMs / (float)JUMP_RAMP_MS,\n          0.0f,\n          1.0f\n        );\n\n      // Pre-spin opposite the direction of the upcoming kick.\n      motor.target =\n        -jumpKickSign *\n        voltageLimit *\n        rampFraction;\n\n      if (elapsedMs >= JUMP_RAMP_MS) {\n        jumpState = JUMP_SPIN;\n        jumpPhaseStartMs = millis();\n        Serial.println(\"JUMP: full-voltage spin-up.\");\n      }\n\n      break;\n    }\n\n    case JUMP_SPIN: {\n\n      motor.target =\n        -jumpKickSign *\n        voltageLimit;\n\n      float wheelRPM =\n        fabs(motor.shaft_velocity) *\n        60.0f /\n        (2.0f * PI);\n\n      if (\n        wheelRPM >= JUMP_TARGET_RPM ||\n        elapsedMs >= JUMP_SPIN_TIMEOUT_MS\n      ) {\n        if (wheelRPM >= JUMP_TARGET_RPM) {\n          Serial.print(\"JUMP: target reached at \");\n        }\n        else {\n          Serial.print(\"JUMP: spin timeout at \");\n        }\n\n        Serial.print(wheelRPM, 0);\n        Serial.println(\" RPM; applying full reverse.\");\n\n        jumpState = JUMP_REVERSE;\n        jumpPhaseStartMs = millis();\n      }\n\n      break;\n    }\n\n    case JUMP_REVERSE: {\n\n      // Drive all the way through zero to the target speed in the\n      // opposite direction. This gives the wheel its maximum possible\n      // momentum change before the balance controller takes over.\n      motor.target =\n        jumpKickSign *\n        voltageLimit;\n\n      float signedWheelRPM =\n        motor.shaft_velocity *\n        60.0f /\n        (2.0f * PI);\n\n      bool reverseTargetReached =\n        jumpKickSign * signedWheelRPM >=\n        JUMP_TARGET_RPM;\n\n      if (\n        reverseTargetReached ||\n        elapsedMs >= JUMP_REVERSE_TIMEOUT_MS\n      ) {\n        motor.target = 0.0f;\n        jumpState = JUMP_CAPTURE;\n        jumpPhaseStartMs = millis();\n\n        if (reverseTargetReached) {\n          Serial.println(\"JUMP: full reverse RPM reached; waiting for capture.\");\n        }\n        else {\n          Serial.println(\"JUMP: reverse timeout; waiting for capture.\");\n        }\n      }\n\n      break;\n    }\n\n    case JUMP_CAPTURE:\n\n      motor.target = 0.0f;\n\n      if (elapsedMs >= JUMP_CAPTURE_TIMEOUT_MS) {\n        finishJump(false);\n      }\n\n      break;\n\n    default:\n\n      finishJump(false);\n      break;\n  }\n}\n\n// ============================================================\n// ENABLE IMU REPORTS\n// ============================================================\n\nbool enableIMUReports() {\n\n  // Same requested update rate for orientation and gyro\n  bool rotationOK =\n    imu.enableRotationVector(imuIntervalMs);\n\n  bool gyroOK =\n    imu.enableGyro(imuIntervalMs);\n\n  return rotationOK && gyroOK;\n}\n\n// ============================================================\n// UPDATE IMU RATE\n// ============================================================\n\nvoid setIMURate(uint16_t intervalMs) {\n\n  // Avoid requesting an interval of zero\n  if (intervalMs < 1) {\n    intervalMs = 1;\n  }\n\n  // Disable controller during reconfiguration\n  bool wasEnabled = controllerEnabled;\n\n  motor.target = 0.0f;\n  controllerEnabled = false;\n\n  imuIntervalMs = intervalMs;\n\n  if (enableIMUReports()) {\n\n    Serial.print(\"IMU interval = \");\n    Serial.print(imuIntervalMs);\n    Serial.println(\" ms\");\n\n    Serial.print(\"Requested rate = \");\n    Serial.print(1000.0f / imuIntervalMs, 1);\n    Serial.println(\" Hz\");\n\n  } else {\n\n    Serial.println(\"ERROR: Could not update IMU reports.\");\n  }\n\n  filteredGyroDegS = 0.0f;\n  integralError = 0.0f;\n  wheelIntegralError = 0.0f;\n  balanceOffsetDeg = 0.0f;\n  effectiveBalanceSetpointDeg = balanceSetpointDeg;\n\n  previousControlMicros = micros();\n\n  if (wasEnabled && AUTO_START_CONTROLLER) {\n\n    controllerEnabled = true;\n\n    Serial.println(\n      \"Controller automatically re-enabled after IMU rate change.\"\n    );\n\n  }\n\n  else if (wasEnabled) {\n\n    Serial.println(\n      \"Controller remains disabled after IMU rate change.\"\n    );\n\n    Serial.println(\n      \"Send A to enable again.\"\n    );\n  }\n}\n\n// ============================================================\n// SERIAL COMMAND HANDLING\n// ============================================================\n\nvoid processSerial() {\n\n  if (!Serial.available()) {\n    return;\n  }\n\n  String input = Serial.readStringUntil('\\n');\n  input.trim();\n\n  if (input.length() == 0) {\n    return;\n  }\n\n  // J already controls the wheel integral limit, so jump uses\n  // complete-word commands that are handled before letter parsing.\n  if (input.equalsIgnoreCase(\"JUMP\")) {\n    startJump(0.0f);\n    return;\n  }\n\n  if (input.equalsIgnoreCase(\"JUMP+\")) {\n    startJump(1.0f);\n    return;\n  }\n\n  if (input.equalsIgnoreCase(\"JUMP-\")) {\n    startJump(-1.0f);\n    return;\n  }\n\n  char command = toupper(input.charAt(0));\n\n  float value = 0.0f;\n\n  if (input.length() > 1) {\n    value = input.substring(1).toFloat();\n  }\n\n  switch (command) {\n\n    // --------------------------------------------------------\n    // ENABLE\n    // --------------------------------------------------------\n\n    case 'A':\n\n      jumpState = JUMP_IDLE;\n      motor.target = 0.0f;\n\n      integralError = 0.0f;\n      wheelIntegralError = 0.0f;\n\n      filteredWheelSpeedRPM =\n        motor.shaft_velocity * 60.0f / (2.0f * PI);\n\n      previousWheelSpeedError =\n        wheelSpeedSetpointRPM - filteredWheelSpeedRPM;\n\n      filteredGyroDegS = rawGyroDegS;\n\n      previousControlMicros = micros();\n\n      controllerEnabled = true;\n\n      Serial.println(\"Controller ENABLED\");\n\n      break;\n\n    // --------------------------------------------------------\n    // DISABLE\n    // --------------------------------------------------------\n\n    case 'X':\n\n      stopController(true);\n\n      break;\n\n    // --------------------------------------------------------\n    // KP\n    // --------------------------------------------------------\n\n    case 'P':\n\n      if (value >= 0.0f && value <= 10.0f) {\n\n        Kp = value;\n\n        Serial.print(\"Kp = \");\n        Serial.println(Kp, 6);\n\n      } else {\n\n        Serial.println(\"Use P between 0 and 10.\");\n      }\n\n      break;\n\n    // --------------------------------------------------------\n    // KI\n    // --------------------------------------------------------\n\n    case 'I':\n\n      if (value >= 0.0f && value <= 10.0f) {\n\n        Ki = value;\n\n        integralError = 0.0f;\n\n        Serial.print(\"Ki = \");\n        Serial.println(Ki, 6);\n\n      } else {\n\n        Serial.println(\"Use I between 0 and 10.\");\n      }\n\n      break;\n\n    // --------------------------------------------------------\n    // KD\n    // --------------------------------------------------------\n\n    case 'D':\n\n      if (value >= 0.0f && value <= 1.0f) {\n\n        Kd = value;\n\n        Serial.print(\"Kd = \");\n        Serial.println(Kd, 6);\n\n      } else {\n\n        Serial.println(\"Use D between 0 and 1.\");\n      }\n\n      break;\n\n    // --------------------------------------------------------\n    // OUTER WHEEL-SPEED PID\n    // --------------------------------------------------------\n\n    case 'S':\n\n      if (value >= 0.0f && value <= 1.0f) {\n        wheelKp = value;\n        Serial.print(\"Wheel Kp = \");\n        Serial.println(wheelKp, 6);\n      } else {\n        Serial.println(\"Use S between 0 and 1.\");\n      }\n      break;\n\n    case 'T':\n\n      if (value >= 0.0f && value <= 1.0f) {\n        wheelKi = value;\n        wheelIntegralError = 0.0f;\n        Serial.print(\"Wheel Ki = \");\n        Serial.println(wheelKi, 6);\n      } else {\n        Serial.println(\"Use T between 0 and 1.\");\n      }\n      break;\n\n    case 'Y':\n\n      if (value >= 0.0f && value <= 1.0f) {\n        wheelKd = value;\n        Serial.print(\"Wheel Kd = \");\n        Serial.println(wheelKd, 6);\n      } else {\n        Serial.println(\"Use Y between 0 and 1.\");\n      }\n      break;\n\n    case 'C':\n\n      if (value >= -10000.0f && value <= 10000.0f) {\n        wheelSpeedSetpointRPM = value;\n        wheelIntegralError = 0.0f;\n        Serial.print(\"Wheel target = \");\n        Serial.print(wheelSpeedSetpointRPM, 2);\n        Serial.println(\" RPM\");\n      } else {\n        Serial.println(\"Use C between -10000 and 10000 RPM.\");\n      }\n      break;\n\n    case 'M':\n\n      if (value >= 0.0f && value <= emergencyMaxBalanceOffsetDeg) {\n        maxBalanceOffsetDeg = value;\n        wheelIntegralError = 0.0f;\n        Serial.print(\"Max balance offset = \");\n        Serial.print(maxBalanceOffsetDeg, 3);\n        Serial.println(\" deg\");\n      } else {\n        Serial.println(\"Use M between 0 and the emergency maximum.\");\n      }\n      break;\n\n    case 'K':\n\n      if (value >= maxBalanceOffsetDeg && value <= 10.0f) {\n        emergencyMaxBalanceOffsetDeg = value;\n        Serial.print(\"Emergency max balance offset = \");\n        Serial.print(emergencyMaxBalanceOffsetDeg, 3);\n        Serial.println(\" deg\");\n      } else {\n        Serial.println(\"Use K between normal M and 10 degrees.\");\n      }\n      break;\n\n    case 'W':\n\n      if (value >= 0.0f && value <= 100.0f) {\n        maxBalanceOffsetRateDegS = value;\n        Serial.print(\"Max balance offset rate = \");\n        Serial.print(maxBalanceOffsetRateDegS, 3);\n        Serial.println(\" deg/s\");\n      } else {\n        Serial.println(\"Use W between 0 and 100 deg/s.\");\n      }\n      break;\n\n    case 'J':\n\n      if (value >= 0.0f && value <= 10.0f) {\n        wheelIntegralLimitDeg = value;\n        wheelIntegralError = 0.0f;\n        Serial.print(\"Wheel integral limit = \");\n        Serial.print(wheelIntegralLimitDeg, 3);\n        Serial.println(\" deg\");\n      } else {\n        Serial.println(\"Use J between 0 and 10 degrees.\");\n      }\n      break;\n\n    case 'O':\n\n      if (value > 0.0f && value <= 1.0f) {\n        wheelSpeedFilterAlpha = value;\n        Serial.print(\"Wheel filter alpha = \");\n        Serial.println(wheelSpeedFilterAlpha, 3);\n      } else {\n        Serial.println(\"Use O > 0 and <= 1.\");\n      }\n      break;\n\n    case 'Q':\n\n      wheelLoopDirection *= -1.0f;\n      wheelIntegralError = 0.0f;\n      Serial.print(\"Wheel-loop direction = \");\n      Serial.println(wheelLoopDirection, 0);\n      break;\n\n    // --------------------------------------------------------\n    // BALANCE POINT\n    // --------------------------------------------------------\n\n    case 'B':\n\n      balanceSetpointDeg = value;\n\n      integralError = 0.0f;\n      wheelIntegralError = 0.0f;\n      balanceOffsetDeg = 0.0f;\n      effectiveBalanceSetpointDeg = balanceSetpointDeg;\n\n      Serial.print(\"Balance setpoint = \");\n      Serial.println(balanceSetpointDeg, 3);\n\n      break;\n\n    // --------------------------------------------------------\n    // DEADBAND\n    // --------------------------------------------------------\n\n    case 'H':\n\n      if (value >= 0.0f && value <= 5.0f) {\n\n        deadbandDeg = value;\n\n        integralError = 0.0f;\n\n        Serial.print(\"Deadband = \");\n        Serial.print(deadbandDeg, 3);\n        Serial.println(\" deg\");\n\n      } else {\n\n        Serial.println(\n          \"Use H between 0 and 5 degrees.\"\n        );\n      }\n\n      break;\n\n    // --------------------------------------------------------\n    // VOLTAGE LIMIT\n    // --------------------------------------------------------\n\n    case 'V':\n\n      if (\n        value > 0.0f &&\n        value <= SUPPLY_VOLTAGE\n      ) {\n\n        voltageLimit = value;\n\n        driver.voltage_limit = voltageLimit;\n        motor.voltage_limit = voltageLimit;\n\n        Serial.print(\"Voltage limit = \");\n        Serial.print(voltageLimit, 2);\n        Serial.println(\" V\");\n\n      } else {\n\n        Serial.println(\n          \"Use V greater than 0 and <= 15.\"\n        );\n      }\n\n      break;\n\n    // --------------------------------------------------------\n    // INTEGRAL LIMIT\n    // --------------------------------------------------------\n\n    case 'N':\n\n      if (\n        value >= 0.0f &&\n        value <= SUPPLY_VOLTAGE\n      ) {\n\n        integralVoltageLimit = value;\n\n        integralError = 0.0f;\n\n        Serial.print(\n          \"Integral voltage limit = \"\n        );\n\n        Serial.print(\n          integralVoltageLimit,\n          2\n        );\n\n        Serial.println(\" V\");\n\n      } else {\n\n        Serial.println(\n          \"Use N between 0 and 15.\"\n        );\n      }\n\n      break;\n\n    // --------------------------------------------------------\n    // GYRO FILTER\n    // --------------------------------------------------------\n\n    case 'F':\n\n      if (\n        value > 0.0f &&\n        value <= 1.0f\n      ) {\n\n        gyroFilterAlpha = value;\n\n        Serial.print(\n          \"Gyro filter alpha = \"\n        );\n\n        Serial.println(\n          gyroFilterAlpha,\n          3\n        );\n\n      } else {\n\n        Serial.println(\n          \"Use F > 0 and <= 1.\"\n        );\n      }\n\n      break;\n\n    // --------------------------------------------------------\n    // FALL CUTOFF\n    // --------------------------------------------------------\n\n    case 'E':\n\n      if (\n        value > 0.0f &&\n        value <= 90.0f\n      ) {\n\n        maxAllowedAngleErrorDeg = value;\n\n        Serial.print(\"Fall cutoff = \");\n\n        Serial.print(\n          maxAllowedAngleErrorDeg,\n          2\n        );\n\n        Serial.println(\" deg\");\n\n      } else {\n\n        Serial.println(\n          \"Use E between 0 and 90 degrees.\"\n        );\n      }\n\n      break;\n\n    // --------------------------------------------------------\n    // IMU UPDATE INTERVAL\n    // --------------------------------------------------------\n\n    case 'U':\n\n      if (\n        value >= 1.0f &&\n        value <= 100.0f\n      ) {\n\n        setIMURate(\n          (uint16_t)value\n        );\n\n      } else {\n\n        Serial.println(\n          \"Use U between 1 and 100 ms.\"\n        );\n      }\n\n      break;\n\n    // --------------------------------------------------------\n    // MOTOR DIRECTION\n    // --------------------------------------------------------\n\n    case 'R':\n\n      motorDirection *= -1.0f;\n\n      integralError = 0.0f;\n\n      Serial.print(\"Motor direction = \");\n      Serial.println(motorDirection, 0);\n\n      break;\n\n    // --------------------------------------------------------\n    // GYRO DIRECTION\n    // --------------------------------------------------------\n\n    case 'G':\n\n      gyroDirection *= -1.0f;\n\n      filteredGyroDegS = 0.0f;\n\n      Serial.print(\"Gyro direction = \");\n      Serial.println(gyroDirection, 0);\n\n      break;\n\n    // --------------------------------------------------------\n    // CLEAR INTEGRAL\n    // --------------------------------------------------------\n\n    case 'Z':\n\n      integralError = 0.0f;\n      wheelIntegralError = 0.0f;\n\n      Serial.println(\"Both integrals cleared\");\n\n      break;\n\n    // --------------------------------------------------------\n    // LOGGING\n    // --------------------------------------------------------\n\n    case 'L':\n\n      loggingEnabled =\n        !loggingEnabled;\n\n      if (loggingEnabled) {\n\n        Serial.println(\n          \"Logging ON\"\n        );\n\n        Serial.println(\n          \"ms,rawError,error,gyro,wheelRPM,recoveryFactor,activeM,activeW,balanceOffset,effectiveSetpoint,P,I,D,target\"\n        );\n\n      } else {\n\n        Serial.println(\n          \"Logging OFF\"\n        );\n      }\n\n      break;\n\n    // --------------------------------------------------------\n    // SETTINGS\n    // --------------------------------------------------------\n\n    case '?':\n\n      printSettings();\n\n      break;\n\n    // --------------------------------------------------------\n    // UNKNOWN\n    // --------------------------------------------------------\n\n    default:\n\n      Serial.println(\n        \"Unknown command.\"\n      );\n\n      printCommands();\n\n      break;\n  }\n}\n\n// ============================================================\n// UPDATE IMU\n// ============================================================\n\nvoid updateIMU() {\n\n  newControlSample = false;\n\n  while (imu.getSensorEvent()) {\n\n    uint8_t reportID =\n      imu.getSensorEventID();\n\n    // --------------------------------------------------------\n    // ROTATION VECTOR\n    // --------------------------------------------------------\n\n    if (\n      reportID ==\n      SENSOR_REPORTID_ROTATION_VECTOR\n    ) {\n\n      pitchDeg =\n        imu.getPitch() *\n        180.0f /\n        PI;\n\n      pitchValid = true;\n    }\n\n    // --------------------------------------------------------\n    // GYROSCOPE\n    // --------------------------------------------------------\n\n    else if (\n      reportID ==\n      SENSOR_REPORTID_GYROSCOPE_CALIBRATED\n    ) {\n\n      rawGyroDegS =\n        gyroDirection *\n        imu.getGyroY() *\n        180.0f /\n        PI;\n\n      filteredGyroDegS +=\n        gyroFilterAlpha *\n        (\n          rawGyroDegS -\n          filteredGyroDegS\n        );\n\n      gyroValid = true;\n\n      // New gyro packet = new control update\n      newControlSample = true;\n    }\n  }\n\n  // ----------------------------------------------------------\n  // IMU RESET HANDLING\n  // ----------------------------------------------------------\n\n  if (imu.wasReset()) {\n\n    pitchValid = false;\n    gyroValid = false;\n\n    rawGyroDegS = 0.0f;\n    filteredGyroDegS = 0.0f;\n\n    integralError = 0.0f;\n    wheelIntegralError = 0.0f;\n\n    stopController(false);\n\n    delay(10);\n\n    if (!enableIMUReports()) {\n\n      Serial.println(\n        \"ERROR re-enabling IMU after reset.\"\n      );\n\n    } else {\n\n      Serial.println(\n        \"IMU reset detected.\"\n      );\n\n      if (AUTO_START_CONTROLLER) {\n        previousControlMicros = micros();\n        controllerEnabled = true;\n        Serial.println(\n          \"Controller automatically re-enabled; waiting for IMU data.\"\n        );\n      } else {\n        Serial.println(\n          \"Controller disabled; send A.\"\n        );\n      }\n    }\n  }\n}\n\n// ============================================================\n// CONTROLLER\n// ============================================================\n\nvoid runController() {\n\n  uint32_t nowMicros =\n    micros();\n\n  float dt =\n    (\n      nowMicros -\n      previousControlMicros\n    ) *\n    1.0e-6f;\n\n  previousControlMicros =\n    nowMicros;\n\n  // Expected dt at 200 Hz is ~0.005 seconds.\n  // Ignore obviously invalid values.\n  if (\n    dt <= 0.0f ||\n    dt > 0.05f\n  ) {\n\n    dt =\n      imuIntervalMs *\n      0.001f;\n  }\n\n  // ==========================================================\n  // OUTER WHEEL-SPEED PID\n  // ==========================================================\n\n  float rawWheelSpeedRPM =\n    motor.shaft_velocity * 60.0f / (2.0f * PI);\n\n  filteredWheelSpeedRPM +=\n    wheelSpeedFilterAlpha *\n    (rawWheelSpeedRPM - filteredWheelSpeedRPM);\n\n  float wheelSpeedError =\n    wheelSpeedSetpointRPM - filteredWheelSpeedRPM;\n\n  wheelPTerm = wheelKp * wheelSpeedError;\n\n  float wheelSpeedErrorRate =\n    (wheelSpeedError - previousWheelSpeedError) / dt;\n\n  previousWheelSpeedError = wheelSpeedError;\n  wheelDTerm = wheelKd * wheelSpeedErrorRate;\n\n  if (controllerEnabled && pitchValid && gyroValid && wheelKi > 0.0f) {\n    wheelIntegralError += wheelSpeedError * dt;\n\n    float maxWheelIntegralError =\n      wheelIntegralLimitDeg / wheelKi;\n\n    wheelIntegralError = constrain(\n      wheelIntegralError,\n      -maxWheelIntegralError,\n      maxWheelIntegralError\n    );\n  } else if (wheelKi <= 0.0f) {\n    wheelIntegralError = 0.0f;\n  }\n\n  wheelITerm = wheelKi * wheelIntegralError;\n\n  // ==========================================================\n  // ADAPTIVE RECOVERY AUTHORITY\n  //\n  // Normal balancing keeps the small M and W values. If wheel\n  // speed runs away, both authority and slew rate increase\n  // smoothly. They automatically return as speed is bled off.\n  // ==========================================================\n\n  float absoluteWheelSpeedErrorRPM = fabs(wheelSpeedError);\n\n  recoveryFactor = constrain(\n    (absoluteWheelSpeedErrorRPM - recoveryStartErrorRPM) /\n    (recoveryFullErrorRPM - recoveryStartErrorRPM),\n    0.0f,\n    1.0f\n  );\n\n  activeBalanceOffsetLimitDeg =\n    maxBalanceOffsetDeg +\n    recoveryFactor *\n    (emergencyMaxBalanceOffsetDeg - maxBalanceOffsetDeg);\n\n  if (maxBalanceOffsetRateDegS > 0.0f) {\n    activeBalanceOffsetRateDegS =\n      maxBalanceOffsetRateDegS +\n      recoveryFactor *\n      (emergencyBalanceOffsetRateDegS - maxBalanceOffsetRateDegS);\n  } else {\n    activeBalanceOffsetRateDegS = 0.0f;\n  }\n\n  float requestedBalanceOffsetDeg = constrain(\n    wheelLoopDirection * (wheelPTerm + wheelITerm + wheelDTerm),\n    -activeBalanceOffsetLimitDeg,\n    activeBalanceOffsetLimitDeg\n  );\n\n  if (activeBalanceOffsetRateDegS > 0.0f) {\n    float maxOffsetStepDeg = activeBalanceOffsetRateDegS * dt;\n\n    balanceOffsetDeg += constrain(\n      requestedBalanceOffsetDeg - balanceOffsetDeg,\n      -maxOffsetStepDeg,\n      maxOffsetStepDeg\n    );\n  } else {\n    balanceOffsetDeg = requestedBalanceOffsetDeg;\n  }\n\n  effectiveBalanceSetpointDeg =\n    balanceSetpointDeg + balanceOffsetDeg;\n\n  // ==========================================================\n  // INNER ANGLE PID ERROR\n  // ==========================================================\n\n  float rawAngleError =\n    pitchDeg -\n    effectiveBalanceSetpointDeg;\n\n  float angleError =\n    rawAngleError;\n\n  lastRawAngleError =\n    rawAngleError;\n\n  // ==========================================================\n  // SOFT DEADBAND\n  // ==========================================================\n\n  if (\n    fabs(angleError) <=\n    deadbandDeg\n  ) {\n\n    angleError = 0.0f;\n\n  } else {\n\n    angleError -=\n      copysign(\n        deadbandDeg,\n        angleError\n      );\n  }\n\n  lastControlAngleError =\n    angleError;\n\n  // ==========================================================\n  // DEFAULT PID VALUES\n  // ==========================================================\n\n  pTerm = 0.0f;\n  iTerm = 0.0f;\n  dTerm = 0.0f;\n\n  // ==========================================================\n  // CONTROLLER DISABLED\n  // ==========================================================\n\n  if (\n    !controllerEnabled ||\n    !pitchValid ||\n    !gyroValid\n  ) {\n\n    integralError = 0.0f;\n    wheelIntegralError = 0.0f;\n    balanceOffsetDeg = 0.0f;\n    effectiveBalanceSetpointDeg = balanceSetpointDeg;\n    recoveryFactor = 0.0f;\n    activeBalanceOffsetLimitDeg = maxBalanceOffsetDeg;\n    activeBalanceOffsetRateDegS = maxBalanceOffsetRateDegS;\n\n    motor.target = 0.0f;\n\n    return;\n  }\n\n  // ==========================================================\n  // FALL CUTOFF\n  // ==========================================================\n\n  if (\n    fabs(rawAngleError) >\n    maxAllowedAngleErrorDeg\n  ) {\n\n    integralError = 0.0f;\n    wheelIntegralError = 0.0f;\n    balanceOffsetDeg = 0.0f;\n    effectiveBalanceSetpointDeg = balanceSetpointDeg;\n    recoveryFactor = 0.0f;\n    activeBalanceOffsetLimitDeg = maxBalanceOffsetDeg;\n    activeBalanceOffsetRateDegS = maxBalanceOffsetRateDegS;\n\n    motor.target = 0.0f;\n\n    return;\n  }\n\n  // ==========================================================\n  // PROPORTIONAL\n  // ==========================================================\n\n  pTerm =\n    Kp *\n    angleError;\n\n  // ==========================================================\n  // DERIVATIVE\n  //\n  // We use gyro directly instead of differentiating angle.\n  // This is much less noisy.\n  // ==========================================================\n\n  dTerm =\n    -Kd *\n    filteredGyroDegS;\n\n  // ==========================================================\n  // INTEGRAL\n  // ==========================================================\n\n  float pdVoltage =\n    motorDirection *\n    (\n      pTerm +\n      dTerm\n    );\n\n  if (\n    Ki > 0.0f &&\n    angleError != 0.0f &&\n    fabs(pdVoltage) <\n    voltageLimit\n  ) {\n\n    integralError +=\n      angleError *\n      dt;\n\n    float maxIntegralError =\n      integralVoltageLimit /\n      Ki;\n\n    integralError =\n      constrain(\n        integralError,\n        -maxIntegralError,\n        maxIntegralError\n      );\n  }\n\n  else if (\n    Ki <= 0.0f\n  ) {\n\n    integralError = 0.0f;\n  }\n\n  iTerm =\n    Ki *\n    integralError;\n\n  // ==========================================================\n  // TOTAL CONTROL VOLTAGE\n  // ==========================================================\n\n  float controlVoltage =\n    motorDirection *\n    (\n      pTerm +\n      iTerm +\n      dTerm\n    );\n\n  // ==========================================================\n  // OUTPUT LIMIT\n  // ==========================================================\n\n  motor.target =\n    constrain(\n      controlVoltage,\n      -voltageLimit,\n      voltageLimit\n    );\n}\n\n// ============================================================\n// SETUP\n// ============================================================\n\nvoid setup() {\n\n  Serial.begin(115200);\n\n  Serial.setTimeout(10);\n\n  delay(1000);\n\n  Serial.println();\n  Serial.println(\n    \"Starting high-rate reaction-wheel PID...\"\n  );\n\n  // ==========================================================\n  // IMU I2C\n  // ==========================================================\n\n  IMU_Wire.begin(\n    IMU_SDA,\n    IMU_SCL,\n    400000\n  );\n\n  if (\n    !imu.begin(\n      IMU_ADDRESS,\n      IMU_Wire\n    )\n  ) {\n\n    Serial.println(\n      \"ERROR: BNO085 not found at 0x4B.\"\n    );\n\n    while (true) {\n      delay(1000);\n    }\n  }\n\n  if (\n    !enableIMUReports()\n  ) {\n\n    Serial.println(\n      \"ERROR: Could not enable IMU reports.\"\n    );\n\n    while (true) {\n      delay(1000);\n    }\n  }\n\n  Serial.println(\n    \"BNO085 ready.\"\n  );\n\n  // ==========================================================\n  // ENCODER\n  // ==========================================================\n\n  sensor.init();\n\n  sensor.enableInterrupt(\n    encoderISR\n  );\n\n  motor.linkSensor(\n    &sensor\n  );\n\n  // ==========================================================\n  // DRIVER\n  // ==========================================================\n\n  driver.voltage_power_supply =\n    SUPPLY_VOLTAGE;\n\n  driver.voltage_limit =\n    voltageLimit;\n\n  if (!driver.init()) {\n\n    Serial.println(\n      \"ERROR: Driver init failed.\"\n    );\n\n    while (true) {\n      delay(1000);\n    }\n  }\n\n  motor.linkDriver(\n    &driver\n  );\n\n  // ==========================================================\n  // SIMPLEFOC\n  // ==========================================================\n\n  motor.foc_modulation =\n    FOCModulationType::SpaceVectorPWM;\n\n  motor.controller =\n    MotionControlType::torque;\n\n  motor.torque_controller =\n    TorqueControlType::voltage;\n\n  motor.voltage_limit =\n    voltageLimit;\n\n  motor.target =\n    0.0f;\n\n  motor.init();\n\n  motor.initFOC();\n\n  previousControlMicros =\n    micros();\n\n  controllerEnabled = AUTO_START_CONTROLLER;\n\n  Serial.println(\n    \"Motor ready.\"\n  );\n\n  if (AUTO_START_CONTROLLER) {\n    Serial.println(\n      \"Controller automatically enabled; waiting for IMU data.\"\n    );\n  }\n\n  printCommands();\n\n  printSettings();\n}\n\n// ============================================================\n// MAIN LOOP\n// ============================================================\n\nvoid loop() {\n\n  // ==========================================================\n  // RUN FOC AS FAST AS POSSIBLE\n  // ==========================================================\n\n  motor.loopFOC();\n\n  // ==========================================================\n  // READ ALL AVAILABLE IMU PACKETS\n  // ==========================================================\n\n  updateIMU();\n\n  // ==========================================================\n  // UPDATE PID ONLY WHEN NEW GYRO DATA ARRIVES\n  // ==========================================================\n\n  if (jumpState != JUMP_IDLE) {\n\n    runJump();\n  }\n\n  else if (newControlSample) {\n\n    runController();\n  }\n\n  // ==========================================================\n  // APPLY MOST RECENT TORQUE COMMAND\n  // ==========================================================\n\n  motor.move();\n\n  // ==========================================================\n  // SERIAL\n  // ==========================================================\n\n  processSerial();\n\n  // ==========================================================\n  // LOGGING\n  // ==========================================================\n\n  if (loggingEnabled) {\n\n    static uint32_t lastLogMicros = 0;\n\n    uint32_t nowMicros =\n      micros();\n\n    // 100 Hz logging.\n    // Keep this slower than the control loop.\n    if (\n      nowMicros -\n      lastLogMicros >=\n      10000\n    ) {\n\n      lastLogMicros =\n        nowMicros;\n\n      Serial.print(\n        millis()\n      );\n\n      Serial.print(',');\n\n      Serial.print(\n        lastRawAngleError,\n        3\n      );\n\n      Serial.print(',');\n\n      Serial.print(\n        lastControlAngleError,\n        3\n      );\n\n      Serial.print(',');\n\n      Serial.print(\n        filteredGyroDegS,\n        3\n      );\n\n      Serial.print(',');\n\n      Serial.print(\n        filteredWheelSpeedRPM,\n        2\n      );\n\n      Serial.print(',');\n\n      Serial.print(\n        recoveryFactor,\n        3\n      );\n\n      Serial.print(',');\n\n      Serial.print(\n        activeBalanceOffsetLimitDeg,\n        3\n      );\n\n      Serial.print(',');\n\n      Serial.print(\n        activeBalanceOffsetRateDegS,\n        2\n      );\n\n      Serial.print(',');\n\n      Serial.print(\n        balanceOffsetDeg,\n        3\n      );\n\n      Serial.print(',');\n\n      Serial.print(\n        effectiveBalanceSetpointDeg,\n        3\n      );\n\n      Serial.print(',');\n\n      Serial.print(\n        pTerm,\n        3\n      );\n\n      Serial.print(',');\n\n      Serial.print(\n        iTerm,\n        3\n      );\n\n      Serial.print(',');\n\n      Serial.print(\n        dTerm,\n        3\n      );\n\n      Serial.print(',');\n\n      Serial.println(\n        motor.target,\n        3\n      );\n    }\n  }\n}\n"}],"id":"380eb919-43f5-425f-b1f6-cf0c259bc0d7"},{"type":"code","heading":"Matlab Sim","files":[{"filename":"animate_reaction_wheel_box.m","language":"MATLAB","code":"% animate_reaction_wheel_box.m\r\n% Front-view animation of reaction-wheel cube\r\n%\r\n% theta = 0 means cube balanced upright on its corner\r\n\r\n%% ============================================================\r\n% GET SIMULATION DATA\n% =============================================================\n\n% This model also calls this script from StopFcn. That callback runs\n% before simulation results are returned to the calling workspace.\n% Do not start another simulation or animate stale data from a callback.\nif bdIsLoaded('reaction_wheel_box') && ...\n        ~strcmp(get_param('reaction_wheel_box', 'SimulationStatus'), 'stopped')\n    fprintf(['Animation deferred until simulation results are available. ' ...\n        'Run animate_reaction_wheel_box after the simulation returns.\\n']);\n    return;\nend\n\n% Support direct workspace variables or Single Simulation Output.\n% Building/opening the model does not produce simulation results.\nhasDirectResults = exist('theta_out','var') && ...\n    exist('wheel_speed_out','var');\nhasOutputResults = false;\nif exist('out','var') && isa(out, 'Simulink.SimulationOutput')\n    outputNames = who(out);\n    hasOutputResults = all(ismember( ...\n        {'theta_out', 'wheel_speed_out'}, outputNames));\nelseif exist('out','var') && isstruct(out)\n    hasOutputResults = isfield(out, 'theta_out') && ...\n        isfield(out, 'wheel_speed_out');\nend\n\nif ~hasDirectResults && ~hasOutputResults\n    modelFile = fullfile(fileparts(mfilename('fullpath')), ...\n        'reaction_wheel_box.slx');\n    if ~isfile(modelFile)\n        error('ReactionWheel:MissingResults', ...\n            ['No theta_out/wheel_speed_out results or model file found. ' ...\n             'Run the Simulink model first, then run this animation.']);\n    end\n    fprintf('No complete animation results found. Running reaction_wheel_box...\\n');\n    load_system(modelFile);\n    out = sim('reaction_wheel_box', 'ReturnWorkspaceOutputs', 'on');\n    outputNames = who(out);\n    if ~all(ismember({'theta_out', 'wheel_speed_out'}, outputNames))\n        error('ReactionWheel:MissingLoggedSignals', ...\n            ['The simulation did not return theta_out and wheel_speed_out. ' ...\n             'Check the To Workspace block variable names and connections.']);\n    end\n    hasOutputResults = true;\nend\n\n% Use both signals from the same source, rather than mixing old workspace\n% variables with a different simulation output.\nif hasOutputResults\n    thetaData = out.theta_out;\n    wheelData = out.wheel_speed_out;\nelse\n    thetaData = theta_out;\n    wheelData = wheel_speed_out;\nend\n\nif ~isa(thetaData, 'timeseries') || ~isa(wheelData, 'timeseries')\n    error('ReactionWheel:InvalidLogFormat', ...\n        ['theta_out and wheel_speed_out must be timeseries. ' ...\n         'Set both To Workspace blocks to Timeseries and rerun the model.']);\nend\n\r\n%% Extract data\r\n\r\nt = thetaData.Time;\r\ntheta = thetaData.Data;\r\n\r\ntw = wheelData.Time;\r\nwheel_speed = wheelData.Data;\r\n\r\nt = t(:);\r\ntheta = theta(:);\r\n\r\ntw = tw(:);\r\nwheel_speed = wheel_speed(:);\n\nif numel(t) < 2 || numel(tw) < 2 || ...\n        numel(theta) ~= numel(t) || numel(wheel_speed) ~= numel(tw)\n    error('ReactionWheel:InvalidSamples', ...\n        'Each logged signal must be scalar with at least two time samples.');\nend\nif any(~isfinite(t)) || any(~isfinite(tw)) || ...\n        any(~isfinite(theta)) || any(~isfinite(wheel_speed)) || ...\n        any(diff(t) <= 0) || any(diff(tw) <= 0)\n    error('ReactionWheel:InvalidSamples', ...\n        'Logged values must be finite and timestamps must strictly increase.');\nend\n\r\n%% Match wheel speed timestamps to theta timestamps\r\n\r\nif length(tw) ~= length(t) || any(tw ~= t)\r\n\r\n    wheel_speed = interp1( ...\r\n        tw, ...\r\n        wheel_speed, ...\r\n        t, ...\r\n        'linear', ...\r\n        'extrap');\r\n\r\nend\r\n\r\n\r\n%% ============================================================\r\n% ANIMATION SETTINGS\r\n% =============================================================\r\n\r\nfps = 30;\n\n% Set exportVideo = false in the workspace to preview without recording.\n% Override videoFile to choose another destination before running this script.\nif ~exist('exportVideo', 'var')\n    exportVideo = true;\nend\nif ~exist('videoFile', 'var')\n    videoFile = fullfile(fileparts(mfilename('fullpath')), ...\n        'reaction_wheel_simulation.mp4');\nend\n\r\n% Generate animation timestamps\r\nt_anim = (t(1):1/fps:t(end))';\r\n\r\n% Interpolate simulation data\r\ntheta_anim = interp1(t, theta, t_anim);\r\n\r\nwheel_speed_anim = interp1( ...\r\n    t, ...\r\n    wheel_speed, ...\r\n    t_anim);\r\n\r\n\r\n%% Calculate wheel angle\r\n\r\n% wheel_speed is wheel speed RELATIVE to box\r\nwheel_angle_anim = cumtrapz( ...\r\n    t_anim, ...\r\n    wheel_speed_anim);\r\n\r\n\r\n%% ============================================================\r\n% VISUAL DIMENSIONS\r\n% =============================================================\r\n\r\nboxSize = 0.40;      % side length of box\r\n\r\nwheelR = 0.12;       % reaction wheel radius\r\n\r\n% Distance from corner to center of square\r\na = boxSize / sqrt(2);\r\n\r\n\r\n%% ============================================================\r\n% BOX GEOMETRY\r\n% =============================================================\r\n%\r\n% theta = 0:\r\n%\r\n%             /\\\r\n%            /  \\\r\n%           / O  \\\r\n%          /      \\\r\n%         /        \\\r\n%         \\        /\r\n%          \\      /\r\n%           \\    /\r\n%            \\  /\r\n%             *\r\n%\r\n%             ^\r\n%           pivot\r\n%\r\n% Bottom corner is exactly at (0,0)\r\n\r\nboxLocal = [ ...\r\n     0,     0;\r\n     a,     a;\r\n     0,   2*a;\r\n    -a,     a;\r\n     0,     0];\r\n\r\n\r\n% Reaction wheel is located at center of box\r\n\r\nwheelCenterLocal = [0, a];\r\n\r\n\r\n%% ============================================================\r\n% CREATE FIGURE\r\n% =============================================================\r\n\r\nanimationFigure = figure(20);\nclf;\nset(animationFigure, 'Color', 'white', 'Units', 'pixels', ...\n    'Position', [100 100 960 720], 'Resize', 'off', ...\n    'Name', 'Reaction Wheel Simulation', 'NumberTitle', 'off');\n\r\nhold on;\r\naxis equal;\r\ngrid on;\nset(gca, 'Color', 'white', 'XColor', [0.08 0.18 0.20], ...\n    'YColor', [0.08 0.18 0.20], 'GridColor', [0.45 0.55 0.55], ...\n    'FontSize', 12);\n\r\nxlim([-0.55 0.55]);\r\nylim([-0.10 0.75]);\r\n\r\nxlabel('X');\r\nylabel('Y');\r\n\r\n\r\n%% Ground\r\n\r\nplot( ...\r\n    [-1 1], ...\r\n    [0 0], ...\r\n    'k-', ...\r\n    'LineWidth',2);\r\n\r\n\r\n%% Title\r\n\r\ntitleHandle = title('', 'Color', [0.08 0.18 0.20], 'FontSize', 14);\n\r\n\r\n%% ============================================================\r\n% INITIAL BOX\r\n% =============================================================\r\n\r\nboxPlot = plot( ...\r\n    boxLocal(:,1), ...\r\n    boxLocal(:,2), ...\r\n    'Color', [0.08 0.25 0.26], 'LineWidth',4);\n\r\n\r\n%% ============================================================\r\n% REACTION WHEEL\r\n% =============================================================\r\n\r\ncircleAngle = linspace(0,2*pi,100);\r\n\r\nwheelCircle = plot( ...\r\n    wheelCenterLocal(1) + wheelR*cos(circleAngle), ...\r\n    wheelCenterLocal(2) + wheelR*sin(circleAngle), ...\r\n    'Color', [0.32 0.48 0.10], 'LineWidth',3);\n\r\n\r\n%% ============================================================\r\n% WHEEL SPOKES\r\n% =============================================================\r\n\r\nspoke1 = plot([0 0],[0 0],'Color',[0.32 0.48 0.10],'LineWidth',2);\n\r\nspoke2 = plot([0 0],[0 0],'Color',[0.32 0.48 0.10],'LineWidth',2);\n\r\nspoke3 = plot([0 0],[0 0],'Color',[0.32 0.48 0.10],'LineWidth',2);\n\r\nspoke4 = plot([0 0],[0 0],'Color',[0.32 0.48 0.10],'LineWidth',2);\n\r\nspokes = { ...\r\n    spoke1, ...\r\n    spoke2, ...\r\n    spoke3, ...\r\n    spoke4};\r\n\r\n\r\n%% ============================================================\r\n% PIVOT\r\n% =============================================================\r\n\r\nplot( ...\r\n    0, ...\r\n    0, ...\r\n    'ko', ...\r\n    'MarkerSize',10, ...\r\n    'MarkerFaceColor','k');\r\n\r\n\r\n%% ============================================================\r\n% ANIMATION LOOP\n% =============================================================\n\nif exportVideo\n    videoWriter = VideoWriter(videoFile, 'MPEG-4');\n    videoWriter.FrameRate = fps;\n    videoWriter.Quality = 95;\n    open(videoWriter);\nend\n\ntry\nfor k = 1:length(t_anim)\n\r\n    %% Current simulation state\r\n\r\n    th = theta_anim(k);\r\n\r\n    phi = wheel_angle_anim(k);\r\n\r\n    omega = wheel_speed_anim(k);\r\n\r\n\r\n    %% Rotation matrix for box\r\n\r\n    R = [ ...\r\n        cos(th), -sin(th);\r\n        sin(th),  cos(th)];\r\n\r\n\r\n    %% --------------------------------------------------------\r\n    % ROTATE BOX\r\n    % ---------------------------------------------------------\r\n\r\n    boxWorld = (R * boxLocal')';\r\n\r\n    boxPlot.XData = boxWorld(:,1);\r\n\r\n    boxPlot.YData = boxWorld(:,2);\r\n\r\n\r\n    %% --------------------------------------------------------\r\n    % REACTION WHEEL CENTER\r\n    % ---------------------------------------------------------\r\n\r\n    wc = R * wheelCenterLocal';\r\n\r\n\r\n    %% Draw wheel circle\r\n\r\n    wheelCircle.XData = ...\r\n        wc(1) + wheelR*cos(circleAngle);\r\n\r\n    wheelCircle.YData = ...\r\n        wc(2) + wheelR*sin(circleAngle);\r\n\r\n\r\n    %% --------------------------------------------------------\r\n    % WHEEL ROTATION\r\n    % ---------------------------------------------------------\r\n    %\r\n    % phi = wheel rotation relative to box\r\n    %\r\n    % th + phi = absolute wheel rotation\r\n\r\n    wheelAbsoluteAngle = th + phi;\r\n\r\n\r\n    %% Four spoke angles\r\n\r\n    spokeAngles = ...\r\n        wheelAbsoluteAngle + ...\r\n        [0, pi/2, pi, 3*pi/2];\r\n\r\n\r\n    %% Update spokes\r\n\r\n    for j = 1:4\r\n\r\n        sx = ...\r\n            wc(1) + ...\r\n            wheelR*cos(spokeAngles(j));\r\n\r\n        sy = ...\r\n            wc(2) + ...\r\n            wheelR*sin(spokeAngles(j));\r\n\r\n\r\n        spokes{j}.XData = ...\r\n            [wc(1), sx];\r\n\r\n        spokes{j}.YData = ...\r\n            [wc(2), sy];\r\n\r\n    end\r\n\r\n\r\n    %% --------------------------------------------------------\r\n    % TITLE\r\n    % ---------------------------------------------------------\r\n\r\n    titleHandle.String = sprintf( ...\r\n        't = %.2f s    box = %.1f deg    wheel = %.0f RPM', ...\r\n        t_anim(k), ...\r\n        rad2deg(th), ...\r\n        omega*60/(2*pi));\r\n\r\n\r\n    %% --------------------------------------------------------\r\n    % DRAW FRAME\r\n    % ---------------------------------------------------------\r\n\r\n    if exportVideo\n        % Render every frame; video playback timing comes from FrameRate.\n        drawnow;\n        writeVideo(videoWriter, getframe(animationFigure));\n    else\n        drawnow limitrate;\n        pause(1/fps);\n    end\n\nend\ncatch animationError\n    if exportVideo\n        close(videoWriter);\n    end\n    rethrow(animationError);\nend\n\nif exportVideo\n    close(videoWriter);\n    fprintf('Simulation video saved to: %s\\n', videoFile);\nend\n"}],"id":"bfd8e2a3-c09d-4f82-a26a-3ee1056b6baa"}],"cubeContent":{"motivation":"Satellites use reaction wheels in space to orient themselves and maintain stable pointing for optical instruments and communication. Good reaction wheel design allows for precise satellite pointing and reduced mechanical vibration.\n\nMy project is inspired by the Cubli project as well as many others who made similar balancing cubes on youtube. I simplified the project to a single DOF so that I could have a good baseline for balancing along a single axis.","engineeringDetails":"","gallery":[{"src":"Media/IMG_7381.JPEG","alt":"","caption":""},{"src":"Media/IMG_7382.JPEG","alt":"","caption":""},{"src":"Media/IMG_6826.JPEG","alt":"","caption":""}],"videos":[{"title":"","src":"Media/IMG_7393.MOV","poster":"","caption":""}],"parts":[{"name":"MKS ESP32 SimpleFOC Shield v1.0","quantity":"","link":"https://www.amazon.com/dp/B0FGD1T5FD?lv=shuf&channelId=500&plpRedirect=mhFallback","image":"Media/Parts/61MRHm1KDuL._SX522_.jpg","notes":""},{"name":"LiHV 3s 300mah Battery","quantity":"","link":"https://www.amazon.com/GAONENG-300mAh-Battery-Connector-Racing/dp/B07MTDCTCD/ref=sr_1_1?sr=8-1","image":"Media/Parts/61Ll30J0psL._AC_SX466_.jpg","notes":""},{"name":"IPOWER GM4108H-120T Gimbal Motor w/ Encoder","quantity":"","link":"https://shop.iflight.com/ipower-motor-gm4108h-120t-gimbal-motor-with-as5048a-encoder-pro243","image":"Media/Parts/GM4108-encoder.webp","notes":""},{"name":"BNO080 Nine Axis Sensor Module","quantity":"","link":"https://www.amazon.com/EC-Buying-Accelerometer-Gyroscope-Magnetometer/dp/B0CDGZMLPP/ref=sr_1_1?sr=8-1","image":"Media/Parts/41OOgZrdIsL._AC_SX466_.jpg","notes":""}],"cadFiles":[{"name":"Assem154645.SLDASM","filename":"Assem154645.SLDASM","src":"data:application/octet-stream;base64,","description":"","size":327159},{"name":"FLywheel2.SLDPRT","filename":"FLywheel2.SLDPRT","src":"data:application/octet-stream;base64,","description":"","size":188635},{"name":"rxnbox2.SLDPRT","filename":"rxnbox2.SLDPRT","src":"data:application/octet-stream;base64,","description":"","size":492692},{"name":"rxnbox2cc.SLDPRT","filename":"rxnbox2cc.SLDPRT","src":"data:application/octet-stream;base64,","description":"","size":545123}],"sectionOrder":["overview","motivation","technologies","simulation","videos","engineering","content:380eb919-43f5-425f-b1f6-cf0c259bc0d7","content:bfd8e2a3-c09d-4f82-a26a-3ee1056b6baa","photos","cad","parts"]},"profileImage":"data:image/jpeg;base64,"};